int main(){
	int n;
	cin >> n;
	int a,b;
	for(int i = 0;i < n-1;i++){
		cin>>a>>b;
		a--;
		b--;
		edges[a].push_back(b);
		edges[b].push_back(a);
	}
	queue<int> que;
	for(int i = 0;i < n;i++){
		scores[i] = edges[i].size();
		if(scores[i] == 1){//leafnode
			que.push(i);
		}
	}
	int turn = 0;
	int fin = 0;
	while(que.size()){
		// cout << que.size() << endl;
		queue<int> que2 = que;
		queue<int> next;
		int count = 0;
		while(que2.size()){
			int target = que2.front();
			// cout << "now:" << (target+1) << endl;
			que2.pop();
			if(count == 0){
				next.push(target);
				count++;
				continue;
			}
			scores[target] = 0;
			vector<int> nextEdges = edges[target];
			bool attack = false;
			for(int i = 0;i < nextEdges.size();i++){
				int nextTarget = nextEdges[i];
				if(scores[nextTarget] == 0)continue;
				scores[nextTarget]--;
				attack = true;
				// cout << "score:" << scores[nextTarget] << endl;
				if(scores[nextTarget] == 1){
					// cout << "nextTarget:" << (nextTarget+1) << endl;
					next.push(nextTarget);
				}
			}
			if(attack)fin++;
			count++;
		}
		que = next;
		if(fin == n-1)break;
		turn++;
		turn%=2;
	}
	if(n == 3)cout << "First" << endl;
	else if(n == 2)cout << "Second" << endl;
	else if(n == 1)cout << "First" << endl;
	else{
		cout << (!turn?"First":"Second") << endl;
	}
}

