#include <bits/stdc++.h>

using namespace std;

template <typename T>
struct Tree{
	vector<vector<pair<T,int> > > edge;
	int size;

	Tree(int v){
		size = v;
		edge.resize(v);
	}

	void add_edge(int s,int e){
		edge[s].push_back(make_pair(1,e));
		edge[e].push_back(make_pair(1,s));
	}

	void add_edge(T d,int s,int e){
		edge[s].push_back(make_pair(d,e));
		edge[e].push_back(make_pair(d,s));
	}

	int shortpath(int s,int t){
	    int i,j;
			vector<int> mini(size,INT_MAX);
	    priority_queue<pair<int,int>,vector<pair<int,int> >,greater<pair<int,int> > > q;
	    q.push(make_pair(0,s));
	    while(!q.empty()){
	        pair<int,int> p = q.top();
	        q.pop();
	        if(mini[p.second] != INT_MAX){
	            continue;
	        }
	        mini[p.second] = p.first;
	        for(i = 0;i < edge[p.second].size();i++){
	            if(mini[edge[p.second][i].second] == INT_MAX){
	                q.push(make_pair(p.first+edge[p.second][i].first,edge[p.second][i].second));
	            }
	        }
	    }
	    return mini[t];
	}

	vector<vector<pair<T,int> > > oneside(int p){
		vector<vector<pair<T,int> > > onesideedge(size);
		vector<int> visited(size,0);
		queue<int> q;
		visited[p] = 1;
		q.push(p);
		while(!q.empty()){
			p = q.front();q.pop();
			for(int i = 0;i < edge[p].size();i++){
				if(visited[edge[p][i].second] == 0){
					onesideedge[p].push_back(edge[p][i]);
					q.push(edge[p][i].second);
				}
			}
		}
		return onesideedge;
	}

	vector<int> cul_all_distance(int r){
	    vector<int> d(size,-1);
	    d[r] = 0;
	    queue<int> q;
	    q.push(r);
	    while(!q.empty()){
            int p = q.front(); q.pop();
            for(int i = 0;i < edge[p].size();i++){
                if(d[edge[p][i].second] == -1){
                    d[edge[p][i].second] = d[p] + 1;
                    q.push(edge[p][i].second);
                }
            }
	    }
	    return d;
	}

	int maxlength(){
	    vector<int> deepth = cul_all_distance(0);
	    int ma=0,mi=0;
	    for(int i = 0;i < size;i++) if(deepth[i] > ma) { ma = deepth[i]; mi = i;}
	    deepth = cul_all_distance(mi);
	    ma = 0;
	    for(int i = 0;i < size;i++) if(deepth[i] > ma) ma = deepth[i];
	    return ma;
	}
};

