ii depth(int n) {
    int d = 0;
    int x = n;
    FORE (e, edge[n]) if (!used[e]) {
        used[e] = true;
        ii res = depth(e);
        if (res.second > d) {
            d = res.second;
            x = res.first;
        }
    }
    return MP(x,d+1);
}

int dfs(int x) { // x個残っている時に勝てるかどうか
    if (result[x] != -1) return result[x];
    int r = dfs(x-2) & dfs(x-1);
    return result[x] = 1-r;
}

