P visit(int p, int v, vector<vector<int>> &G){
	P r(0, v);
	for (auto e : G[v]){
		if (e != p){
			P t = visit(v, e, G);
			t.first += 1;
			if (r.first < t.first) r = t;
		}
	}
	return r;
}

