        G[a-1].pb(b-1);
        G[b-1].pb(a-1);
    }

    // BFS のためのデータ構造
    vector<int> dist(n, -1); // 全頂点を「未訪問」に初期化
    deque<int> que;

    // 初期条件 (頂点 0 を初期ノードとする)
    dist[0] = 0;
    que.pb(0); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop_front();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.pb(nv);
        }
    }

    // 結果出力 (各頂点の頂点 0 からの距離を見る)
    int cho=0;
    int memo;
    rep(i,n){
      if(cho<dist[i]) memo=i;
      cho=max(cho,dist[i]);
    }

    rep(i,n){
      dist[i]=-1;
    }

    // 初期条件 (頂点 0 を初期ノードとする)
    dist[memo] = 0;
    que.pb(memo); // 0 を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop_front();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.pb(nv);
        }
    }

  cho=0;
  rep(i,n){
    cho=max(cho,dist[i]);
  }

cout << (cho%3==1?"Second":"First") << endl;

}

