    for(int i = 0; i < n - 1; ++i){
        int a, b;
        std::cin >> a >> b;
        add_edge(g, a-1, b-1, 1);
    }
    int x = double_sweep(g).weight%3==2;
    if(x){
        cout<<"First"<<endl;
    }else{
        cout<<"Second"<<endl;

    }
}

