int chokkei(const V<V<int>> &G) {
    int n = G.size();
    V<int> d(n, -1);
    d[0] = 0;
    queue<int> que;
    que.push(0);
    int v;
    while(!que.empty()) {
        v = que.front();
        que.pop();
        for(int u : G[v]) {
            if(d[u] == -1) {
                d[u] = d[v] + 1;
                que.push(u);
            }
        }
    }
    d.assign(n, -1);
    d[v] = 0;
    que.push(v);
    while(!que.empty()) {
        v = que.front();
        que.pop();
        for(int u : G[v]) {
            if(d[u] == -1) {
                d[u] = d[v] + 1;
                que.push(u);
            }
        }
    }
    return d[v];
}

