int dfs(const vector<vector<int>>& G, vector<int>& d, int p, int v) {
   for (int j = 0; j < G[v].size(); j++) {
      int u = G[v][j];
      if (u == p) continue;
      d[u] = d[v] + 1;
      dfs(G, d, v, u);
   }
}
int diameter(const vector<vector<int>>& G) {
   // G: tree
   int N = G.size();
   vector<int> dist(N, 0), dista(N, 0);
   dfs(G, dist, -1, 0);
   int a = max_element(dist.begin(), dist.end()) - dist.begin();
   dfs(G, dista, -1, a);
   return *max_element(dista.begin(), dista.end());
}

