using P = pair<int, int>;
P farthest(vector<VI> g, int now, int par) {
    P ret = { 0,now };
    each(to, g[now]) {
        if (to == par)continue;
        auto a = farthest(g, to, now);
        ++a.first;
        chmax(ret, a);
    }
    return ret;
}

VI memo;
int solve(int n) {
    if (n == 0)return 1;
    if (n == 1)return 0;
    if (memo[n] != -1)return memo[n];
    if (solve(n - 1) == 0 || solve(n - 2) == 0)return memo[n] = 1;
    else return memo[n] = 0;
}

int main() {
    init();

    int n; cin >> n;
    auto g = vec<VI>(n);
    FOR(i, 0, n - 1) {
        int a, b; cin >> a >> b;
        --a, --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    int s = farthest(g, 0, -1).second;
    int d = farthest(g, s, -1).first;
    memo.resize(d + 1, -1);
    cout << (solve(d) == 1 ? "First" : "Second") << "\n";
}

