struct Node {
  bool val;
  vector<Node*> conn;
};


ll f(Node* node, Node* prev) {
  ll m = 0;
  for (ll j=0; j < node->conn.size(); ++j) {
    if (node->conn[j] == prev) continue;
    m = max(m, f(node->conn[j], node));
  }
  return m+1;
}

int main() {
