  for (ll j=0; j < N; ++j) {
    nodes[j] = Node{true, vector<Node*>()};
  }
  for (ll j=0; j < N-1; ++j) {
    ll a, b; cin >> a >> b;
    g[a-1][b-1] = true;
    nodes[a-1].conn.push_back(&nodes[b-1]);
    nodes[b-1].conn.push_back(&nodes[a-1]);
  }
  bool flag = true; ll cur = 0;
  while (flag) {
    ll prev = cur;
    for (ll j = 0; j < N; ++j) {
      if (g[cur][j]) {
        cur = j;
        break;
      }
    }
    if (cur == prev) flag = false;
  }
