class Graph
{
public:
  ll N;
  vector<vector<edge>> G;
  vec his;
  vec dcmax;

  Graph(ll N) : N(N)
  {
    G = vector<vector<edge>>(N, vector<edge>(0));
    his = vec(N, 0);
    dcmax = vec(N, 0);
  }

  void add_Directed_edge(ll from, ll to, ll cost = 1, ll id = 0)
  {
    G[from].push_back(edge({to, cost, id}));
  }

  void add_Undirected_edge(ll v1, ll v2, ll cost = 1, ll id = 0)
  {
    add_Directed_edge(v1, v2, cost, id);
    add_Directed_edge(v2, v1, cost, id);
  }

  mat waeshall_floyd()
  {
    mat d(N, vec(N, INF));
    REP(i, N)
    d[i][i] = 0;
    REP(i, N)
    for (edge e : G[i])
    {
      d[i][e.to] = min(d[i][e.to], e.cost);
    }
    REP(k, N)
    REP(i, N)
    REP(j, N)
    d[i][j] = min(d[i][j], d[i][k] + d[k][j]);

    return d;
  }
  vec dikstra(ll x)
  {
    vec distance(N, INF);
    distance[x] = 0;
    PQG<pa> pque;
    pque.push(make_pair(0, x));

    while (!pque.empty())
    {

      auto pq = pque.top();
      pque.pop();
      for (auto e : G[pq.second])
      {
        ll d = distance[pq.second] + e.cost;
        if (d < distance[e.to])
        {
          distance[e.to] = d;
          pque.push(make_pair(d, e.to));
        }
      }
    }

    return distance;
  }

  ll dfs(ll x, ll d)
  {
    vec cand;
    if (his[x] == 1)
      return d;
    his[x] = 1;

    PQ<ll> pque;
    ll res = 0;
    for (edge e : G[x])
    {
      auto x = dfs(e.to, d + 1);
      if (d == 0)
        cand.PB(x);
      chmax(res, x);
    }
    if (d == 0)
    {
      sort(begin(cand), end(cand));
      if (cand.size() == 1)
        return cand[0];
      else
        return cand[0] + cand[1];
    }
    return res;
  }
};

