int dl[]={-1,0,1,0,-1,1,1,-1};
int dc[]={0,1,0,-1,1,1,-1,-1};

bool interior(int i, int j){
    return i>=1&&j>=1&&i<=n&&j<=m;
}

long double lee(int xs, int ys, int xf, int yf){
    queue<pair<int,int>>q;
    q.push(make_pair(xs,ys));
    uz[xs][ys] = turn;
    if (xs == xf && ys == yf){
        return 0;
    }
    for (int i=1;i<=n;++i){
        for (int j=1;j<=m;++j){
            dm[i][j] = inf;
        }
    }
    dm[xs][ys] = 0;
    while (!q.empty()){
        auto act = q.front();
        q.pop();
        int i = act.first;
        int j = act.second;
        long double cs = dm[i][j];
        for (int k=0;k<8;++k){
            if (!interior(i+dl[k],j+dc[k])){
                continue;
            }
            if (a[i+dl[k]][j+dc[k]]=='#'){
                continue;
            }
            long double add = cs + 1.0;
            if (k >= 4){
                add = cs + sqrt(2.0);
            }
            if (uz[i+dl[k]][j+dc[k]]==turn && dm[i+dl[k]][j+dc[k]] < add){
                continue;
            }
            uz[i+dl[k]][j+dc[k]] = turn;
            dm[i+dl[k]][j+dc[k]] = add;
            q.push(make_pair(i+dl[k],j+dc[k]));
        }
    }
    if (dm[xf][yf] == inf){
        return -1.0;
    }
    return dm[xf][yf];
}

