void dfs1(int k, int lst, int dist){
    if (dist > maxxdist){
        maxxdist = dist;
        node = k;
    }
    for (auto x:g[k]){
        if (x == lst){
            continue;
        }
        dfs1(x, k, dist+1);
    }
}
void dfs2(int k, int lst){
    if (good){
        return;
    }
    if (k == n1){
        while (!nodes.empty()){
            diameter.push_back(nodes.top());
            ond[nodes.top()] = true;
            nodes.pop();
        }
        good = true;
        return;
    }
    for (auto x:g[k]){
        if (x == lst){
            continue;
        }
        nodes.push(x);
        dfs2(x, k);
        nodes.pop();
        if (good){
            return;
        }
    }
}

void dfs3(int k, int lst){
    ++cnt;
    for (auto x:g[k]){
        if (x == lst || ond[x]){
            continue;
        }
        dfs3(x, k);
    }
}

