void dfs(int s, int len, int from) {
    if (g[s].size() == 1 && len > 0) {
        if (len > maxlen) {
            maxs = s;
            maxlen = len;
        }
        return;
    } else {
        len++;
        rep(i, g[s].size()) {
            int to = g[s][i];
            if (to == from) {
                continue;
            }
            dfs(to, len, s);
        }
    }
    return;
}

