struct Tree{
	int V;
	vector<int> G[200010];
	int dist[2][200010];
	void dfs(int v,int p,int t){
		dist[t][v] = dist[t][p]+1;
		for(int u: G[v]){
			if(u == p)continue;
			dfs(u,v,t);
		}
	}
	int calc_dia(){
		int x = 1;
		dist[0][0] = -1;
		dfs(x,0,0);
		int y = 1;
		for(int i = 1 ; i <= V ; i ++){
			if(dist[0][i] > dist[0][y])y = i;
		}
		dist[1][0] = -1;
		dfs(y,0,1);
		int ret = 0;
		for(int i = 1 ; i <= V ; i ++){
			ret = max( ret , dist[1][i] );
		}
		return ret;
	}
}tree;

int main(){
	int n,a,b;
	scanf("%d",&n);
	tree.V = n;
	rep(i,n-1){
		scanf("%d%d",&a,&b);
		tree.G[a].pb(b);
		tree.G[b].pb(a);
	}

	int d = tree.calc_dia();
	if(d%3 == 1)puts("Second");
	else puts("First");
}

