template <class T>
bool chmax(T &a, const T &b) { return (a < b) ? (a = b, 1) : 0; }
template <class T>
bool chmin(T &a, const T &b) { return (b < a) ? (a = b, 1) : 0; }

template <typename T = int>
struct WeightedTree {
    vector<vector<pair<T, int>>> edges;

    WeightedTree(int n_) : edges(n_){};

    void addEdge(T from, T to, int weight) {
        edges[from].emplace_back(to, weight);
        edges[to].emplace_back(from, weight);
    }

    // return {cost, farthest node idx} from idx
    pair<T, int> dfs(int idx, int prev) {
        pair<T, int> ret(0, idx);
        for (auto &edge : edges[idx]) {
            if (edge.first == prev)
                continue;
            auto cost = dfs(edge.first, idx);
            cost.first += edge.second;
            ret = max(ret, cost);
        }
        return ret;
    }

    T diameter() {
        auto p = dfs(0, -1);
        auto q = dfs(p.second, -1);
        return q.first;
    }
};

int main() {
    int N;
    cin >> N;
    WeightedTree<int> t(N);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        t.addEdge(a, b, 1);
    }
    int diameter = t.diameter();
    if (diameter % 3 == 1) {
        cout << "Second" << endl;
    } else
        cout << "First" << endl;
    return 0;
}

