const int inf = (int)1.05e9;

pair<int, int> compute_distant_vertex(graph& g, int from)
{
	vector<int> dist(g.size(), inf);
	queue<pair<int,int>> q;
	int ans_v = from;

	q.push({from, 0});

	while(!q.empty()) {

		int v = q.front().first;
		int d = q.front().second;
		q.pop();

		if(dist[v] <= d) {
			continue;
		}
		dist[v] = d;
		if(dist[v] > dist[ans_v]) {
			ans_v = v;
		}

		for(auto& w : g[v]) {
			q.push({w, d + 1});
		}
	}

	return {ans_v, dist[ans_v]};
}

int compute_diameter(graph& g)
{
	auto d1 = compute_distant_vertex(g, 0);
	auto d2 = compute_distant_vertex(g, d1.first);
	return d2.second;
}

