    auto farthest = [&](auto&& f, int s)->pair<int, int> {
        VI dis(n, INF);
        dis[s] = 0;
        queue<int> bfs;
        bfs.push(s);
        while (!bfs.empty()) {
            int now = bfs.front();
            bfs.pop();
            each(to, g[now]) {
                if (!chmin(dis[to], dis[now] + 1))continue;
                bfs.push(to);
            }
        }

        pair<int, int> ret = { s,0 };
        FOR(i, 0, n)if (chmax(ret.second, dis[i])) {
            ret.first = i;
        }
        return ret;
    };

    int s = farthest(farthest, 0).first;
    int d = farthest(farthest, s).second;

    print(d % 3 == 1 ? "Second" : "First");
}

