int N;
vector<vector<int> > G;
vector<int> dp;

pair<int,int> farthest(int i0)
{
  vector<int> d(N,-1);
  d[i0] = 0;
  deque<int> dq;
  dq.push_back(i0);

  while( not dq.empty() )
    {
      int u = dq.front();
      dq.pop_front();

      for( auto id : G[u] )
	{
	  if( d[id] == -1 )
	    {
	      dq.push_back(id);
	      d[id] = d[u] + 1;
	    }
	}
    }

  int i1 = 0;
  FOR(i,1,N)
    {
      if( d[i1] < d[i] )
	{
	  i1 = i;
	}
    }

  return make_pair(i1,d[i1]);

}

int fwin( int i )
{
  if( dp[i] != -1 )
    {
      return dp[i];
    }

  if( i == 0 )
    {
      return dp[0] = 1;
    }

  int f1 = fwin(i-1);
  int f2;

  if( 2 <= i )
    {
      f2 = fwin(i-2);
    }
  else
    {
      f2 = 1;
    }

  if( f1 == 0 or f2 == 0 )
    {
      return dp[i] = 1;
    }
  else
    {
      return dp[i] = 0;
    }

}



signed main()
{
  IOS; /* making cin faster */
  SCAND(N);
  G.resize(N);
  dp.assign(N,-1);
  REP(_,N-1)
    {
      int a,b;
      SCAND2(a,b);
      -- a;
      -- b;
      G[a].push_back(b);
      G[b].push_back(a);
    }

  int u = farthest(0).first;
  pair<int,int> r = farthest(u);
  int dist = r.second;
  if( fwin(dist) == 1 )
    {
      puts("First");
    }
  else
    {
      puts("Second");
    }


}

