		auto cost = dfs(next, now, G);
		cost.first++;
		res = max(res, cost);
	}
	return res;
}

ll tree_diameter(Graph &G){
	auto p = dfs(0, -1, G);
	auto q = dfs(p.second, -1, G);
	// (p.second, q.second) is the diameter
	return q.first;
}

