vector<int> edge[200001];
bool used[200001];
int h[200001], par[200001];
vector<int> child[200001];

void dfs(int i){
  used[i] = true;
  for(auto e: edge[i]){
    if(!used[e]){
      par[e] = i;
      h[e] = h[i] + 1;
      dfs(e);
      child[i].pb(e);
    }
  }
}

