    edge[a].pb(b);
    edge[b].pb(a);
  }
  dfs(0);
  int maxi = 0;
  int at = 0;
  rep(i, n){
    if(maxi < h[i]){
      at = i;
      maxi = h[i];
    }
  }
  rep(i, n){
    used[i] = false;
    child[i].clear();
    par[i] = i;
  }
  h[at] = 0;
  dfs(at);
  maxi = 0;
