	FOR(i,0,N-1){
		ll a,b;
		cin >> a >> b;
		a--;
		b--;
		DT.add_edge(a,b,1);
	}
	ll td = DT.treeDiameter();
	if(td%3==1){
		cout << "Second" << endl;
	}else{
		cout << "First" << endl;
	}


}

