P diam(vector<vector<ll>> &es, vector<int> &visited, ll now) {
	if (visited[now])
		return P(-10, -1);
	visited[now] = true;
	P ret = P(-1, now);
	for (auto &e : es[now]) {
		ret = max(ret, diam(es, visited, e));
