struct Edge {
    int from {0};
    int to {0};
};

constexpr int InvalidPoint = -1;

int main(int argc, char* argv[]) {
    int n = 0;
    std::string line;
    std::getline(std::cin, line);
    std::istringstream isa(line);
    isa >> n;

    std::vector<int> points(n, 0);
    std::unordered_map<int, int> pointCounts(0);
    std::vector<Edge> edges;
    for(int i=0; i<n; ++i) {
        points.at(i) = i;
    }

    for(int i=0; i<(n-1); ++i) {
        std::getline(std::cin, line);
        std::istringstream isb(line);
        int a = InvalidPoint;
        int b = InvalidPoint;
        isb >> a >> b;

        // 0-based
        --a;
        --b;
        Edge edge {a, b};
        edges.push_back(edge);
        pointCounts[a] += 1;
        pointCounts[b] += 1;
    }

    bool turn = false;
    for(;;) {
        if (points.size() <= 1) {
            break;
        }

        std::vector<int> newPoints;
        std::unordered_map<int, bool> removedPoints;
        size_t count = 0;
        for(const auto& point : points) {
            count += (pointCounts[point] == 1) ? 1 : 0;
        }

        auto pickUpOne = ((count % 2) == 0);
        for(const auto& point : points) {
            auto ct = pointCounts[point];
            auto keep = false;
            if (ct > 1) {
                keep = true;
            } else if ((ct == 1) && pickUpOne) {
                keep = true;
                pickUpOne = false;
            }

            if (keep) {
                newPoints.push_back(point);
            } else {
                removedPoints[point] = true;
            }
        }

        for (auto&& edge : edges) {
            if (removedPoints.find(edge.from) != removedPoints.end()) {
                auto point = edge.to;
                edge.from = InvalidPoint;
                edge.to = InvalidPoint;
                if (point != InvalidPoint) {
                    pointCounts[point] -= 1;
                }
            } else if (removedPoints.find(edge.to) != removedPoints.end()) {
                auto point = edge.from;
                edge.from = InvalidPoint;
                edge.to = InvalidPoint;
                if (point != InvalidPoint) {
                    pointCounts[point] -= 1;
                }
            }
        }

        std::swap(points, newPoints);
        turn = !turn;
    }

    std::cout << (turn ? "Second" : "First") << "\n";
    return 0;
}

