typedef vector<vi> vvi;

#define INF (1e9)

int N;

int getDiameter(vi A, vi B) {
    vi A_ = A;
    vi B_ = B;

    // bfs
    queue<int> q;
    q.push(0);

    int now;
    while (!q.empty()) {
        queue<int> next;
        while (!q.empty()) {
            now = q.front();
            q.pop();

            for (int i = A_.size() - 1; i >= 0; i--) {
                if (A_[i] == now) {
                    next.push(B_[i]);
                    A_.erase(A_.begin() + i);
                    B_.erase(B_.begin() + i);
                } else if (B_[i] == now) {
                    next.push(A_[i]);
                    A_.erase(A_.begin() + i);
                    B_.erase(B_.begin() + i);
                }
            }
        }
        q = next;
    }

    int deepNode = now;

    A_ = A;
    B_ = B;

    // bfs
    while (!q.empty()) q.pop();
    q.push(deepNode);

    int depth = -1;
    while (!q.empty()) {
        depth++;
        queue<int> next;
        while (!q.empty()) {
            now = q.front();
            q.pop();

            for (int i = A_.size() - 1; i >= 0; i--) {
                if (A_[i] == now) {
                    next.push(B_[i]);
                    A_.erase(A_.begin() + i);
                    B_.erase(B_.begin() + i);
                } else if (B_[i] == now) {
                    next.push(A_[i]);
                    A_.erase(A_.begin() + i);
                    B_.erase(B_.begin() + i);
                }
            }
        }
        q = next;
    }

    return depth;
}

int main() {
    cin >> N;

    vi A(N - 1), B(N - 1);
    for (int i = 0; i < N - 1; i++) {
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
    }

    int d = getDiameter(A, B);

    if (d % 3 == 1) {
        cout << "Second" << endl;
    } else {
        cout << "First" << endl;
    }
    return 0;
}

