pair<int, int> dfs(vec<vec<int> > t, int s)
{
  queue<int> q;
  q.push(s);
  vec<int> dp(t.size(), 0);
  while(q.size()) {
    int p = q.front();
    q.pop();
    rep(i, t[p].size()) {
      if (dp[t[p][i]]) continue;
      dp[t[p][i]] = dp[p] + 1;
      q.push(t[p][i]);
    }
  }
  int m = 0;
  rep(i, dp.size()) {
    if (dp[i] > dp[m]) m = i;
  }
  return make_pair(m, dp[m]);
}

