using P = pair<int, int>;
P farthest(vector<VI>& g, int now, int par) {
    P ret = { 0,now };
    each(to, g[now]) {
        if (to == par)continue;
        auto a = farthest(g, to, now);
        ++a.first;
        chmax(ret, a);
    }
    return ret;
}

