using namespace std;

int main() {
    int N;
    cin >> N;

    Graph<> tree(N);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        tree.span(u, v);
        tree.span(v, u);
    }

    using Top2 = std::pair<int, int>;
    std::function<Top2(Top2, Top2)> merge = [](Top2 p, Top2 q) {
        if (p.second > q.first) return p;
        if (q.second > p.first) return q;
        if (p.first > q.first) return Top2(p.first, q.first);
        return Top2(q.first, p.first);
    };
    std::function<Top2(Top2, Edge<int> e)> promote = [](Top2 p, Edge<int> e) {
        return p.first < 0 ? Top2(e.cost, -1) : Top2(p.first + e.cost, -1);
    };

    // Data     : 最も遠い葉までの距離 異なる部分木から上位2つ
    // Merger   : 大きい方2つを取る (id = (-1, -1))
    // Promoter : 一番大きいやつにcostを足す(1つの部分木からは1つの葉しか選べないことに注意)
    ReRooting<int, Top2> dp(tree, Top2(-1, -1), merge, promote);

    int ans = 0;
    for (const auto& p : dp.data) ans = std::max(ans, p.first + p.second);

    cout << (ans % 3 == 1 ? "Second" : "First") << endl;
    return 0;
}

