class Tree{
public:
    int N;
    vector<vector<int>> G;

    Tree(int n){
        N = n;
        G.resize(N);
    }

    void make_edge(int s, int t){
        G[s].push_back(t);
        G[t].push_back(s);
    }

    int find_leaf(){
        int n = 0, par = -1;
        while(true){
            //cout << n << " " << par << endl;
            if(G[n].size() == 1) return n;
            else {
                if(G[n][0] == par){
                    par = n;
                    n = G[n][1];
                } else {
                    par = n;
                    n = G[n][0];
                }
            }
        }
    }

    int dfs(int n, int par){
        int mx = 1;
        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par){
                mx = max(mx, dfs(nx, n) + 1);
            }
        }

        return mx;
    }

    int tyokkei(){
        int n = find_leaf();
        //cout << "leaf = " << n << endl;
        return dfs(n, -1);
    }
};

int main(){
    int N;
    cin >> N;

    if(N == 1){
        cout << "First" << endl;
        return 0;
    }

    Tree tr = Tree(N);
    for(int i = 0; i < N - 1; i++){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        tr.make_edge(a, b);
    }

    int x = tr.tyokkei();
    //cout << "x = " << x << endl;

    bool dp[N + 1];
    dp[1] = true;
    dp[2] = false;
    for(int i = 3; i <= N; i++){
        if(dp[i - 1] && dp[i - 2]) dp[i] = false;
        else dp[i] = true;
    }

    if(dp[x]){
        cout << "First" << endl;
    } else {
        cout << "Second" << endl;
    }

    return 0;
}

