pii visit(int p, int v, const vector<vi> &g) {
    pii r(0, v);
    for(int e : g[v]) if (e != p) {
            pii t = visit(v, e, g);
            t.first += 1;
            if (r.first < t.first) r = t;
        }
    return r;
}
int diameter(const vector<vi> &g) {
    pii r = visit(-1, 0, g);
    pii t = visit(-1, r.second, g);
    return t.first; // (r.second, t.second) is farthest pair
}

