int far_away(int s){
  fill(f,0);
  temp=0;
  int res;
  std::priority_queue<pi,std::vector<pi>,std::greater<pi> > q;  
  q.push(mp(0,s));
  while(!q.empty()){
    pi p=q.top();q.pop();
    int F=p.first,S=p.second;
    f[S]=true;
    int es=edge[S].size();
    rep(i,es){
      int e=edge[S][i];
      if(!f[e]){
	q.push(mp(F+1,e));
	if(temp<=F+1){
	  temp=F+1;
	  res=e;
	}
      }
    }
  }
  return res;
}
int diameter(){
  far_away(far_away(0));
  return temp+1;
}
