  for (int i = N - 1; 0 <= i; --i) {
    if (T[i] == 'U')
      v.second = min(H, v.second + 1);
    else if (T[i] == 'D')
      v.first = max(1LL, v.first - 1);
    else if (T[i] == 'L')
      h.second = min(W, h.second + 1);
    else if (T[i] == 'R')
      h.first = max(1LL, h.first - 1);

    if (S[i] == 'U')
      ++v.first;
    else if (S[i] == 'D')
      --v.second;
    else if (S[i] == 'L')
      ++h.first;
    else if (S[i] == 'R')
      --h.second;

    if (h.second < h.first || v.second < v.first) return false;
  }

  bool can_stay = (v.first <= s.first && s.first <= v.second) && (h.first <= s.second && s.second <= h.second);

  return can_stay;
}

