        -- a;
        -- b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    vector<int> dist;
    shortestPath(edges, 0, dist);
    int pos = max_element(dist.begin(), dist.end()) - dist.begin();
    shortestPath(edges, pos, dist);
    int len = *max_element(dist.begin(), dist.end());

    if(len % 3 == 1)
        cout << "Second" << endl;
    else
        cout << "First" << endl;

    return 0;
}

