void solve(__attribute__((unused)) bool read) {
  int n;
  cin >> n;
  vector<vector<int>> g(n);
  for (int i = 1; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int st = 0;
  int res = 0;
  for (int w = 0; w < 2; ++w) {
    vector<int> dist(n, -1);
    dist[st] = 0;
    queue<int> q;
    q.push(st);
    while (!q.empty()) {
      int v = q.front();
      q.pop();
      for (int to : g[v]) {
        if (dist[to] == -1) {
          dist[to] = dist[v] + 1;
          q.push(to);
        }
      }
    }
    int max_id = 0;
    for (int i = 0; i < n; ++i) {
      if (dist[i] > dist[max_id]) {
        max_id = i;
      }
    }
    st = max_id;
    res = dist[max_id];
  }
  if (res % 3 == 1) {
    cout << "Second\n";
  } else {
    cout << "First\n";
  }

}

