int n, cnt, head[MAXN], maxlen;

struct Edge {int next, to;} edge[MAXN*2];

void addedge(int from, int to)
{
    edge[++cnt].next=head[from];
    edge[cnt].to=to;
    head[from]=cnt;
}

int dfs(int x, int fa)
{
    int len1=0, len2=0;
    for(int i=head[x]; i; i=edge[i].next)
    {
        int to=edge[i].to;
        if(to==fa) continue;
        int len=dfs(to, x)+1;
        if(len>len1) len2=len1, len1=len;
        else if(len>len2) len2=len;
    }
    if(len1+len2+1>maxlen) maxlen=len1+len2+1;
    return len1;
}

