vector<vector<int> > edges;
int ans = 0;

int dfs(int v, int p){
	vector<int> ends = {0, 0};
	for(int w : edges[v]){
		if(w == p) continue;
		int x = dfs(w, v);
		ends.push_back(1+x);
	}
	sort(ends.begin(), ends.end());
	reverse(ends.begin(), ends.end());
	ans = max(ans, ends[0] + ends[1]);
	return ends[0];
}

