int main() {
	int n, a, b;
	cin >> n;

	if (n == 1) {
		cout << "First" << endl;
		return 0;
	}

	vector<vector<int>> connect(n + 1, vector<int>());
	for (int i = 0; i < n - 1; i++) {
		cin >> a >> b;
		connect[a].emplace_back(b);
		connect[b].emplace_back(a);
	}


	vector<bool> used(n + 1, false);
	queue<int> que;
	used[1] = true;
	que.push(1);

	int node1 = -1;
	while (!que.empty()) {
		auto x = que.front();
		// printf("x1 %d\n", x);
		que.pop();

		for (auto y: connect[x]) {
			if (used[y]) {
				continue;
			}
			used[y] = true;
			que.push(y);
			node1 = y;
		}
	}

	// printf("node %d\n", node1);


	queue<PII> que2;
	int dist = 0;
	used.assign(n + 1, false);
	used[node1] = true;
	que2.push(make_pair(node1, 0));
	while (!que2.empty()) {
		auto p = que2.front();
		que2.pop();
		int x = p.first;
		dist = max(dist, p.second);

		// printf("p %d %d\n", p.first, p.second);

		for (auto y: connect[x]) {
			if (used[y]) {
				continue;
			}
			used[y] = true;
			que2.push(make_pair(y, p.second + 1));
		}
	}
	// printf("dist %d\n", dist);

	// v1 = win
	// v2 = lose
	// vi2 = (vi1 == lose || vi0 == lose) ? win : lose
	// win lose win が繰り返す

	string ans = (dist + 1) % 3 == 2 ? "Second" : "First";
	cout << ans << endl;


	return 0;
}

