const int INF = 1e8;

class Tree {
	int n;
	void bfs(int s, vector<int>& dis, vector<int>& pre) {
		queue<int> q;
		dis[s] = 0;
		q.emplace(s);

		while (not q.empty()) {
			int u = q.front();
			q.pop();
			for (auto e : g[u]) {
				if (dis[e.first] == INF) {
					dis[e.first] = dis[u] + e.second;
					pre[e.first] = u;
					q.emplace(e.first);
				}
			}
		}
	}

  public:
	vector<vector<pair<int, int>>> g;
	vector<int> path;
	Tree(int n) : n(n), g(n) {}
	void addEdge(int a, int b, int c = 1) {
		g[a].emplace_back(b, c);
		g[b].emplace_back(a, c);
	}
	int diameter() {
		vector<int> pre(n, -1), dis(n, INF);
		bfs(0, dis, pre);

		int maxi = 0, tgt = 0;
		rep(i, n) {
			if (dis[i] == INF) continue;
			if (maxi < dis[i]) {
				maxi = dis[i];
				tgt = i;
			}
		}

		pre = vector<int>(n, -1);
		dis = vector<int>(n, INF);
		bfs(tgt, dis, pre);
		maxi = 0; // tgt$B$+$i:G$b1s$$@\E@$N5wN%(Bmaxi
		rep(i, n) {
			if (dis[i] == INF) continue;
			if (maxi < dis[i]) {
				maxi = dis[i];
				tgt = i;
			}
		}

		int pos = tgt;
		while (pre[pos] != -1) {
			path.emplace_back(pre[pos]);
			pos = pre[pos];
		}
		return maxi;
	}
	pair<int, int> center() {
		if (path.empty()) diameter();

		assert(path.size() == 0 and "path is empty");
		if (path.size() % 2 == 0) {
			return make_pair(path[path.size() / 2 - 1], path[path.size() / 2]);
		} else {
			return make_pair(path[path.size() / 2], -1);
		}
	}
};

