struct Edge {
public:
	int from, to, cost;
	Edge() {}
	Edge(int _from, int _to, int _cost) {
		from = _from;
		to = _to;
		cost = _cost;
	}
};

typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
typedef pair<int, int> P;

vi dijkstra(int s, Graph G) {//s=>始点
	priority_queue<P, vector<P>, greater<P> > que;
	vi D(SZ(G), INF);
	D[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if (D[v] < p.first)continue;

		for (Edge e : G[v]) {
			if (D[e.to] > D[v] + e.cost) {
				D[e.to] = D[v] + e.cost;
				que.push(P(D[e.to], e.to));
			}
		}
	}
	return D;
}

Edge solve(Graph G) {
	vi d = dijkstra(0, G);
	int mind = 0;
	int v = 0;
	REP(i, SZ(G)) {
		if (i == 0)continue;
		if (d[i] > mind) {
			mind = d[i];
			v = i;
		}
	}
	d = dijkstra(v, G);
	mind = 0;
	int vv = 0;
	REP(i, SZ(G)) {
		if (i == v)continue;
		if (d[i] > mind) {
			mind = d[i];
			vv = i;
		}
	}
	return Edge(v, vv, d[vv]);
}

