	REP(i, N - 1) {
		int a, b;
		cin >> a >> b;
		a--;b--;
		G[a].push_back(Edge(a, b, 1));
		G[b].push_back(Edge(b, a, 1));
	}
	Edge e = solve(G);
	int ans = (e.cost + 1) / 2;
	if (ans%2 == 1) {
		cout << "First" << endl;
	}
	else {
		cout << "Second" << endl;
	}
	return 0;
}

