ll diameter_of_tree(Graph& tree){
    ll dM = 0, vM = 0, v1, v2;

    auto dfs = [&](auto dfs, ll src, ll par, ll d) -> void{
        if (chmax(dM, d)) vM = src;
        for (auto& e: tree[src]){
            if (e.to == par) continue;
            dfs(dfs, e.to, src, d + 1);
        }
    };
    dfs(dfs, 0, -1, 0); v1 = vM;
    dfs(dfs, vM, -1, 0); v2 = vM;
    return dM;
}

