void solve() {
    //const i64 mod = 1'000'000'007;
    i64 N;
    cin >> N;

    vector<vector<i64>> graph(N);
    rep(i,0,N-1){
        i64 a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }

    vector<i64> depth(N),height(N);
    function<void(i64,i64,i64)> calc_depth=[&](i64 u,i64 p,i64 d){
        depth[u]=d;
        for(auto v:graph[u]){
            if(v==p) continue;
            calc_depth(v,u,d+1);
            chmax(height[u],height[v]+1);
        }
    };
    calc_depth(0,-1,0);

    print(depth);
    print(height);

    vector<i64> f(N);
    function<void(i64,i64,i64)> calc_f=[&](i64 u,i64 p,i64 up){
        f[u]=up;
        for(auto v:graph[u]){
            if(v==p) continue;
            chmax(f[u],height[v]+1);
        }
        if(graph[u].empty()) return;
        vector<i64> l(graph[u].size()),r(graph[u].size());
        if(graph[u][0]!=p) l[0]=height[graph[u][0]]+1;
        if(graph[u].back()!=p) r[graph[u].size()-1]=height[graph[u].back()]+1;
        rep(i,1,graph[u].size()){
            i64 v=graph[u][i];
            l[i]=l[i-1];
            if(v==p) continue;
            chmax(l[i],height[v]+1);
        }
        for(i64 i=i64(graph[u].size())-2; i>=0; --i){
            i64 v=graph[u][i];
            r[i]=r[i+1];
            if(v==p) continue;
            chmax(r[i],height[v]+1);
        }
        rep(i,0,graph[u].size()){
            i64 v=graph[u][i];
            if(v==p) continue;
            calc_f(v,u,max({up,i==0?0:l[i-1],i==graph[u].size()-1?0:r[i+1]})+1);
        }
    };
    calc_f(0,-1,0);

    i64 x=0;
    rep(i,0,N) chmax(x,f[i]);

    x%=3;
    cout << (x==1?"Second":"First") << endl;
}

