vector<vector<int> > g;

P bfs(int s){
    vector<int> dist(g.size(),-1);
    queue<int> que;
    que.push(s);
    dist[s] = 0;
    while(!que.empty()){
        int v = que.front();
        que.pop();
        for(auto u : g[v]){
            if(dist[u] != -1) continue;
            dist[u] = dist[v] + 1;
            que.push(u);
        }
    }
    int dmax = 0, idx = -1;
    for(int i=0;i<int(g.size());i++){
        if(dist[i] > dmax){
            dmax = dist[i];
            idx = i;
        }
    }
    return P(idx, dmax);
}

