struct item{
    int i = 0;
    int d = 0;
    item(int i, int d){
        this->i = i;
        this->d = d;
    }
};

int main(){
    int n;
    int d[200001];
    vector<int> g[200001];

    scanf("%d", &n);
    for(int i = 0; i < n - 1; i++){
        int a;
        int b;
        scanf("%d %d", &a, &b);
        d[a]++;
        d[b]++;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    queue<item> q;
    bool b[200001];

    for(int i = 0; i < n; i++){
        b[i] = false;
        if(d[i] == 1){
            q.push(item(i, 0));
            break;
        }
    }

    int l = 0;
    while(!q.empty()){
        item t = q.front();
        q.pop();
        b[t.i] = true;
        l = t.d;
        for(int i = 0; i < g[t.i].size(); i++){
            if(!b[g[t.i][i]]){
                q.push(item(g[t.i][i], t.d + 1));
            }
        }
    }

    if(l % 3 == 1){
        printf("Second");
    }else{
        printf("First");
    }

    return 0;
}

