template <typename T>
class TreeNode{
private:
    T m_val;
    TreeNode<T> *m_parent = nullptr;
    set<TreeNode<T>*> m_children;

public:
    TreeNode(T val){
        m_val = val;
        m_parent = nullptr;
    }

    ~TreeNode(){
        for(auto& c : m_children){
            delete c;
        }
    }

    void Print(int d=0){
        cout<<setw(d+1)<<m_val<<endl;
        for(auto c : m_children){
            c->Print(d+1);
        }
    }

    T GetValue(){ return m_val;}

    TreeNode* GetRoot(){
        auto node = this;
        while(node->m_parent!=nullptr){
            node = node->m_parent;
        }
        return node;
    }

    TreeNode* AddNode(T val){
        auto child = new TreeNode<T>(val);
        child->m_parent = this;
        m_children.insert(child);
        return child;
    }

    bool IsRoot(){ return m_parent==nullptr;}
    bool IsLeaf(){ return m_children.size()==0;}

    //static TreeNode<T>* GetTree(T iroot, const vector<vector<T>>& G){
    static TreeNode<T>* GetTree(T iroot, const map<T, vector<T>>& G){
        auto root = new TreeNode<T>(iroot);
        queue<TreeNode<T>*> q;
        q.push(root);
        while(!q.empty()){
            auto v = q.front(); q.pop();
            for(auto& u : G.at(v->m_val)){
                if(v->m_parent != nullptr && v->m_parent->m_val == u) continue;
                auto c = v->AddNode(u);
                q.push(c);
            }
        }
        return root;
    }

    int GetDepth(){
        int depth = 0;
        auto node = m_parent;
        while(node!=nullptr){
            depth++;
            node = node->m_parent;
        }
        return depth;
    }

    TreeNode<T>* GetFarthestNode(){
        int depth_max = -1;
        TreeNode<T>* res = nullptr;
        queue<TreeNode<T>*> q;
        q.push(this);
        while(!q.empty()){
            auto v = q.front(); q.pop();
            for(auto& c : v->m_children){
                if(c->IsLeaf()){
                    auto d = c->GetDepth();
                    if(d > depth_max){
                        depth_max = d;
                        res = c;
                    }
                }else{
                    q.push(c);
                }
            }
        }
        return res;
    }

    void ChangeRoot(){
        TreeNode<T>* v = this;
        TreeNode<T>* parent = nullptr;
        while(true){
            if(parent!=nullptr) v->m_children.erase(parent);
            auto p = v->m_parent;
            v->m_parent = parent;
            if(p==nullptr) break;
            v->m_children.insert(p);
            parent = v;
            v = p;
        }
    }

    int GetMaxRadius(){
        auto root = GetRoot();
        auto v = GetFarthestNode();
        v->ChangeRoot();
        auto u = v->GetFarthestNode();
        auto d = u->GetDepth();
        root->ChangeRoot();
        return d + 1;
    }
};


