template<typename T>
struct Diameter {
private:
    using Edge = pair<int, T>;
    vector<T> dp,ps;
    vector<vector<Edge>> G;

    void dfs(int v, int p, int &s) {
        ps[v] = p;
        if (p < 0) dp[v] = T(0);
        if (dp[s] < dp[v]) s = v;
        for(Edge e : G[v]) {
            int u = e.first;
            if(u == p) continue;
            dp[u] = dp[v] + e.second;
            dfs(u, v, s);
        }
    }

    pair<int, int> endPoints() {
        int s = 0;
        dfs(s, -1, s);
        int t = s;
        dfs(t, -1, t);
        return make_pair(s, t);
    }

public:
    Diameter(){}
    Diameter(int n) : dp(n), ps(n), G(n) {}

    void add_edge(int u, int v, T c) {
        G[u].emplace_back(v, c);
        G[v].emplace_back(u, c);
    }

    T build() {
        int t = endPoints().second;
        return dp[t];
    }

    vector<int> restore() {
        int t = endPoints().second;
        vector<int> seq;
        while(~t) {
            seq.emplace_back(t);
            t = ps[t];
        }
        return seq;
    }

    vector<T> distance(int v) {
        dfs(v, -1, v);
        return dp;
    }

    vector<T> farthest() {
        int t = endPoints().second;
        auto ds = dp;
        auto dt = distance(t);
        for(int i = 0; i < (int)ds.size(); i++) {
            if(ds[i] < dt[i]) ds[i] = dt[i];
        }
        return ds;
    }
};

