int memo[200010][2];
int dp(int n,int p){
    if (n == 1) return p;
    if (n == 2) return !p;
    if (memo[n][p] != -1) return memo[n][p];
    if (p == 1) return memo[n][p] = max(dp(n-1,0), dp(n-2,0));
    else return memo[n][p] = min(dp(n-1,1),dp(n-2,1));
}
