pair<int,int> dfs(int s,int t){ //親はsです 子はtです
  int fir=0,sec=0,ff=0;
  pair<int,int> P;
  auto it=Y[t].begin();
  auto it2=Y[t].end();
  while(it!=it2){
    if(*it!=s){
      P=dfs(t,*it);
      if(P.second>=fir)
        sec=fir,fir=P.second;
      else if(P.second>sec)
        sec=P.second;
      ff=max(ff,P.first);
    }
    it++;
    continue;
  }
  ff=max({ff,fir+sec,fir+1});
  return {ff,fir+1};
}

