pair<int,int> dfs(vector< vector< pair<int,int> > > &G, vector<bool> &visited, int v){
  pair<int,int> ret(0,v);
  visited[v] = true;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i].second;
    if(visited[v_]) continue;
    pair<int,int> ret_ = dfs(G,visited,v_);
    ret_.first += G[v][i].first;
    ret = max(ret,ret_);
  }
  return ret;
}

int diameter(vector< vector< pair<int,int> > > &G){
  int N = G.size();
  vector<bool> init(N,false);
  int v = dfs(G,init,0).second;
  init = vector<bool>(N,false);
  return dfs(G,init,v).first;
}

