int N;

int getDepth(int iRoot, vi A, vi B) {
    queue<int> q;
    q.push(iRoot);

    int d = 0;

    // bfs
    while (!q.empty()) {
        d++;
        queue<int> next;
        while (!q.empty()) {
            int now = q.front();
            q.pop();

            for (int i = A.size() - 1; i >= 0; i--) {
                if (A[i] == now) {
                    next.push(B[i]);
                    A.erase(A.begin() + i);
                    B.erase(B.begin() + i);
                } else if (B[i] == now) {
                    next.push(A[i]);
                    A.erase(A.begin() + i);
                    B.erase(B.begin() + i);
                }
            }
        }
        q = next;
    }
    return d;
}

int main() {
