    vi A(N - 1), B(N - 1);
    for (int i = 0; i < N - 1; i++) {
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
    }

    int ans = INF;
    // i 根１
    for (int i = 0; i < N; i++) {
        int d = getDepth(i, A, B);
        ans = min(ans, d);
    }

    if (ans % 2 == 1) {
        cout << "Second" << endl;
    } else {
        cout << "First" << endl;
    }
    return 0;
}

