      udepth=tmp.depth;
      u = tmp.pos;
    }
    s.pop();
    for(auto pos : connection[tmp.pos]){
      // cout << pos << endl;
      if(!reached[pos]){
        reached[pos]=true;
        s.push(data{pos, tmp.depth+1});
      }
    }
  }

  vector<bool> reached2(N, false);
  stack<data> s2;
  reached2[u] = true;
  s2.push(data{u, 1ll});

  ll diam = 1;

  while(!s2.empty()){
    data tmp = s2.top();
    diam = max(diam, tmp.depth);
    s2.pop();
    for(auto pos : connection[tmp.pos]){
      if(!reached2[pos]){
        reached2[pos]=true;
        s2.push(data{pos, tmp.depth+1});
      }
    }
  }

  cout << diam << endl;

  if(diam==0){ cout << "Second" << endl; return 0;}

  if(diam%3==2){cout<<"Second" <<endl;}
  else cout<<"First" <<endl;


}

















