//  topological sort
TTT VI topsort(const digraph<T>&g){VI to_node(g.n,0);fou(id,0,si(g.edges)){if(g.ignore!=nullptr&&g.ignore(id))continue;to_node[g.edges[id].to]++;}VI sorted;fou(i,0,g.n)if(to_node[i]==0)sorted.emb(i);fou(i,0,si(sorted)){tra(id,g.g[sorted[i]]){if(g.ignore!=nullptr&&g.ignore(id))continue;if(--to_node[g.edges[id].to]==0)sorted.emb(g.edges[id].to);}}if(si(sorted)!=g.n)return VI();return sorted;}




