template<typename T>class forest:public undigraph<T> {
public:
  using undigraph<T>::edges;using undigraph<T>::g;using undigraph<T>::n;
  VI root,treesize,depth;VT dist;
  forest(int _n):undigraph<T>(_n){init();}
  void init(){root=VI(n,-1);treesize=VI(n,1);depth=VI(n);dist=vector<T>(n);}
  void dfs(int from){tra(id,g[from]){auto&e=edges[id];if(from==e.from)swap(e.from,e.to);int to=e.from;if(root[to]!=-1)continue;dist[to]=dist[from]+e.cost;depth[to]=depth[from]+1;root[to]=root[from];dfs(to);treesize[from]+=treesize[to];}}
  void set_root(int v){if(root[v]==-1){root[v]=v;dfs(v);}}
  void search_all(){init();fou(v,0,n)set_root(v);}
  T diameter(){
    search_all();
    int end=maxe(dist);
    init();
    set_root(end);
    return dist[maxe(dist)];
  }
};





