        stack<int> q;
        q.push(v);
        d[v] = 1;
        while (!q.empty()) {
            int v = q.top();
            q.pop();
            for (int w : g[v]) {
                if (d[w] == inf) {
                    d[w] = d[v] + 1;
                    q.push(w);
                }
            }
        }
    };
