    vector<int> W{0, 1, 0};
    W.reserve(D + 1);
    for (int dd = 3; dd <= D; ++dd) {
        W.push_back(!(W[dd - 1] & W[dd - 2]));
    }
    cout << (W[D] ? "First" : "Second") << endl;
