vector<int> g[225816],q[2];
int dist[225816];
bool done[225816],memo[225816];

bool solve(int r){
	if(done[r]){
		return memo[r];
	}
	done[r] = true;
	if(r==0){
		memo[r] = true;
	}else if(r==1){
		memo[r] = false;
	}else{
		memo[r] = (!(solve(r-1)&&solve(r-2)));
	}
	return memo[r];
}

