int n, x, y, d;
vector<int> v[200005];
bool dp[200005];

int dfs(int x, int y) {
    int mx1 = 0, mx2 = 0;
    for (int i = 0; i < (int)v[x].size(); ++i) {
        int to = v[x][i];
        if (to == y) continue;
        int z = dfs(to, x);
        if (z + mx1 + 1 > d) {
            d = z + mx1 + 1;
        }
        if (z >= mx1) mx2 = mx1, mx1 = z;
        else if (z >= mx2) mx2 = z;
    }
    d = max(d, mx1 + 1);
    return mx1 + 1;
}

