void bfs(int s){
  for(int i=0;i<n;i++)d[i]=INF;
  queue<int>q;
  q.push(s);
  d[s]=0;
  int u;
  while(!q.empty()){
    u=q.front();q.pop();
    for(int i=0;i<G[u].size();i++){
      Edge e=G[u][i];
      if(d[e.t]==INF){
        d[e.t]=d[u]+e.w;
        q.push(e.t);
      }
    }
  }
}
int solve(){
  bfs(0);
  int maxv=0;
  int tgt=0;
  for(int i=0;i<n;i++){
    if(d[i]==INF)continue;
    if(maxv<d[i]){
      maxv=d[i];
      tgt=i;
    }
  }
  bfs(tgt);
  maxv=0;
  for(int i=0;i<n;i++){
    if(d[i]==INF)continue;
    maxv=max(maxv,d[i]);
  }
  return maxv;
}

int dp[222222];

int Grundy(int x){
  int &g=dp[x];
  if(g!=-1)return g;
  if(x==0)return g=0;
  set<int>V;
  if(x>=1)V.insert(Grundy(x-1));
  if(x>=2)V.insert(Grundy(x-2));
  g=0;
  while(V.count(g))++g;
  return g;
}

int main(){
  memset(dp,-1,sizeof(dp));
  int s,t,w;
