    w=1;
    G[s].push_back(Edge(t,w));
    G[t].push_back(Edge(s,w));
  }
  int A=solve();
  A++;
  A=Grundy(A);
  if(A==0)cout<<"First"<<endl;
  else cout<<"Second"<<endl;
}

