#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

pair<ll, ll> visit(int v, int p, vector<vector<ll>> &E) {
  pair<ll, ll> r = make_pair(0, v);
  for (ll u : E[v]) if (u != p) {
    pair<ll, ll> t = visit(u, v, E);
    t.first++;
    if (r.first < t.first) r = t;
  }
  return r;
}

ll diameter(vector<vector<ll>> &E) {
  pair<ll, ll> r = visit(0, -1, E);
  pair<ll, ll> t = visit(r.second, -1, E);
  return t.first;
}

int main(void) {
  ll N;
  cin >> N;
  vector<vector<ll>> E(N);
  REP(i, 0, N - 1) {
    ll a, b;
    cin >> a >> b, a--, b--;
    E[a].push_back(b);
    E[b].push_back(a);
  }

  ll r = diameter(E);
  cout << (r % 3 != 1 ? "First" : "Second") << endl;
}

