        a--; b--;
        di.add_edge(a, b, 1);
        di.add_edge(b, a, 1);
    }
    di.get_distance(0);
    ll mv = -1, mi = -1;
    reps(i, 1, n) {
        if (mv < di.dist[i]) {
            mv = di.dist[i];
            mi = i;
        }
    }
    di.get_distance(mi);
    mv = -1, mi = -1;
    rep(i, n) {
        if (mv < di.dist[i]) {
            mv = di.dist[i];
            mi = i;
        }
    }
