template <typename T>
class TreeNode{
private:
    T m_val;
    TreeNode<T> *m_parent = nullptr;
    set<TreeNode<T>*> m_children;

public:
    TreeNode(T val){
        m_val = val;
        m_parent = nullptr;
    }

    ~TreeNode(){
        for(auto& c : m_children){
            delete c;
        }
    }

    void Print(int d=0){
        cout<<setw(d+1)<<m_val<<endl;
        for(auto c : m_children){
            c->Print(d+1);
        }
    }

    T GetValue(){ return m_val;}

    TreeNode* GetRoot(){
        auto node = this;
        while(node->m_parent!=nullptr){
            node = node->m_parent;
        }
        return node;
    }

    TreeNode* AddNode(T val){
        auto child = new TreeNode<T>(val);
        child->m_parent = this;
        m_children.insert(child);
        return child;
    }

    bool IsRoot(){ return m_parent==nullptr;}
    bool IsLeaf(){ return m_children.size()==0;}

    bool FindValInParents(T val){
        auto node = m_parent;
        while(node!=nullptr){
            if(node->m_val == val) return true;
            node = node->m_parent;
        }
        return false;
    }

    static TreeNode<T>* GetTree(T iroot, const map<T, vector<T>>& G){
        auto root = new TreeNode<T>(iroot);
        GetTree(root, G);
        return root;
    }
    static void GetTree(TreeNode<T>* node, const map<T, vector<T>>& G){
        for(auto& u : G.at(node->GetValue())){
            if(node->FindValInParents(u)) continue;
            auto c = node->AddNode(u);
            GetTree(c, G);
        }
    }

    int GetDepth(){
        int depth = 0;
        auto node = m_parent;
        while(node!=nullptr){
            depth++;
            node = node->m_parent;
        }
        return depth;
    }

    TreeNode<T>* GetFarthestNode(){
        TreeNode<T>* res = nullptr;
        int depth_max = -1;
        if(IsLeaf()) return this;
        for(auto& c : m_children){
            auto v = c->GetFarthestNode();
            auto d = v->GetDepth();
            if(d > depth_max){
                depth_max = d;
                res = v;
            }
        }
        return res;
    }

    void ChangeRoot(TreeNode<T>* parent = nullptr){
        if(parent!=nullptr) m_children.erase(parent);
        auto p = m_parent;
        m_parent = parent;
        if(p==nullptr) return;
        m_children.insert(p);
        p->ChangeRoot(this);
    }

    int GetMaxRadius(){
        auto root = GetRoot();
        auto v = GetFarthestNode();
        v->ChangeRoot();
        auto u = v->GetFarthestNode();
        auto d = u->GetDepth();
        root->ChangeRoot();
        return d + 1;
    }
};

