const ll MOD = 1e9 + 7;

int main() {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  ll n;
  std::cin>>n;

  std::vector<std::vector<ll>> graph(n);

  rep(i,0,n-1){
    ll a,b;
    std::cin>>a>>b;
    a--;b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  std::vector<ll> d(n,MOD);

  std::queue<ll> que;

  d[0]=0;
  que.push(0);

  while(!que.empty()){
    ll now=que.front();que.pop();

    for(ll next:graph[now]){
      if(chmin(d[next],d[now]+1)){
        que.push(next);
      }
    }
  }

  ll max=-1,itr=-1;

  rep(i,0,n){
    if(chmax(max,d[i]))itr=i;
  }

  rep(i,0,n)d[i]=MOD;

  d[itr]=0;
  que.push(itr);

  while(!que.empty()){
    ll now=que.front();que.pop();

    for(ll next:graph[now]){
      if(chmin(d[next],d[now]+1)){
        que.push(next);
      }
    }
  }

  max=-1;

  rep(i,0,n)chmax(max,d[i]);

  if(max%3==1)std::cout<<"Second";
  else std::cout<<"First";


  return 0;
}

