#define loop(i, a, b) for (int i = (a), i##len = (b); i < i##len; ++i)
#define rep(i, n) loop(i, 0, n)
#define lin long long
#define lfl long double

lin n;
vector<lin> e[200001];
vector<lin> d[200001];
bool passed[200001];
bool calced[200001];
stack<lin> st;

void calc(lin vv)
{
    st.push(vv);
    passed[vv] = true;

    while(st.size() > 0)
    {
        lin v = st.top();
        //cout << v << endl;
        bool completed = true;
        rep(i, e[v].size())
        {
            lin c = e[v][i];
            if(passed[c])
                continue;

            completed = false;
            passed[c] = true;
            st.push(c);
        }

        if(!completed)
            continue;

        calced[v] = true;

        rep(i, e[v].size())
        {
            lin c = e[v][i];
            if(!calced[c])
                continue;

            lin sz = d[c].size();

            lin depth = 1;
            if(sz > 0)
            {
                sort(d[c].begin(), d[c].end());
                depth = d[c][sz-1] + 1;
            }
            d[v].push_back(depth);
        }

        st.pop();
    }
}

bool solve()
{
    calc(n / 2);
    lin len = 1;

    rep(i, n)
    {
        lin sz = d[i].size();
        //cout << i << " " << sz << endl;
        if(sz <= 0)
            continue;
        if(sz == 1)
        {
            len = max(len, d[i][0] + 1);
            continue;
        }

        //sort(d[i].begin(), d[i].end());
        len = max(len, d[i][sz-1] + d[i][sz-2] + 1);
    }

    //cout << len << endl;

    return len % 3 != 2;
}

int main(void)
{
    cin >> n;
    //n = 100000;
    //cout << "start";
    rep(i,n)
    {
        lin a,b;
        cin >> a >> b;
        //a = i + 1; b = i + 2;
        e[a-1].push_back(b-1);
        e[b-1].push_back(a-1);
    }
    //cout << "start";

    if(solve())
        cout << "First" << endl;
    else
        cout << "Second" << endl;
    return 0;
}

