int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N;
    cin >> N;

    vvi adj(N);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u-1].push_back(v-1);
        adj[v-1].push_back(u-1);
    }

    auto dist = [&](int rt) {
        vi res(N, -1);
        res[rt] = 0;
        queue<int> bfs({ rt });
        while (!bfs.empty()) {
            int loc = bfs.front();
            bfs.pop();
            for (int nbr : adj[loc]) {
                if (res[nbr] == -1) {
                    res[nbr] = res[loc] + 1;
                    bfs.push(nbr);
                }
            }
        }
        return res;
    };

    vi dist0 = dist(0);
    int x = 0;
    for (int i = 1; i < N; i++) {
        if (dist0[i] > dist0[x])
            x = i;
    }

    vi distX = dist(x);
    int mx = 0;
    for (int v : distX)
        mx = max(mx, v);
    mx++;

    vb win(mx + 1);
    win[0] = false;
    win[1] = true;
    win[2] = false;
    for (int d = 3; d <= mx; d++) {
        win[d] = (!win[d-1]) | (!win[d-2]);
    }

    cout << (win.back() ? "First" : "Second") << endl;

    return 0;
}

