vector<Weight> ShortestPath(const Graph& g, int s) {
	int V = g.size();
	vector<Weight> dist(V);
	function<void(int, int, Weight)> dfs = [&](int v, int p, Weight depth) {
		dist[v] = depth;
		for (auto e : g[v]) {
			if (e.to == p)continue;
			dfs(e.to, v, depth + e.cost);
		}
	};
	dfs(s, -1, 0);
	return dist;
}

tuple<Weight, int, int> Diametar(const Graph& g) {
	vector<Weight> d1 = ShortestPath(g, 0);
	int v1 = max_element(d1.begin(), d1.end()) - d1.begin();
	vector<Weight> d2 = ShortestPath(g, v1);
	int v2 = max_element(d2.begin(), d2.end()) - d2.begin();
	return make_tuple(d2[v2], v1, v2);
}

