pair<int, int> dfs(int v, int p, Graph<>& g) {
    pair<int, int> ret = {0, v};
    for (int u : g.Ns(v)) {
        if (p == u) continue;
        chmax(ret, dfs(u, v, g));
    }
    return {ret.first + 1, ret.second};
}
int main() {
    int N;
    cin >> N;
    Graph<> g(N, N - 1);
    for (int i : range(N - 1)) {
        int a, b;
        cin >> a >> b;
        g.add_edge(a - 1, b - 1);
    }
    auto r = dfs(0, 0, g).second;
    if ((dfs(r, r, g).first) % 3 == 0) {
        cout << "First" << endl;
    }
    else {
        cout << "Second" << endl;
    }
    return 0;
