unsigned solve2(unsigned p, unsigned pre) {
	unsigned first = 0, second = 0;
	for (auto next : e[p]) {
		if (next == pre) continue;
		unsigned d = solve2(next, p);
		second = max(second, min(first, d));
		first = max(first, d);
	}
	ans = max(ans, first + second + 1);
	return first + 1;
}

