unordered_map<long, unordered_set<long>> joint;

// 最も遠い点、距離
pair<long, long> rec(long start, unordered_set<long> &used) {
  pair<long, long> result = make_pair(start, 0);
  for (long n: joint[start]) {
    if (used.count(n)) continue;
    used.insert(n);
    auto tmp = rec(n, used);
    if (result.second <= tmp.second) result = make_pair(tmp.first, tmp.second + 1);
  }
  return result;
}

