#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

unordered_multimap<int, int> tree;
int num[200001] = { 0 };

pair<int, int> most_distant(int p, unordered_multimap<int, int>& trees)
{
	FOR_LE(i, 0, 200000) {
		num[i] = -1;
	}
	queue<int> search;
	search.push(p);
	num[p] = 1;

	while (!search.empty()) {
		int p2 = search.front();
		search.pop();

		auto it = trees.find(p2);
		while (it != trees.end() && it->first == p2) {
			if (num[it->second] != -1) {
				it++;
				continue;
			}

			num[it->second] = num[it->first] + 1;
			search.push(it->second);
			it++;
		}
	}

	pair<int, int> ans = { 0, 0 };
	FOR_LE(i, 1, 200000) {
		if (ans.second < num[i]) {
			ans.first = i;
			ans.second = num[i];
		}
	}

	return ans;
}

int main()
{
	int n;
	cin >> n;

	FOR_LT(i, 0, n - 1) {
		int a, b; cin >> a >> b;
		tree.insert(make_pair(a, b));
		tree.insert(make_pair(b, a));
	}

	// 末端の数
	auto s = most_distant(1, tree);
	auto u = most_distant(s.first, tree);

	if ((u.second + 1) % 3 != 0) {
		cout << "First" << endl;
	}
	else {
		cout << "Second" << endl;
	}

	return 0;
}

