    for(int i = 0; i < n; ++i) {
        int a, b; cin >> a >> b;
        g[a - 1].push_back(b - 1);
        g[b - 1].push_back(a - 1);
    }

    int dist = 0;
    vector<int> v(n);
    function<int(int, int)> dfs = [&] (int v, int p) {
        int res = 0;
        vector<int> ds;
        for(auto to : g[v]) {
            if(to == p) continue;
            ds.push_back(dfs(to, v) + 1);
        }
        sort(rbegin(ds), rend(ds));
        if(!ds.empty()) {
            res = ds[0];
            dist = max(dist, ds[0]);
        }
        if(ds.size() >= 2u) {
            dist = max(dist, ds[0] + ds[1]);
        }
        if(ds.size())
        dist = max(dist, res);
        return res;
    };
    dfs(0, -1);

    vector<int> dp(n + 1, -1);
    function<int(int)> solve = [&] (int x) {
        int& res = dp[x];
        if(x == 0) return res = 1;
        if(x == 1) return res = 0;
        if(res != -1) return res;
        return res = !solve(x - 1) || !solve(x - 2);
    };
    if(solve(dist) == 1) {
        cout << "First" << endl;
    } else {
        cout << "Second" << endl;
    }
}

