using namespace std;

int dv;
int maxDepth = -1;
int visit[20001];
void findDeepestV(int v, int depth, unordered_map<int, vector<int> > mp) {
    if (maxDepth < depth) {
        maxDepth = depth;
        dv = v;
    }
    visit[v] = 1;
    for (auto &child : mp[v]) {
        if (visit[child] == 0) {
            findDeepestV(child, depth + 1, mp);
        }
    }
}

int getDiameter(unordered_map<int, vector<int> > mp) {
    maxDepth = -1;
    findDeepestV(1, 0, mp);
    maxDepth = -1;
    for (int i = 0; i < 20001; i++) visit[i] = 0;
    findDeepestV(dv, 1, mp);
    return maxDepth;
}

int d[20001];

bool canWin(int now, bool turn) {
    // cout << (turn == true ? "First" : "Second") << " " << now << endl;
    if (now == 0) return false;
    if (d[now] != 0) return d[now] == 1;
    bool ans = false;
    ans |= !canWin(now - 1, !turn);
    if (now > 2) {
        ans |= !canWin(now - 2, !turn);
    }
    // cout << "now = " << now << " " << (turn == true ? "First" : "Second") << " result = " << ans << endl;
    d[now] = ans == true ? 1 : 2;
    return ans;
}

int main() {
    int n, i, a, b;
    cin >> n;
    unordered_map<int, vector<int> > mp;
    for (i = 0; i < n - 1; i++) {
        cin >> a >> b;
        if (mp.find(a) == mp.end()) {
            mp.insert(make_pair(a, vector<int>()));
        }
        mp[a].push_back(b);
        if (mp.find(b) == mp.end()) {
            mp.insert(make_pair(b, vector<int>()));
        }
        mp[b].push_back(a);
    }
    int diameter = getDiameter(mp);
    if (canWin(diameter, true)) {
        cout << "First";
    } else cout << "Second";
    return 0;
}

