vector<int> dfs(vector2<int>& graph, int s){
    int n = graph.size();
    vector<int> depth(n, -1);

    stack<P> st;
    st.emplace(s, 0);
    while(not st.empty()){
        int v = st.top().first;
        int d = st.top().second;
        st.pop();

        if(depth[v] != -1){
            continue;
        }
        depth[v] = d;
        for(int u : graph[v]){
            st.emplace(u, d + 1);
        }
    }

    return depth;
}

int doubleSweep(vector2<int>& graph){
    int n = graph.size();
    vector<int> d1 = dfs(graph, 1);
    int f1 = 0;
    rep(i, n){
        if(d1[f1] < d1[i]){
            f1 = i;
        }
    }
    vector<int> d2 = dfs(graph, f1);
    int f2 = 0;
    rep(i, n){
        if(d2[f2] < d2[i]){
            f2 = i;
        }
    }
    vector<int> d3 = dfs(graph, f2);

    int dia = d2[f2];

    vector<int> len(n);
    for(int v = 1; v < n; v++){
        len[max(d2[v], d3[v])]++;
    }
    return dia;
}

