const int N = 2e5 + 7;

vector <int> g[N];
int dp[N];

int ans = 0;

void dfs(int v, int pr)
{
  dp[v] = 1;
  vector <int> ret;
  for (int to : g[v])
  {
    if (to != pr)
    {
      dfs(to, v);
      dp[v] = max(dp[v], dp[to] + 1);
      ret.push_back(dp[to]);
    }
  }
  sort(ret.rbegin(), ret.rend());
  int sum = 1;
  for (int i = 0; i < 2 && i < (int) ret.size(); i++) sum += ret[i];
  ans = max(ans, sum);
}

void solve()
{
  int n;
  cin >> n;
  for (int i = 1; i < n; i++)
  {
    int a, b;
    cin >> a >> b;
    a--, b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  dfs(0, -1);
  vector <bool> dp(n + 228);
  dp[0] = false;
  dp[1] = true;
  dp[2] = false;
  for (int i = 3; i <= n; i++)
  {
    if (i - 1 >= 0 && !dp[i - 1]) dp[i] = true;
    if (i - 2 >= 0 && !dp[i - 2]) dp[i] = true;
  }
  if (dp[ans])
  {
    cout << "First\n";
  }
  else
  {
    cout << "Second\n";
  }
}

