template<typename T>
struct DiameterOfVertex{
  vector<T> vs,dp;
  vector<vector<int> > G;
  DiameterOfVertex(vector<T> vs):vs(vs),dp(vs.size()),G(vs.size()){}
  void add_edge(int u,int v){
    G[u].emplace_back(v);
    G[v].emplace_back(u);
  }
  void dfs(int v,int p,int &s){
    if(p<0) dp[v]=T(0);
    dp[v]+=vs[v];
    if(dp[s]<dp[v]) s=v; 
    for(int u:G[v]){
      if(u==p) continue;
      dp[u]=dp[v];
      dfs(u,v,s);
    }    
  }  
  T build(){    
    int s=0;
    dfs(s,-1,s);
    dfs(s,-1,s);
    return dp[s];    
  }
};
