vector<int> dist(int st, vector<vector<int>> &tree) {

	const int sz = (int)tree.size();
	vector<int> dist(sz, -1);

	queue<int> que;
	que.emplace(st);
	dist[st] = 0;
	while (!que.empty()) {

		auto now = que.front();
		que.pop();

		for (const auto &e : tree[now]) {
			if (dist[e] == -1) {
				dist[e] = dist[now] + 1;
				que.emplace(e);
			}
		}

	};

	return dist;

};

