		if (!visit[e.to]) dfs(g, e.to, d + 1, dist, visit);
	}
}

int diameter(graph& g) {
	int n = g.size();
	VI dist(n);
	vector<bool> visit(n);
	dfs(g, 0, 0, dist, visit);
	int max_idx = 0;
	int max_dist = -1;
	REP(i, n) {
		if (dist[i] > max_dist) {
			max_dist = dist[i];
			max_idx = i;
		}
	}
	visit = vector<bool>(n, false);
	dfs(g, max_idx, 0, dist, visit);
	max_dist = -1;
	max_idx = 0;
	REP(i, n) {
		if (dist[i] > max_dist) {
			max_dist = dist[i];
			max_idx = i;
		}
	}
	return max_dist;
}


