Edge edge[SIZE << 1];
int head[SIZE], edgePt, vertexNum;
int deg[SIZE];

pair<int, int> dp[SIZE];
int maxLen, num;

void addEdge(int from, int to) {
    edge[edgePt] = {to, head[from]};
    head[from] = edgePt++;
}

void dfs(int cntPt, int fatherPt) {
    dp[cntPt].first = 0;
    dp[cntPt].second = 1;

    for (int i = head[cntPt]; i != -1; i = edge[i].next) {
        int nextPt = edge[i].to;
        if (nextPt == fatherPt)
            continue;
        dfs(nextPt, cntPt);

        int cntLen = dp[nextPt].first + 1;
        if (cntLen + dp[cntPt].first > maxLen) {
            maxLen = cntLen + dp[cntPt].first;
            num = dp[cntPt].second * dp[nextPt].second;
        } else if (cntLen + dp[cntPt].first == maxLen) {
            num += dp[cntPt].second * dp[nextPt].second;
        }

        if (cntLen > dp[cntPt].first) {
            dp[cntPt].first = cntLen;
            dp[cntPt].second = dp[nextPt].second;
        } else if (cntLen == dp[cntPt].first) {
            dp[cntPt].second += dp[nextPt].second;
        }
    }
}

