struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to, const bool bi = false)
    {
        assert(from < V), assert(to < V);
        edge[from].push_back(to), rev_edge[to].push_back(from);
        if (bi) { addEdge(to, from, false); }
    }
    const std::vector<std::size_t>& operator[](const std::size_t i) const { return assert(i < V), edge[i]; }
    friend std::ostream& operator<<(std::ostream& os, const Graph& g)
    {
        os << "[\n";
        for (std::size_t i = 0; i < g.V; i++) {
            for (const std::size_t to : g.edge[i]) { os << i << "->" << to << "\n"; }
        }
        return (os << "]\n");
    }
    std::size_t V;
    std::vector<std::vector<std::size_t>> edge, rev_edge;
};
using Tree = Graph;
//!======================================================================!//
//!  888888ba  oo                                dP                      !//
//!  88    '8b                                   88                      !//
//!  88     88 dP .d8888b. 88d8b.d8b. .d8888b. d8888P .d8888b. 88d888b.  !//
//!  88     88 88 88'  '88 88''88''88 88ooood8   88   88ooood8 88'  '88  !//
//!  88    .8P 88 88.  .88 88  88  88 88.  ...   88   88.  ... 88        !//
//!  8888888P  dP '88888P8 dP  dP  dP '88888P'   dP   '88888P' dP        !//
//!======================================================================!//
std::vector<std::size_t> Diameter(const Tree& tree)
{
    const std::size_t V = tree.V;
    std::vector<std::size_t> dist(V, 0);
    std::vector<std::size_t> p(V, V);
    auto dfs = [&](auto&& self, const std::size_t s, const std::size_t prev) -> void {
        for (const std::size_t to : tree.edge[s]) {
            if (to == prev) { continue; }
            dist[to] = dist[s] + 1, p[to] = s;
            self(self, to, s);
        }
    };
    dfs(dfs, 0, V);
    std::size_t r = std::max_element(dist.begin(), dist.end()) - dist.begin();
    dist[r] = 0, std::fill(p.begin(), p.end(), V), dfs(dfs, r, V);
    r = std::max_element(dist.begin(), dist.end()) - dist.begin();
    std::vector<std::size_t> ans;
    for (; r != V; r = p[r]) { ans.push_back(r); }
    return ans;
}
