#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

unordered_multimap<int, int> tree;
int num[200001] = { 0 };

int num_size(int p, unordered_multimap<int, int>& trees)
{
	FOR_LE(i, 0, 200000) {
		num[i] = -1;
	}
	queue<int> search;
	search.push(p);
	num[p] = 1;
	bool is_first = true;

	while (!search.empty()) {
		int p2 = search.front();
		search.pop();

		auto it = trees.find(p2);
		if (is_first && tree.count(p2) != 1) {
			int* hoge = nullptr;
			*hoge = 0;
		}
		is_first = false;
		while (it != trees.end() && it->first == p2) {

			if (num[it->second] != -1) {
				it++;
				continue;
			}

			num[it->second] = num[it->first] + 1;
			search.push(it->second);
			it++;
		}
	}

	int ans = 0;
	FOR_LE(i, 0, 200000) {
		ans = max(num[i], ans);
	}

	return ans;
}

int main()
{
	int n;
	cin >> n;

	FOR_LT(i, 0, n - 1) {
		int a, b; cin >> a >> b;
		tree.insert(make_pair(a, b));
		tree.insert(make_pair(b, a));
	}

	// 末端の数
	int p = 0;
	FOR_LE(i, 1, n) {
		if (tree.count(i) == 1) {
			p = i;
			break;
		}
	}

	int size = num_size(p, tree);

	if ((size + 1) % 3 != 0) {
		cout << "First" << endl;
	}
	else {
		cout << "Second" << endl;
	}

	return 0;
}

