pair<int,int> dfs(const Graph &G, int v, int prev){
  pair<int,int> ret(0,v);
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    ret = max(ret,dfs(G,v_,v));
  }
  ++ret.first;
  return ret;
}

