pair<ll, ll> far_node(ll k)
{
    vector<ll> min_cost(200005, inf);
    queue<ll> que;

    ll far_node = k;
    ll max_cost = 0;

    que.push(k);
    min_cost[k] = 0;
    while (!que.empty()) {
        ll node = que.front();
        que.pop();

        for (int i = 0; i < tree[node].size(); i++) {
            ll nnode = tree[node][i];

            if (min_cost[nnode] > min_cost[node] + 1) {
                min_cost[nnode] = min_cost[node] + 1;
                que.push(nnode);
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        if (max_cost < min_cost[i]) {
            max_cost = min_cost[i];
            far_node = i;
        }
    }

    return pair<ll, ll>(far_node, max_cost);
}

ll far_path(void)
{
    ll s = far_node(1).first;

    return far_node(s).second;
}

