//UnweightedTree
//argument -> [Vertex_Size, Start_Node]
//return   -> [Furthest_Node, Diameter]
P tree_diameter(int V, int st){
	int t = st;
	int diameter = 0;
	queue<int> Q;
	vector<int> dist(V, inf);
	dist[st] = 0;
	Q.push(st);
	while(!Q.empty()){
		int f = Q.front();
		Q.pop();
		for(auto x:G[f]){
			if(dist[x] == inf){
				dist[x] = dist[f] + 1;
				Q.push(x);
				if(dist[x] > diameter){
					diameter = dist[x];
					t = x;
				}
			}
		}
	}
	return make_pair(t, diameter);
}

