vector<edge> g[MAX];

P farthest(int u,int p) {
  P r(0,u);
  for(auto e : g[u]) {
    if(e.to == p) continue;
    P c = farthest(e.to,u);
    c.first += e.cost;
    r = max(r,c);
  }
  return r;
}

Diameter tree_diameter() {
  P p = farthest(0,-1);
  P q = farthest(p.second,-1);
  return Diameter{p.second,q.second,q.first}; 
}

