int dfs(int node, int depth) {
    used[node] = 1;
    int ret = depth;
    for(int next_node: graph[node]) {
        if(used[next_node]) continue;
        ret = max(ret, dfs(next_node, depth+1));
    }
    return ret;
}

int calc_diameter() {
    vector<int> depths;
    used[0] = 1;
    for(int node: graph[0]) {
        depths.push_back(dfs(node, 1));
    }
    sort(depths.rbegin(), depths.rend());
    return depths[0]+depths[1];
}

