  int edge_num;
  int diameter = -1;
  int leaf_node;
  int far_index = -1;
  vector<vector<int>> cost;
  vector<bool> visited;

  Tree(int nn) : node_num(nn){
    edge_num = node_num - 1;
    cost = vector<vector<int>> (node_num, vector<int>(node_num, -1));
    visited = vector<bool> (node_num, false);
  }


  int get_far_dist(int from, int d){
    visited[from] = true;
    // cout << d << endl;
    // cout << from << endl;
    for (int i = 0; i < node_num; i++) {
      if(cost[from][i] != -1 && !visited[i]){
        get_far_dist(i, d+cost[from][i]);
      }
    }
    diameter = max(diameter, d);
    return diameter;
  }

  int get_far_index(int from, int d){
    visited[from] = true;
    for (int i = 0; i < node_num; i++) {
      if(cost[from][i] != -1 && !visited[i]){
        get_far_index(i, d+cost[from][i]);
      }
    }
    if(diameter < d){
      diameter = d;
      far_index = from;
    }
    return far_index;
  }

  int get_diameter(int from){
    int leaf = get_far_index(0, 0);
    init();
    return diameter = get_far_dist(leaf, 0);
  }

  void init(){
    visited = vector<bool> (node_num, false);
  }

};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  Tree t(n);
  for (int i = 0; i < n-1; i++) {
    int from, to;
    cin >> from >> to;
    from--;
    to--;
    t.cost[from][to] = 1;
    t.cost[to][from] = 1;
  }

  t.get_diameter(0);
  if(t.diameter % 3 == 1){
    cout << "Second" << endl;
  }else{
    cout << "First" << endl;
  }
}

