const int N = 200005;

int n, d[N];
vector<int> adj[N];

void calc (int C, int P) {
	for(auto &T : adj[C]) {
		if(T == P) continue;
        d[T] = d[C] + 1;
        calc(T, C);
	}
}

int main()
{
