		adj[A].push_back(B);
		adj[B].push_back(A);
	}
	calc(1, 0);
	int I = 1;
	for(int i=1;i<=n;i++) {
		if(d[I] < d[i]) I = i;
	}
	d[I] = 0;
	calc(I, 0);
	int X = 0;
	for(int i=1;i<=n;i++) {
		X = max(X, d[i]);
	}
	puts((X - 1) % 3 ? "First" : "Second");
}

