int n;
vector<vector<int> > neigh;

pair<int, int> Find_furthest(int start){
    vector<bool> is_visited(n, false);
    queue<int> indices, dist;
    is_visited[start] = true;
    indices.push(start);
    dist.push(0);
    int ans_i = -1, ans_dist = -1;
    while (!indices.empty()){
        int a = indices.front();
        if (dist.front() > ans_dist){
            ans_dist = dist.front();
            ans_i = a;
        }
        for (int b : neigh[a])
            if (!is_visited[b]){
                is_visited[b] = true;
                indices.push(b);
                dist.push(dist.front() + 1);
            }
        indices.pop();
        dist.pop();
    }
    return {ans_i, ans_dist};
}

int main(){
    cin.tie(NULL);
    ios_base::sync_with_stdio(false);
    cin >> n;
    neigh.resize(n);
    FOR (i, n - 1){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    FOR (i, n)
        if (neigh[i].size() == 1){
            int max_dist = Find_furthest(Find_furthest(i).first).second;
            if (max_dist % 3 == 1)
                cout << "Second" << endl;
            else
                cout << "First" << endl;
            return 0;
        }
    cout << "First" << endl;
}

