vector<vector<int>> kake(vector<vector<int>> &tim1,vector<vector<int>> &tim2) {
	vector<vector<int>> res = vector<vector<int>>(tim1.size(),vector<int>(tim1[0].size(),0));
	REP (i,tim1.size()) {
		REP (j,tim1[0].size()) {
			REP (k,tim2[0].size()) {
				res[i][k] += tim1[i][j] * tim2[j][k];
				res[i][k] %= mod;
			}
		}
	}
	return res;
}

class UnionFind {
private:
	vector<int> par;
public:
	UnionFind(int N) { par = vector<int>(N, -1LL); }
	int find(int x);
	ll size(int x);
	void unite(int x, int y);
	bool same(int x, int y);
};



//----UnionFind-------------------------------
int UnionFind::find(int x) {
	if (par[x] < 0) return x;
	else return par[x] = find(par[x]);
}

ll UnionFind::size(int x) {
	return -par[find(x)];
}

void UnionFind::unite(int x, int y) {
	x = find(x);
	y = find(y);

	//大きい方に小さい方をくっ付ける
	if (size(x) < size(y)) swap(x, y);
	par[x] += par[y];
	par[y] = x;
}

bool UnionFind::same(int x, int y) {
	x = find(x);
	y = find(y);
	return x == y;
}

signed main() {
	int n;
	cin >> n;
	UnionFind uf(n);

	int len[n];
	REP (i,n) len[i] = INF;
	len[0] = 0;

	vector<vector<int>> A = vector<vector<int>>(n);
	REP (i,n-1) {
		int a,b;
		cin >> a >> b;
		A[a-1].push_back(b-1);
		A[b-1].push_back(a-1);
	}

	queue<int> q;

	REP (i,A[0].size()) {
		len[A[0][i]] = 1;
		q.push(A[0][i]);
	}
	while (!q.empty()) {
		int x = q.front();
		q.pop();
		REP (i,A[x].size()) {
			if (len[A[x][i]] == INF) {
				len[A[x][i]] = len[x] + 1;
				q.push(A[x][i]);
				uf.unite(x,A[x][i]);
			}
		}
	}
	int mi = INF;
	int ma = -INF;
	int UNI[n];
	REP (i,n) UNI[i] = 0;
	REP (i,n) {
		int PAR = uf.find(i);
		UNI[PAR] = max(UNI[PAR],len[i]);
	}
	sort(UNI,UNI+n);
	ma = UNI[n-1];
	mi = UNI[n-2];
	if ((ma + mi - 1) % 3 == 0) {
		cout << "Second" << endl;
	} else {
		cout << "First" << endl;
	}
}

