int mem[N][2] ;
int solve(int d,int cur){
    if(d==0) return 1-cur ;
    if(d==1) return cur ;
    if(d==2) return 1-cur ;
    int&ret=mem[d][cur];
    if(~ret) return ret;
    int a = solve(d-1,1-cur);
    int b = solve(d-2,1-cur);
    if(a==cur) return ret = cur ;
    if(b==cur) return ret = cur ;
    return ret = 1-cur ;
}
