const int N = 2e5 + 1e2;
const int MOD = 1e9 + 7;
const int INF32 = 1e9 + 1e2;

int d[N];

vector<int> adj[N];

void bfs(int v = 0) {
    queue<int> q;
    q.push(v);
    fill(d, d + N, INF32);
    d[v] = 0;
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        for (int to : adj[x]) {
            if (d[to] > d[x] + 1) {
                d[to] = d[x] + 1;
                q.push(to);
            }
        }
    }
    for (int i = 0; i < N; ++i)
        if (d[i] == INF32)
            d[i] *= -1;
}

bool dp[N];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        adj[u].pb(v);
        adj[v].pb(u);
    }
    bfs();
    int v = max_element(d, d + N) - d;
    bfs(v);
    int dia = *max_element(d, d + N);
    dp[1] = 1;
    for (int i = 2; i <= dia; ++i) 
        dp[i] = not (dp[i - 1] & dp[i - 2]);
    cout << (dp[dia] ? "First" : "Second");
    return 0;
}

