//木の直径を返す
//res.first=木の直径 res.second.first<->res.second.secondが最遠点対
pair<ll,pair<ll,ll>> tree_diameter(const vector<vector<ll>> &g) {
	auto dfs = [&](auto&& dfs, const vector<vector<ll>> &g, ll idx, ll par) -> pair<ll,ll> {
		pair< ll, ll > ret(0, idx);
		for(ll e : g[idx]) {
			if(e == par) continue;
			pair<ll,ll> cost = dfs(dfs, g, e, idx);
			cost.first++;
			ret = max(ret, cost);
		}
		return ret;
	};
	pair< ll, ll > p = dfs(dfs, g, 0, -1);
	pair< ll, ll > q = dfs(dfs, g, p.second, -1);
	return {q.first, {p.second, q.second}};
}

