void SPFA1(){
	memset(vis,0,sizeof vis);
	for (int i=1;i<=n;i++) distx[i]=1e5;
	distx[s]=0;
	vis[s]=1;
	while (!q.empty()) q.pop();
	q.push(s);
	while (!q.empty()){
		int x=q.front();
		q.pop();
		for (int i=1;i<=n;i++){
			if (gh[x][i]<1e5){
				if (distx[x]+gh[x][i]<distx[i]){
					distx[i]=distx[x]+gh[x][i];
					if (!vis[i]) {
						vis[i]=1;
						q.push(i);
					}
				}
			}
		}
		vis[x]=0;
	}
}
void SPFA2(){
	memset(vis,0,sizeof vis);
	for (int i=1;i<=n;i++) disty[i]=1e5;
	disty[t]=0;
	vis[t]=1;
	while (!q.empty()) q.pop();
	q.push(t);
	while (!q.empty()){
		int x=q.front();
		q.pop();
		for (int i=1;i<=n;i++){
			if (gh[x][i]<1e5){
				if (disty[x]+gh[x][i]<disty[i]){
					disty[i]=disty[x]+gh[x][i];
					if (!vis[i]) {
						vis[i]=1;
						q.push(i);
					}
				}
			}
		}
		vis[x]=0;
	}
}
