    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        ds.E[a].push_back({b, 1});
        ds.E[b].push_back({a, 1});
    }
    ds.calc(0);
    int v, max_d = -1;

    rep(i, n) {
        if (ds.d[i] > max_d) {
            max_d = ds.d[i];
            v = i;
        }
    }
    ds.calc(v);
    ll diameter = 0;
    rep(i, n) diameter = max(diameter, ds.d[i]);
    cout << (diameter % 3 == 1 ? "Second" : "First") << endl;
    return 0;
}

