    vector<vector<int>> G(N, vector<int>());
    for(int i=0;i<N-1;i++){
        cin >> ai >> bi;
        G[ai-1].push_back(bi-1);
        G[bi-1].push_back(ai-1);
    }
    queue<pair<int,int>> q_end;
    vector<int> visited(N, INT_MIN);
    for(size_t i=0; i<G.size(); i++){
        if(G[i].size()==1){
            q_end.push(make_pair<int,int>(i,-1));
            visited[i] = 1;
        }
    }

    while(!q_end.empty()){
        queue<pair<int,int>> q_next;
        while(!q_end.empty()){
            auto v = q_end.front(); q_end.pop();
            for(auto g : G[v.first]){
                if(g==v.second) continue;
                if(visited[g] <= visited[v.first]){
                    q_next.push(make_pair(g,v.first));
                    visited[g] = visited[v.first]+1;
                }
            }
        }
        q_end = q_next;
    }
    int nmax = 0;
    int cmax = 0;
    for(auto v : visited){
        if(v == nmax) cmax++;
        else if(v > nmax){
            nmax = v;
            cmax = 1;
        }
    }
    if((nmax-0)%3==2) cout<<"Second"<<endl;
    else              cout<<"First"<<endl;

