    for (int i = 0; i < e.at(v).size(); ++i) if (e.at(v).at(i) != p) make_tree(e.at(v).at(i), v);
}

bool solve(int v) {
    if (c.at(v).empty()) return true;
    bool ans = true;
    for (int i = 0; i < c.at(v).size(); ++i) ans ^= solve(c.at(v).at(i));
    return ans;
}

