  if (n == 1) return 0 * printf("First\n");
  if (n == 2) return 0 * printf("Second\n");

  for (int i=1; i<n; i++) {
    int u, v;
    scanf("%d %d", &u, &v);
    --u, --v;

    edges[u].push_back(v);
    edges[v].push_back(u);
  }

  depth[0] = 0;
  dfs(0, -1);

  int root = 0;
  for (int i=1; i<n; i++) if (depth[i] > depth[root]) root = i;

  depth[root] = 0;
  dfs(root, -1);

  int maks = 0;
  for (int i=0; i<n; i++) maks = max(maks, depth[i]);

  if (maks % 3 == 1) printf("Second\n");
  else printf("First\n");
  return 0;
}

