// Returns the farthest node from the start.
// O(N)
int bfs(int start) {
    queue<int> q;
    q.push(start);

    dist.assign(SIZE, -1);
    dist[start] = 0;

    int cur = -1;
    while (!q.empty()) {
        cur = q.front();
        q.pop();

        for (int next : edges[cur]) {
            if (dist[next] == -1) {
                dist[next] = dist[cur] + 1;
                q.push(next);
            }
        }
    }

    return cur;
}

// Returns the length of the diameter of the tree.
// O(N)
int calcTreeDiameter(int root) {
    int far1 = bfs(root);
    int far2 = bfs(far1);
    return dist[far2];
}

