II calcD()
{
  memset(dist, 0, sizeof(dist));
  int k = calcDist(0,-1);
  II ret;
  REP(n,N) {
    if(dist[n] == k) ret.first = n;
  }
  memset(dist, 0, sizeof(dist));
  k = calcDist(ret.first, -1);
  REP(n,N) {
    if(dist[n] == k) ret.second = n;
  }

  vec.clear();
  int pos = ret.second;
  while(true) {
    vec.push_back(pos);
    if(pos == ret.first) break;
    for(int n : tree[pos]) {
      if(dist[n] == dist[pos]-1) {
        pos = n;
      }
    }
  }
  // cerr << ret.first << "," << ret.second << endl;
  return ret;
}

