void farthest(ll ref, ll here, ll& node, ll& dist) {
  DLOG("farthest %lld %lld\n", ref, here);
  ll cmax = -1;
  ll cmaxarg;
  for (ll c : nbr.at(here)) {
    if (c == ref)  continue;
    ll nd;
    ll dt;
    farthest(here, c, nd, dt);
    if (cmax < dt) {
      cmax = dt;
      cmaxarg = nd;
    }
  }
  if (cmax == -1) {
    node = here;
    dist = 0;
  }else {
    node = cmaxarg;
    dist = cmax + 1;
  }
  DLOG("farthest %lld %lld ---> %lld %lld\n", ref, here, node, dist);
}

