    queue<pair<int,int>> que;
    bool used[n]={};
    used[0]=true;
    que.push(make_pair(0,0));
    pair<int,int> t,t2;
    while(!que.empty()){
        t=que.front();
        que.pop();
        for(int i=0;i<h[t.first].size();i++){
            if(!used[h[t.first][i]]){
                used[h[t.first][i]]=true;
                que.push(make_pair(h[t.first][i],t.second+1));
            }
        }
    }
    fill(used,used+n,0);
    used[t.first]=true;
    que.push(make_pair(t.first,0));

    while(!que.empty()){
        t2=que.front();
        que.pop();
        for(int i=0;i<h[t2.first].size();i++){
            if(!used[h[t2.first][i]]){
                used[h[t2.first][i]]=true;
                que.push(make_pair(h[t2.first][i],t2.second+1));
            }
        }
    }

    if(t2.second%3==1)cout<<"Second";
    else cout<<"First";
    return 0;
}

