    void add(long long u, long long v, long long weight) {
        edges.push_back(make_tuple(u, v, weight, 1));
    }
    void add(long long u, long long v, long long weight, long long capacity) {
        edges.push_back(make_tuple(u, v, weight, capacity));
    }
    Graph(long long V) : V(V) {
    }
