pair<int,int> farthest(int i0)
{
  vector<int> d(N,-1);
  d[i0] = 0;
  deque<int> dq;
  dq.push_back(i0);

  while( not dq.empty() )
    {
      int u = dq.front();
      dq.pop_front();

      for( auto id : G[u] )
	{
	  if( d[id] == -1 )
	    {
	      dq.push_back(id);
	      d[id] = d[u] + 1;
	    }
	}
    }

  int i1 = 0;
  FOR(i,1,N)
    {
      if( d[i1] < d[i] )
	{
	  i1 = i;
	}
    }

  return make_pair(i1,d[i1]);

}




