pair<int, int> dfs(const Graph &G, int u, int par) {  // 最遠点間距離と最遠点を求める
    pair<int, int> ret = make_pair(0, u);
    for (auto e : G[u]) {
        if (e == par) continue;
        auto next = dfs(G, e, u);
        next.first += 1;
        ret = max(ret, next);
    }
    return ret;
}

int tree_diamiter(const Graph &G) {
    pair<int, int> p = dfs(G, 0, -1);
    pair<int, int> q = dfs(G, p.second, -1);
    return q.first;
}

