            }
        }
};

template <class T>
T * dijkstra(const graph<T> &g, const int &start)
{
    T *dist = new T[g.size()];
    //vector<T> dist(g.size());
    bool *used = new bool[g.size()]();
    priority_queue<pair<T, int>, vector<pair<T, int> >, greater<pair<T, int> > > q;
    dist[start] = 0;
    q.push(pair<T, int>(0, start));
    used[start] = true;
    while(!q.empty()) {
        pair<T, int> p = q.top();
        q.pop();
        int from = p.second;
        if (dist[from] < p.first) {
            continue;
        }
        for (int i = 0; i < g.edges[from].size(); ++i) {
            int to = g.edges[from][i].to;
            T cost = g.edges[from][i].cost;
            if (!used[to]) {
                dist[to] = dist[from] + cost;
                q.push(pair<T, int>(dist[to], to));
                used[to] = true;
            }
            else if (dist[to] > dist[from] + cost) {
                dist[to] = dist[from] + cost;
                q.push(pair<T, int>(dist[to], to));
            }
        }
    }
    delete[] used;
    return dist;
}




