        s--, t--;
        T[s].push_back({t, 1});
        T[t].push_back({s, 1});
    }
    long long w = tree_diamiter(T);
    if ((w + 2) % 3 == 0) {
        cout << "Second" << endl;
    } else {
        cout << "First" << endl;
    }
    return 0;
}

