int n;
vector <int> graph[200005];
int visit [200005];

int diameter () {
	int i=0;
	queue<int> q;

	q.push(1); visit[i] = 1;

	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (i=0; i<graph[u].size(); i++) {
			int v = graph[u][i];
			if (visit[v] == 0) {visit[v] = visit[u]+1; q.push(v); } 
		}
	}

	int idx=-1, val=-1;
	for (i=1; i<=n; i++) {
		val = max(val, visit[i]);
		if (val == visit[i]) idx = i;
	}

	memset(visit, 0, sizeof(visit));

	q.push(idx); visit[idx] = 1;

	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (i=0; i<graph[u].size(); i++) {
			int v = graph[u][i];
			if (visit[v] == 0) {visit[v] = visit[u]+1; q.push(v); } 
		}
	}

	idx=-1, val=1;
	for (i=1; i<=n; i++) {
		val = max(val, visit[i]);
		if (val == visit[i]) idx = i;
	}

	return val-1;
}

