//first: distance, second: farthest vertex
P farthest_v(int prev, int v) {
    P res(0, v);
    for (int to: graph[v]) if (to != prev) {
        P t = farthest_v(v, to);
        t.first++;
        if (res.first < t.first) res = t;
    }
    return res;
}

int diameter() {
    P u = farthest_v(-1, 0);
    return farthest_v(-1, u.second).first;
}

