std::pair<int,int> GetMaxInd(int in){
  std::pair<int,int> L (-1,-1);
  std::vector<int> memo(N, -1);
  std::stack<int> q;
  q.push(in); memo[in] = 0;
  while(!q.empty()){
    auto cur = q.top(); q.pop();
    for(int i=0; i<N; i++) {
      if ( A[cur][i] == 1 && memo[i] == -1 ) {
        memo[i] = (memo[cur] + 1);
        if ( L.first < memo[i] ) L = { memo[i], i } ;
        q.push(i);
      }
    }
  }
  return L;
}

int GetDiameter () {
  auto s = GetMaxInd(0);
  auto g = GetMaxInd(s.second);
  return g.first;
}

