int d[maxn];

void dfs(int v, int p) {
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i];
    if (u == p) {
      continue;
    }
    d[u] = d[v] + 1;
    dfs(u, v);
  }
}

void solve() {
  int diam;
  {
    int v = 0;
    d[v] = 0;
    dfs(v, -1);
    int u = 0;
    for (int i = 1; i < n; i++) {
      if (d[i] > d[u]) {
        u = i;
      }
