vvll in_Graph(ll nodeNum, ll edgeNum, bool isDirected){
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u;
		cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return std::move(to);
}


vvll to;
ll diameter = 0;

ll dfs(ll v, ll p){
	multiset<ll> depthSet;
	EACH(u, to[v]){
		if (u == p) continue;
		depthSet.insert(dfs(u, v));
	}
	if (depthSet.empty()) return 0;
	if (depthSet.size() == 1){
		ll depth = *(depthSet.begin());
		chmax(diameter, depth+1);
		return depth+1;
	}
	else{
		auto it = depthSet.end();
		it--;
		ll maxDepth = *it;
		it--;
		ll secDepth = *it;
		chmax(diameter, maxDepth + secDepth + 2);
		return maxDepth+1;
	}
}


void solve()
{
	ll N;
	cin >> N;
	to = in_Graph(N, N-1, false);

	dfs(0, -1);
	string ans = (diameter % 3 == 1) ? "Second" : "First";
	cout << ans << '\n';
}

int main(){
	solve();
	return 0;
}

