    Edge(ll _to, long double _cap, ll _rev) {
        to = _to;
        cap = _cap;
        rev = _rev;
    }
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void add_edge(Graph &G, ll from, ll to, long double cap, bool revFlag,
              long double revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n;
    cin >> n;
    Graph g(n);
    REP(i, n - 1) {
        ll a, b;
        cin >> a >> b;
        add_edge(g, --a, --b, 1, true, 1);
    }

    Array d(n, 0);
    auto dfs = [&](auto &&self, int v, int p) -> void {
        for(auto e : g[v]) {
            if(e.to == p)
                continue;
            d[e.to] = d[v] + 1;
            self(self, e.to, v);
        }
    };

    auto check = [&](int v) -> P {
        d[v] = 0;
        dfs(dfs, v, -1);
        ll ma = 0;
        ll ma_i = 0;
        REP(i, n) {
            if(chmax(ma, d[i]))
                ma_i = i;
        }
        return {ma, ma_i};
    };

    auto leaf = check(0).second;
    auto ma_l = check(leaf).second;
    ll ans = check(ma_l).first + 1;

    if(ans % 3 == 2)
        cout << "Second" << en;
    else
        cout << "First" << en;
}

