pii bfs(int s) {
    fill(dist + 1, dist + n + 1, inf);
    queue<int> q;
    q.push(s);
    dist[s] = 0;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int to : g[v]) {
            if (dist[to] > dist[v] + 1) {
                q.push(to);
                dist[to] = dist[v] + 1;
            }
        }
    }
    int res = -1;
    for (int v = 1; v <= n; v++) {
        if (res == -1 || dist[v] > dist[res]) {
            res = v;
        }
    }
    return make_pair(dist[res], res);
}

