        a--;b--;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }
    int s=0;
    for(int i=0;i<n;i++)if(graph[i].size()==1){
        s=i;break;
    }
    DLCA<V<V<ll>>> tree(graph);
    tree.build();
    int ma=0;
    for(int i=0;i<n;i++)if(i!=s)chmax(ma,tree.dist(s,i));
    ma--;
    if(ma%3==0)cout<<"Second"<<"\n";
    else cout<<"First"<<"\n";
}

