signed main() {
  int n;
  cin >> n;
  rep(i, 0, n - 1) {
    int a, b;
    cin >> a >> b;
    kg[--a].pb(--b);
    kg[b].pb(a);
  }

  for(int i = 2; i <= n; i += 3) win[i] = true;

  queue<int> kq;
  kq.push(0);
  s[0] = true;
  while(!kq.empty()) {
    int x = kq.front(); kq.pop();
    rep(i, 0, kg[x].size()) {
