      }
    }
  }

  queue<int> q;
  rep(i, 1, n) {
    if(kg[i].size() == 1) {
      q.push(i);
    }
  }

  int count = 0;
  while(!q.empty()) {
    count++;
    queue<int> kq;
    while(!q.empty()) {
      int x = q.front(); q.pop();
      int nxt = g[x];
      if(count > ps[nxt].second) ps[nxt].second = count;
