    queue<int> former, latter;
    former.push(0);
    int u, v;
    bool take[200020];
    take[0] = false;
    for (int i = 1; i < n; i++) take[i] = true;

    for (int i = 0; !former.empty(); i++) {
        int t = former.front();
        for (int j = 0; j < G[t].size(); j++) {
            if (take[G[t][j]]) {
                take[G[t][j]] = false;
                former.push(G[t][j]);
            }
        }
        if (former.size() == 1) u = t;
        former.pop();
    }
    //cout << "u " << u << endl;
    int q[200020];
    latter.push(u);
    for (int i = 0; i < n; i++) {
        take[i] = true;  q[i] = 0;
    }
    q[0] = 1;
    take[u] = false;

    int tmp = 0, idx = 0;
    for (int i = 0; !latter.empty(); i++) {
        int t = latter.front();
        for (int j = 0; j < G[t].size(); j++) {
            if (take[G[t][j]]) {
                take[G[t][j]] = false;
                latter.push(G[t][j]);
                q[idx + 1]++;
                //cout << G[t][j] << endl;
            }
        }
        tmp++;
        //cout << idx << " " << q[idx] << " " << tmp << endl;
        if (tmp == q[idx]) {
            idx++;  tmp = 0;
        }
        if (latter.size() == 1) return idx;
        latter.pop();
    }
}

