#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

std::vector<LL>dist;
std::vector<std::vector<LL>>G;

void dfs(LL v, LL p, LL d)
{
	dist[v] = d;
	for (LL u : G[v])
	{
		if (u != p) dfs(u, v, d + 1);
	}
}

int main()
{
	LL N;
	in >> N;
	std::vector<LL>a(N - 1), b(N - 1);
	rep(i, N - 1) in >> a[i] >> b[i];

	std::vector<LL>in_cnt(N + 1), leaves;
	LL leave_cnt = 0;
	G.resize(N + 1);
	rep(i, N - 1)
	{
		++in_cnt[a[i]];
		++in_cnt[b[i]];
		G[a[i]].push_back(b[i]);
		G[b[i]].push_back(a[i]);
	}
	for (LL i = 1; i <= N; ++i)
	{
		if (in_cnt[i] == 1)
		{
			++leave_cnt;
			leaves.push_back(i);
		}
	}

	std::vector<LL>master;
	rep(i, leaves.size())
	{
		dist.clear();
		dist.resize(N + 1);
		dfs(leaves[i], -1, 0);

		bool flag = false;
		for (LL j = 1; j <= N; ++j)
		{
			if (dist[j] == N - leave_cnt + 1)
			{
				flag = true;
				break;
			}
		}
		if (flag)
		{
			master.push_back(leaves[i]);
			for (LL j = 1; j <= N; ++j)
			{
				if (i == j) continue;
				if (dist[j] == N - leave_cnt + 1) master.push_back(j);
			}
			break;
		}
	}

	bool ans;
	if (leave_cnt == 2) ans = (N % 2 == 1);
	else
	{
		N -= (leave_cnt - 1);
		if (N % 2 == 0) ans = (master.size() % 2 == 1);
		else ans = true;
	}
	out << (ans ? "First" : "Second") << std::endl;
}

