ii dijkstra(int s){
  memset(d, INF, sizeof(d));
  priority_queue<ii, vector<ii>, greater<ii>> que;
  d[s]=0;
  que.push({d[s], s});
  while(!que.empty()){
    ii p=que.top();que.pop();
    int v=p.second;
    if(d[v]<v.first) continue;
    int M=G[v].size();
    for (int i=0;i<M;++i){
      int nv=G[v][i];
      if(d[nv]>v.first+1){
        d[nv]=v.first+1;
        que.push({d[nv], nv});
      }
    }
  }

  int dist=0, ans=s;
  for (int i=0;i<N;++i){
    if(dist<d[i]){dist=d[i];ans=i;}
  }
  return {dist, ans};
}

int tree_diam(){
  ii p=dijkstra(s);
  int u=p.second;
  ii q=dijkstra(u);
  int ans=q.first;
  return ans; 
}

