int main() {
  int n = IN;
  VVI graph(n);
  rep(n-1) {
    int u = IN, v = IN;
    u--; v--;
    graph[u].push_back(v);
    graph[v].push_back(u);
  }
  VI dist(n), par(n);
  stack<int> s;
  s.push(0); dist[0] = 0; par[0] = -1;
  while (not s.empty()) {
    int v = s.top(); s.pop();
    for (auto next : graph[v]) if (next != par[v]) {
      dist[next] = dist[v] + 1;
      par[next] = v;
      s.push(next);
    }
  }
  int f = max_element(all(dist)) - dist.begin();
  dist = par = VI(n);
  s.push(f); dist[f] = 0; par[f] = -1;
  while (not s.empty()) {
    int v = s.top(); s.pop();
    for (auto next : graph[v]) if (next != par[v]) {
      dist[next] = dist[v] + 1;
      par[next] = v;
      s.push(next);
    }
  }
  int d = *max_element(all(dist));
  OUT((d+1) % 3 == 2 ? "Second" : "First");
}

