#define ALL(x) x.begin(), x.end()

const llong inf = 1100100100100100ll;
const llong mod = 1e9+7;

llong N;
vector<vector<llong> > edges;

P dfs(int start) {
	queue<P> q;
	vector<bool> use(N, false);
	P lst;

	q.push(P(start, 1));
	while(q.size()) {
		P now = q.front();
		q.pop();

		lst = now;
		for (auto edge : edges[now.first]) {
			if (use[edge]) continue;
			use[edge] = true;
			P next(edge, now.second+1);
			q.push(next);
		}
	}

	return lst;
}

