		a--, b--;
		edges[a].push_back(b);
		edges[b].push_back(a);
	}

	P n = dfs(0);
	n = dfs(n.first);
	if (n.second%3 == 2)
		cout << "Second" << endl;
	else
		cout << "First" << endl;

	return 0;
}

