int double_sweep(const auto & g){
  int n = sz(g);
  int x = 0;
  int max_d = 0;
  auto dfs = [&](const auto& dfs, auto& d, int u, int cost) -> void {
    each(v, g[u]){
      if (d[v]<INF) continue;
      d[v] = cost+1;
      if (d[v]>max_d){
        chmax(max_d, d[v]);
        x = v;
      }
      dfs(dfs, d, v, cost+1);
    }
  };

  vi d0(n, INF); d0[0] = 0;  // distance from 0
  dfs(dfs, d0, 0, 0);
  vi dx(n, INF); dx[x] = 0;  // distance from x
  int a = x;  // 保存

  max_d = 0;
  dfs(dfs, dx, x, 0);
  int b = x;

  return max_d; // d(a,b) == max_d;
}

