template <typename T> bool chmax(T &a, const T b){if(a < b){a = b;return true;}return false;}

vector<ll> bfs(ll top, vector<vector<ll>>& graph)
{
    ll i,j;
    queue<ll> que;
    ll n = graph.size();
    vector<ll> vdis(n,-1);
    vdis.at(top) = 0;
    que.emplace(top);
    while(!que.empty()){
        ll now = que.front();
        que.pop();
        ll dist = vdis.at(now);
        for(i = 0;i < graph.at(now).size();++i){
            ll next = graph.at(now).at(i);
            if(vdis.at(next) == -1){
                vdis.at(next) = dist+1;
                que.emplace(next);
            }
        }
    }
    return vdis;
}

