using P = pair<int, int>;

vector<vector<int>> g(200010);

// distance, vertex
P dfs(int cur, int pre)
{
    int p = -1, ma = -1;
    for (auto v : g[cur])
    {
        if (v == pre)
            continue;
        auto ret = dfs(v, cur);
        if (ret.first > ma)
        {
            ma = ret.first;
            p = ret.second;
        }
    }
    if (ma == -1)
    {
        return P(0, cur);
    }
    return P(ma + 1, p);
}

