template<class T>
struct WG
{
	int to;
	T cost;
	WG(int a, T b) : to(a), cost(b) {}
};

template< typename T >
pair< T, int > dfs(const vector<vector<WG<T>>> &g, int idx, int par) {
  pair< T, int > ret(0, idx);
  for(auto &e : g[idx]) {
    if(e.to == par) continue;
    auto cost = dfs(g, e.to, idx);
    cost.first += e.cost;
    ret = max(ret, cost);
  }
  return ret;
}

template< typename T >
T tree_diameter(const vector<vector<WG<T>>> &g) {
  auto p = dfs(g, 0, -1);
  auto q = dfs(g, p.second, -1);
  return (q.first);
}

