struct Diameter{
    vector<int> center;
    int N;

    pair<vector<int>, vector<int>> calc_dist(int start, const vector<int> G[]){
        vector<int> dist(N, -1), prev(N);
        dist[start] = 0;
        prev[start] = -1;
        queue<int> que;
        que.push(start);
        while(que.size()){
            int i = que.front(); que.pop();
            for(auto j : G[i]){
                if(dist[j] == -1){
                    dist[j] = dist[i]+1;
                    prev[j] = i;
                    que.push(j);
                }
            }
        }
        return {dist, prev};
    }

    int calculate(int n, const vector<int> G[]){
        N = n;
        auto res1 = calc_dist(0, G);
        auto d1 = res1.first;
        int v1 = max_element(d1.begin(), d1.end()) - d1.begin();
        auto res2 = calc_dist(v1, G);
        auto d2 = res2.first;
        auto p2 = res2.second;
