        diameter = max(diameter, leafdis[node]);
    } else {
        sort(leafdis_val.begin(), leafdis_val.end());
        reverse(leafdis_val.begin(), leafdis_val.end());
        diameter = max(diameter, leafdis_val[0] + leafdis_val[1] + 1);
    }
}


