pair < int, int > dfs (int s) {
  vector < int > d(N, INT_MAX);
  d[s] = 0;
  queue < int > q;
  vector < bool > used(N, false);
  used[s] = true;
  q.push(s);
  int mx = s, mx_dis = 0;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    for (auto to : adj[u]) {
      if (!used[to]) {
        d[to] = d[u] + 1;
        if (d[to] > mx_dis) {
          mx_dis = d[to];
          mx = to;
        }
        used[to] = true;
        q.push(to);
      }
    }
  }
  return {mx, mx_dis};
}

