// pii<distance, v>
pii dfs(int v, int par = -1) {
    pii r = {0, v};
    for (int to : g[v]) {
        if (to == par) {
            continue;
        }
        pii t = dfs(to, v);
        t.first += 1;
        if (t.first > r.first) {
            r = t;
        }
    }
    return r;
}

int diameter() {
    pii s = dfs(0);
    pii t = dfs(s.second);
    return t.first;
}

bool solve() { return diameter() % 3 != 1; }

