    dp[i] = i % 2;
  }
  for (int i = 3; i <= siz; i++) {
    if (dp[i - 1] == 0 || dp[i - 2] == 0) {
      dp[i] = 1;
    } else {
      dp[i] = 0;
    }
  }
  cerr << siz << endl;
  cout << (dp[siz] ? "Second" : "First") << endl;
  return 0;
}

