{
	Graph_func graph;
	int ans;
	graph.read_edge();
	graph.adjini();
	ans = graph.diameter();
	//cout << ans << endl;
	if (ans % 3 != 1)
		cout << "First" << endl;
	else
		cout << "Second" << endl;
	return 0;
}

