using namespace std;

int n;
vector<vector<int> > neigh;

pair<int, int> Find_furthest(int start){
    vector<bool> is_visited(n, false);
    queue<int> indices, dist;
    is_visited[start] = true;
    indices.push(start);
    dist.push(0);
    int ans_i = -1, ans_dist = -1;
    while (!indices.empty()){
        int a = indices.front();
        if (dist.front() > ans_dist){
            ans_dist = dist.front();
            ans_i = a;
        }
        for (int b : neigh[a])
            if (!is_visited[b]){
                is_visited[b] = true;
                indices.push(b);
                dist.push(dist.front() + 1);
            }
        indices.pop();
        dist.pop();
    }
    return {ans_i, ans_dist};
}

int main(){
    cin.tie(NULL);
    ios_base::sync_with_stdio(false);
    cin >> n;
    neigh.resize(n);
    FOR (i, n - 1){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    FOR (i, n)
        if (neigh[i].size() == 1){
            int max_dist = Find_furthest(Find_furthest(i).first).second;
            if (max_dist % 3 == 1)
                cout << "Second" << endl;
            else
                cout << "First" << endl;
            return 0;
        }
}

#include <bits/stdc++.h>
using namespace std;

static const int MAX = 200005;
static const int INF = 1e9;

// 隣接リストを用いた幅優先探索 O(|V|+|E|)
vector<int> G[MAX], d(MAX, INF); // 始点sから頂点iまでの最短距離をd[i]に記録
// main関数からこれらを削除すること

void bfs(int s) {
  queue<int> q;
  q.push(s);
  d[s] = 0;
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int v = 0; v < G[u].size(); v++) {
      if (d[G[u][v]] == INF) {
        d[G[u][v]] = d[u] + 1;
        q.push(G[u][v]);
      }
    }
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  // 無向(有向)グラフの隣接リスト
  int n; // n:頂点数
  cin >> n;

  //vector<int> G[n]; // G:頂点数がnのグラフを表す隣接リスト

  int u, v;
  for (int i = 0; i < n - 1; i++) {
    cin >> u >> v;
    u--;
    v--;
    G[u].emplace_back(v);
    G[v].emplace_back(u); // 有向グラフではこの行をコメントアウト
  }

  bfs(0);

  int now = 0, maxd = 0;
  for (int i = 0; i < n; i++) {
    if (d[i] > maxd) {
      now = i;
      maxd = d[i];
    }
  }

  fill(d.begin(), d.end(), INF);
  bfs(now);

  int dia = 0;
  for (int i = 0; i < n; i++) {
    dia = max(dia, d[i]);
  }

  if (dia % 3 == 1) cout << "Second\n";
  else cout << "First\n";
}

