        edgelist[b].pb(a);
    }
}

void f_maxd(ll &ev, ll &dis, const V<ll> edgelist[], ll n, ll sv)
{
    ll dlist[200005];
    rep (i, 200005) dlist[i] = -1;

    queue<ll> q;
    q.push(sv);
    dlist[sv] = 0;
    dis = 0;

    while (q.size()) {
        ll v = q.front(); q.pop();
        ll d = dlist[v];
        for (auto nv : edgelist[v]) {
            if (dlist[nv] >= 0) continue;
            dlist[nv] = d+1;
            if (dis < d+1) {
                dis = d+1;
                ev = nv;
            }
            q.push(nv);
        }
    }
}

