		cin >> x >> y;
		graph[x].push_back(y);
		graph[y].push_back(x);
	}

	int res = diameter();

	//cout << res << endl;

	if (res == 1) cout << "First" << endl;
	else if (res == 2) cout << "Second" << endl;
	else {

		if (res%3 == 0) cout << "First" << endl;
		else cout << "Second" << endl;

	}

	return 0;
}

