vector<vector<int> > ns;

pair<int, int> diameter(int n, int prev){
    if(ns.at(n).size() == 1 && ns.at(n).at(0) == prev){
        return make_pair(0, 1);
    }
    int d = 0;
    int h1 = 0;
    int h2 = 0;
    for(int n2 : ns.at(n)){
        if(n2 == prev){ continue; }
        auto res = diameter(n2, n);
        d = max(d, res.first);
        if(res.second > h1){
            h2 = h1;
            h1 = res.second;
        }else if(res.second > h2){
            h2 = res.second;
        }
    }
    return make_pair(max(d, h1 + h2 + 1), h1 + 1);
}

