int opposite = 0;
int max_dist = 0;

void f(int index,int x){
  int dx = d[index][x];
  if(dx > max_dist){
    opposite = x;
    max_dist = dx;
  }
  int s = edge[x].size();
  for(int i=0;i<s;i++){
    int y = edge[x][i];
    if(d[index][y] == INF){
      d[index][y] = dx+1;
      f(index,y);
    }    
  }
  return;
}

