pair<int, int> bfs(const vector<vector<int>> &g, int s) {
	queue<int> que;
	que.push(s);

	vector<pair<int, int>> dist(g.size());
	for (int i = 0; i < g.size(); i++) {
		dist[i].first = i;
		dist[i].second = -1;
	}
	dist[s].second = 0;

	int now = s;
	while (!que.empty()) {
		now = que.front(); que.pop();
		for (auto next : g[now]) {
			if (dist[next].second != -1) {
				continue;
			}

			dist[next].second = dist[now].second + 1;
			que.push(next);
		}
	}

	return dist[now];
}

