pair<int, int> dfs(int v, int prev, vector<vector<int> > &G) {
    pair<int, int> res = make_pair(v, 0);
    for (int i=0; i<(int)G[v].size(); ++i) {
        if (G[v][i] != prev) {
            auto t = dfs(G[v][i], v, G);
            t.second += 1;
            if (res.second < t.second) {
                res = t;
            }
        }
    }
    return res;
}

int diameter(vector<vector<int> > &G) {
    auto u = dfs(1, -1, G);
    auto v = dfs(u.first, -1, G);
    return v.second;
