  int ans = 0, num = x;
  vector<int> dis;
  queue<int> qu;
  dis.assign(n, n + 1);
  qu.push(x);
  dis[x] = 0;
  while(qu.size() > 0) {
    int now = qu.front();
    qu.pop();
    for(int i = 0; i < edge[now].size(); ++i) {
      int nextp = edge[now][i];
      if(dis[nextp] <= dis[now] + 1) continue;
      dis[nextp] = dis[now] + 1;
      if(ans < dis[nextp]) {
        ans = dis[nextp];
        num = nextp;
      }
      qu.push(nextp);
    }
  }
  mdis = ans;
  return num;
}

