using namespace std;

unordered_multimap<int, int> tree;
int num[200001] = { 0 };

int num_path(int p, unordered_multimap<int, int>& trees)
{
	FOR_LE(i, 0, 200000) {
		num[i] = -1;
	}
	queue<int> search;
	search.push(p);
	num[p] = 0;

	while (!search.empty()) {
		int p2 = search.front();
		search.pop();

		auto it = trees.find(p2);
		while (it != trees.end() && it->first == p2) {
			if (num[it->second] != -1) {
				it++;
				continue;
			}

			num[it->second] = num[it->first] + 1;
			search.push(it->second);
			it++;
		}
	}

	int ans = 0;
	FOR_LE(i, 0, 200000) {
		ans = max(num[i], ans);
	}

	return ans;
}

