	}

	// 末端の数
	int p = 0;
	int count = 0;
	for (auto elem : tree) {
		if (elem.first != p) {
			if (count == 1) {
				p = elem.first;
				break;
			}
			p = elem.first;
		}
		count++;
	}

	int path = num_path(p, tree);

	if ((path - 1) % 3 != 0) {
		cout << "First" << endl;
	}
	else {
		cout << "Second" << endl;
	}

	return 0;
}

