using Graph = vector<vector<ll>>;
pll dfs(ll now, ll par, Graph &G){
	pll res = {0, now};
	for(auto next: G[now]){
		if(next == par) continue;
		auto cost = dfs(next, now, G);
		cost.first++;
		res = max(res, cost);
	}
	return res;
}

ll tree_diameter(Graph &G){
	auto p = dfs(0, -1, G);
	auto q = dfs(p.second, -1, G);
	// (p.second, q.second) is the diameter
	return q.first;
}

