struct edge{ll to; ll cost;};
struct graph{
    ll N;
    vector<vector<edge> > G;
    vector<bool> used;
    vector<ll> depth;
    ll maxd=-1;
    ll dnode;

    graph(ll n): N(n), G(N), used(N,false), depth(N,-1) {}

    void add_edge(ll s, ll t, ll cost=1){
        G[s].emplace_back((edge){t,cost});
        G[t].emplace_back((edge){s,cost}); //無向ならON
    }

    void dfs(ll v=0, ll d=0){
        used[v]=true;
        depth[v]=d;
        if(maxi(maxd,d)) dnode=v; //一番深いノードを更新
        for(auto E : G[v]){
            if(!used[E.to]){
                dfs(E.to, d+E.cost);
            }
        }
    }

    ll delimiter(){
        dfs();
        rep(i,N) used[i]=false;
        dfs(dnode);
        return maxd;
    }
};
