int calc_diameter(vec<vec<int>>& adj) {
    pint farthest_node = farthest_node_from(0, adj);
    pint node_of_diameter = farthest_node_from(farthest_node.first, adj);
    return node_of_diameter.second + 1;
}

pint farthest_node_from(int node, vec<vec<int>>& adj) {
    int num_nodes = adj.size();
    vec<int> distance_of(num_nodes, -1);
    vec<int> stack;
    stack.emplace_back(node);
    distance_of.at(node) = 0;
    while (!stack.empty()) {
        int node = stack.back(); stack.pop_back();
        for (auto neighbor : adj.at(node)) {
            if (distance_of.at(neighbor) != -1) continue;
            distance_of.at(neighbor) = distance_of.at(node) + 1;
            stack.emplace_back(neighbor);
        }
    }
    pint node_with_maxdist = {-1, -1};
    range(node, 0, num_nodes) {
        if (distance_of.at(node) > node_with_maxdist.second) {
            node_with_maxdist = {node, distance_of.at(node)};
        }
    }
    return node_with_maxdist;
}

