       o => 負け
       o-o => 勝ち
       つまり, 最大を与えるような組みの距離が 3の倍数のあまりによって決定する
       < 木の最大距離のペアを見つけてその長さを求む！ >
       もし, 最大のルートの頂点を選べば => 最大 + 2番目の最大
       そうでない頂点を選んだら => ルートに繋がる距離を考えると、最大距離を与える場所は,
       最大距離を与えるペアの一方では＞
    */
    int farAway;
    std::queue<int> B; B.push(0);
    Vint C(n, -1); C[0] = 0;
    while(not B.empty()){
        int p = B.front(); B.pop();
        vREP(ele, A[p]) if(C[ele] == -1){
            C[ele] = C[p] + 1; B.push(ele);
        }
