typedef vector< vector<int> > Graph;

int getFar(const Graph& g, int start){
  const int kInf = 1234567;
  int n = g.size();
  vector<int> dist(n, kInf);
  dist[start] = 0;
  queue<int> qu;
  qu.push(start);
  int res = start;
  while(!qu.empty()){
    int p = qu.front();
    qu.pop();
    res = p;
    rep(i, g[p].size()){
      int next = g[p][i];
      if(dist[next] < dist[p]+1) continue;
      dist[next] = dist[p]+1;
      qu.push(next);
    }
  }
  return res;
}

