vector<vector<int>>graph;
vector<int>depth;
int start;
void dfs(int v) {
	for (auto next : graph[v]) {
		if (depth[next] == 0 && next != start) {
			depth[next] = depth[v] + 1;
			dfs(next);
		}
	}
}
int main() {
	int n; cin >> n;
	graph = vector<vector<int>>(n);
	for (int i = 0; i < n - 1; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		graph[a].push_back(b); graph[b].push_back(a);
	}

	depth = vector<int>(n);	start = 0;
	dfs(start);
	int best = 0; int how = 0;
	for (int i = 0; i < n; i++) {
		if (how < depth[i]) {
			how = depth[i];
			best = i;
		}
	}

	depth = vector<int>(n);	start = best;
	dfs(start);
	how = 0;
	for (int i = 0; i < n; i++) how = max(how, depth[i]);

	cout << (how % 3 == 1 ? "Second" : "First") << endl;
	return 0;
}

