pair <int, int> diam(int u)
{
    used[u] = 1;
    auto x = mp(0 , u);
    for (auto v : g[u])
    {
        if(!used[v])
        {
            auto nw = diam(v);
            nw = mp(nw.fst + 1 , nw.snd);
            x = max(x, nw);
        }
    }
    return x;
}
