using namespace std;
typedef long long int ll;
typedef pair<int, int> P;
template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

const int limit = 200005;
using edge = struct {int to; long long cost;};

int n;
vector<edge> tree[limit];
vector<long long> dist;

bool brunch;

void dfs(int v, long long d = 0, int p = -1){
    dist[v] = d;
    int cnt = 0;
    for(auto &e : tree[v]) {
        if(e.to == p) continue;
        dfs(e.to, d + e.cost, v);
        ++cnt;
    }
    if(cnt > 1) brunch = true;
}

vector<long long> calcDist(int s){
    dist = vector<long long>(n);
    dfs(s);
    return dist;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    for(int i = 0; i < n-1; i++){
        int a, b, c;
        cin >> a >> b;
        a--, b--;
        c = 1;
        tree[a].push_back({b, c});
        tree[b].push_back({a, c});
    }
    brunch = false;
    vector<ll> dist1 = calcDist(0);
    int src = 0;
    ll mxDist = 0;
    rep(i,n){
        if(dist1[i] > mxDist){
            mxDist = dist1[i];
            src = i;
        }
    }
    vector<ll> dist2 = calcDist(src);
    rep(i,n){
        chmax(mxDist, dist2[i]);
    }
    if(mxDist%2 == 0){
        if(brunch) cout << "Second" << endl;
        else cout << "First" << endl;
    }
    else cout << "First" << endl;
    return 0;
}

