int solve(int a, int turn) {
    if(memo[a][turn]!=-1)return memo[a][turn];
    if(turn==0) {
        //takahashi's turn
        if(a==1)return 1;
        if(a==0||a==2)return 0;
        //cout<<solve(a-1, turn^1)<<" "<<solve(a-2)
        return memo[a][turn] = solve(a-1, turn^1)|solve(a-2, turn^1);
    }else {
        //aoki's turn
        if(a==0||a==2)return 1;
        if(a==1)return 0;
        return memo[a][turn] = solve(a-1, turn^1)&solve(a-2, turn^1);
    }
}
