ll diam(vector<vector<edge>> g, ll N) {

	queue<ll> q;
	vector<ll> dis(N + 1, -1);
	dis[1] = 0;
	q.push(1);

	while (!q.empty()) {
		ll v = q.front();
		q.pop();

		for (edge e : g[v]) {
			if (dis[e.to] != -1) { continue; }
			q.push(e.to);
			dis[e.to] = dis[v] + e.d;
		}
	}

	ll maxdis = -INF;
	ll maxid = 1;
	repn(i, N) {
		if (maxdis < dis[i]) {
			maxdis = dis[i];
			maxid = i;
		}
	}

	vector<ll> dis2(N + 1, -1);
	dis2[maxid] = 0;
	q.push(maxid);

	while (!q.empty()) {
		ll v = q.front();
		q.pop();

		for (edge e : g[v]) {
			if (dis2[e.to] != -1) { continue; }
			q.push(e.to);
			dis2[e.to] = dis2[v] + e.d;
		}
	}

	ll ret = -INF;
	repn(i, N) {
		ret = max(ret, dis2[i]);
	}

	return ret;

}


