#include <bits/stdc++.h>
using namespace std;

#define SIZE 200010

typedef struct _Edge {
    int to, next;
} Edge;

Edge edge[SIZE << 1];
int head[SIZE], edgePt, vertexNum;
int deg[SIZE];

pair<int, int> dp[SIZE];
int maxLen, num;

void addEdge(int from, int to) {
    edge[edgePt] = {to, head[from]};
    head[from] = edgePt++;
}

void dfs(int cntPt, int fatherPt) {
    dp[cntPt].first = 0;
    dp[cntPt].second = 1;

    for (int i = head[cntPt]; i != -1; i = edge[i].next) {
        int nextPt = edge[i].to;
        if (nextPt == fatherPt)
            continue;
        dfs(nextPt, cntPt);

        int cntLen = dp[nextPt].first + 1;
        if (cntLen + dp[cntPt].first > maxLen) {
            maxLen = cntLen + dp[cntPt].first;
            num = dp[cntPt].second * dp[nextPt].second;
        } else if (cntLen + dp[cntPt].first == maxLen) {
            num += dp[cntPt].second * dp[nextPt].second;
        }

        if (cntLen > dp[cntPt].first) {
            dp[cntPt].first = cntLen;
            dp[cntPt].second = dp[nextPt].second;
        } else if (cntLen == dp[cntPt].first) {
            dp[cntPt].second += dp[nextPt].second;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);
    memset(head, -1, sizeof(head));
    memset(deg, 0, sizeof(deg));
    edgePt = 0;
    cin >> vertexNum; int maxDeg = 0;
    for (int i = 1; i < vertexNum; i++) {
        int from, to;
        cin >> from >> to;
        from--; to--;
        addEdge(from, to);
        addEdge(to, from);
        deg[from]++; deg[to]++;
        maxDeg = max(maxDeg, max(deg[from], deg[to]));
    }

    maxLen = 0, num = 0;
    dfs(0, -1); maxLen++;
    int ans = maxLen % 3;
    if (vertexNum == 2 || ((maxLen - 1) >> 1) * maxDeg + 1 == vertexNum) {
        ans = !ans;
    }
    cout << (ans ? "Second\n" : "First\n");
    return 0;
}

