VI tree_diameter(VVI &e){
    int n = e.size();
    VI dist(n, -1);
    queue<int> que;
    que.push(0);
    dist[0] = 0;
    while (!que.empty()){
        int x = que.front();
        que.pop();
        for (int y : e[x]){
            if (dist[y] == -1){
                dist[y] = dist[x] + 1;
                que.push(y);
            }
        }
    }
    int r = max_element(ALL(dist)) - dist.begin();
    dist.assign(n, -1);
    que.push(r);
    dist[r] = 0;
    while (!que.empty()){
        int x = que.front();
        que.pop();
        for (int y : e[x]){
            if (dist[y] == -1){
                dist[y] = dist[x] + 1;
                que.push(y);
            }
        }
    }
    int s = max_element(ALL(dist)) - dist.begin();
    VI ret;
    while (s != r){
        ret.push_back(s);
        for (int x : e[s]){
            if (dist[x] == dist[s] - 1){
                s = x;
                break;
            }
        }
    }
    ret.push_back(r);
    return ret;
}

