vector<ll> dfs(ll now, ll before, ll len, vector<vector<ll>>& connection) {
  if ((connection.at(now).size() == 1) && (before != -1)) {
    return {len, now};
  }
  vector<ll> res = {0, now};
  for (ll i = 0; i < connection.at(now).size(); ++i) {
    ll next = connection.at(now).at(i);
    if (next == before) {
      continue;
    }
    vector<ll>  temp = dfs(next, now, len + 1, connection);
    if (temp.at(0) > res.at(0)) {
      res = temp;
    }
  }
  // res.at(0) += len;
  return res;
}

int main() {
  ios::sync_with_stdio(false);
