  ll N;
  cin >> N;
  vector<vector<ll>> connection(N);
  for (ll i = 0; i < N - 1; ++i) {
    ll a, b;
    cin >> a >> b;
    a -= 1;b -= 1;
    connection.at(a).push_back(b);
    connection.at(b).push_back(a);
  }
  vector<bool> visted(N, false);
  visted.at(0) = true;
  ll now = 0;
  ll L;
  while (true) {
    vector<ll> temp = dfs(now, -1, 0, connection);
    if (visted.at(temp.at(1)) == true) {
      L = temp.at(0);
      break;
    }
    visted.at(temp.at(1)) = true;
    now = temp.at(1);
  }
  L += 1;
  if (L % 3 == 2) {
    cout << "Second" << "\n";
  }
  else {
    cout << "First" << "\n";
  }
}

