  while(!q.empty()) {
    count++;
    queue<int> kq;
    while(!q.empty()) {
      int x = q.front(); q.pop();
      int nxt = g[x];
      if(count > ps[nxt].second) ps[nxt].second = count;
      if(ps[nxt].second > ps[nxt].first) swap(ps[nxt].second, ps[nxt].first);
