    pre[t] = last[x];
    tar[t] = y;
    last[x] = t;
}

void bfs(int st)
{
    l = 1, r = 1;
    q[1] = st;
    memset(h, 0, sizeof(h));
    h[st] = 1;
    while (l <= r)
    {
        int x = q[l++];
