int sub(int u, int p=-1){
    vi ds;
    for (int v: nxt[u]){
        if (v==p) continue;
        int d = sub(v, u) + 1;
        ds.pb(d);
    }
    sort(ALL(ds));
    int L = ds.size();
    if (L == 0) {
        return 0;
    } else if (L == 1) {
        amax(diameter, ds[0]);
        return ds[0];
    } else {
        amax(diameter, ds[L-1] + ds[L-2]);
        return ds[L-1];
    }
}

bool solve(int N, vi& a, vi& b) {
    nxt.resize(N);
    rep(i,N-1){
        nxt[a[i]].pb(b[i]);
        nxt[b[i]].pb(a[i]);
    }
    diameter = 0;
    sub(0);

    vector<bool> dp(diameter+1, false);
    dp[0] = true;
    dp[1] = false;
    for(int i=2; i<=diameter; ++i) {
        if (dp[i-1]==false || dp[i-2]==false) dp[i] = true;
    }
    return dp[diameter];
}

