using namespace std;

int FindFurthest(vector<vector<int> > &adj_nodes, int start, int* p_furthest)
{
  int N = adj_nodes.size();
  vector<bool> visited(N, false);
  int remaining = N;

  queue<int> q;
  q.push(start);
  visited[start] = true;
  --remaining;
  queue<int> nq;

  int dist = 1;
  bool done = false;
  while (remaining > 0) {
    while (not q.empty()) {
      int x = q.front();
      q.pop();
      for (auto nx : adj_nodes[x]) {
	if (not visited[nx]) {
	  nq.push(nx);
	  visited[nx] = true;
	  --remaining;
	  if (remaining == 0) {
	    *p_furthest = nx;
	    done = true;
	    break;
	  }
	}
      }
      if (done) break;
    }
    if (done) break;
    swap(q, nq);
    ++dist;
  }

  return dist;
}

int main()
{
  int N;
  cin >> N;

  vector<vector<int> > adj_nodes(N);

  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    adj_nodes[a].push_back(b);
    adj_nodes[b].push_back(a);
  }

  int dist;
  int furthest;
  dist = FindFurthest(adj_nodes, 0, &furthest);
  int furthest2;
  dist = FindFurthest(adj_nodes, furthest, &furthest2);

  if (dist % 3 == 1) cout << "Second" << endl;
  else cout << "First" << endl;

  return 0;
}

