void dijkstra(int s) {
  fill(d, d+V, INF);
  priority_queue<Pii, vector<Pii>, greater<Pii> > pque;
  d[s] = 0;
  pque.push(Pii(0, s));


  while (!pque.empty()) {
    Pii p = pque.top(); pque.pop();
    int v = p.second;
    if (d[v] < p.first) continue;
    for (int i = 0; i < (int)G[v].size(); ++i) {
      edge e = G[v][i];
      if (d[e.to] > d[v] + e.cost) {
        d[e.to] = d[v] + e.cost; 
        pque.push(Pii(d[v]+ e.cost, e.to));
      }
    }
  }
}

int dfs(int v, int& radius) {
  int ma1 = -1, ma2 = -1;
  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i].to;
    if (d[u] > d[v]) {
      int t = dfs(u, radius);
      if (t >= ma1) {
        ma2 = ma1;
        ma1 = t;
      } else if (t >= ma2) {
        ma2 = t;
      }
    }
  }
  if (ma1 < 0) {
    return 1;
  } else if (ma2 < 0) {
    radius = max(radius, ma1+1);
    return ma1+1;
  } else {
    radius = max(radius, ma1+ma2+1);
    return ma1+1;
  }

}


