        priority_queue<Element> pq;

        cost1[0] = 0;
        pq.push({ 0, 0 });
        while (!pq.empty()) {
            auto t = pq.top();
            pq.pop();

            for (auto next : edges[t.node]) {
                if (t.cost + 1 < cost1[next]) {
                    cost1[next] = t.cost + 1;
                    pq.push({ t.cost + 1, next });
                }
            }
        }
    }

    ll max_cost = 0, max_index = -1;
    for (ll i = 0; i < N; i++) {
        if (cost1[i] > max_cost) {
            max_cost = cost1[i];
            max_index = i;
        }
