i64 tree_diameter(const vector<vector<i64>>& g) {
    auto dfs = FIX([&g](auto&& self, i64 v, i64 parent) -> pair<i64,i64> {
        pair<i64,i64> res{0,v};

        for(i64 to : g[v]) {
            if(to == parent) continue;
            auto p = self(to,v);
            chmax(res, make_pair(p.first+1,p.second));
        }

        return res;
    });

    auto p1 = dfs(0,-1);
    auto p2 = dfs(p1.second,-1);

    return p2.first;
}

void solve() {
    i64 N = RD();

    vector<vector<i64>> G(N);
    REP(_, N-1) {
        i64 a = RD1();
        i64 b = RD1();
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    DBG(G);

    i64 d = tree_diameter(G);
    DBG(d);

    bool ans = d%3 != 1;

    PRINTLN(ans ? "First" : "Second");
}

signed main() {


    solve();

    return 0;
}

