typedef vector< vector<int> > Graph;

int getFar(const Graph& g, int start){
  const int kInf = 1234567;
  int n = g.size();
  vector<int> dist(n, kInf);
  dist[start] = 0;
  queue<int> qu;
  qu.push(start);
  int res = start;
  while(!qu.empty()){
    int p = qu.front();
    qu.pop();
    res = p;
    rep(i, g[p].size()){
      int next = g[p][i];
      if(dist[next] < dist[p]+1) continue;
      dist[next] = dist[p]+1;
      qu.push(next);
    }
  }
  return res;
}

int main(){
  int N;
  cin >> N;
  Graph g(N);
  rep(i, N - 1){
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int s = getFar(g, 0);

  queue<int> qu;
  qu.push(s);
  int dis = 0;
  const int kInf = 1234567;
  int n = g.size();
  vector<int> dist(n, kInf);
  dist[s] = 0;
  while(!qu.empty()){
    dis++;
    int p = qu.front(); qu.pop();
    rep(i, g[p].size()){
      int next = g[p][i];
      if(dist[next] < dist[p]+1) continue;
      dist[next] = dist[p]+1;
      qu.push(next);
    }
  }

  int ans = 1;
  while(dis > 0){
    dis -= 2;
    ans = 1 - ans;
  }
  puts(ans ? "First" : "Second");
  return 0;
}

