  d[s] = 0;
  queue<int> q;
  q.push(s);
  while(!q.empty()) {
    int i = q.front();
    q.pop();
    for (int j : g[i]) {
      if (d[j] > d[i]+1) {
        d[j] = d[i]+1;
        q.push(j);
      }
    }
  }
  auto itr = max_element(ALL(d));
  return make_pair(itr-begin(d), *itr);
}

