int n,m,edgenum,head[200005],f[200005],dep[200005],max1[200005],max2[200005],pa[200005];
void add(int u,int v)
{
	e[++edgenum].to=v;
	e[edgenum].nxt=head[u];
	head[u]=edgenum;
}
void dfs(int node)
{
	dep[node]=dep[pa[node]]+1;
	max1[node]=max2[node]=dep[node];
	for(int hd=head[node];hd;hd=e[hd].nxt)
	{
		int to=e[hd].to;
		if(to==pa[node])continue;
		pa[to]=node;
		dfs(to);
		if(max1[to]>max1[node])max2[node]=max1[node],max1[node]=max1[to];
		else if(max1[to]>max2[node])max2[node]=max1[to];
	}
	m=max(m,max1[node]+max2[node]-2*dep[node]);
}
