Graph<int> G;

vi dist;

void calc_dist(int pos, int par) {
    for (auto e : G[pos]) {
        if (e.to == par) continue;
        dist[e.to] = dist[pos] + 1;
        calc_dist(e.to, pos);
    }
}

int main(void) {
    int N;
    cin >> N;
    G = Graph<int>(N);
    rep(i, N - 1) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a].push_back(Edge<int>{a, b, 1});
        G[b].push_back(Edge<int>{b, a, 1});
    }
    dist = vi(N, 0);
    calc_dist(0, -1);
    int tip = 0;
    int dmax = 0;
    rep(i, N) {
        if (dist[i] > dmax) {
            dmax = dist[i];
            tip = i;
        }
    }
    dist = vi(N, 0);
    calc_dist(tip, -1);
    dmax = 0;
    rep(i, N) {
        chmax(dmax, dist[i]);
    }
    dump(dmax);
    if (dmax % 3 == 1) {
        cout << "Second" << endl;
    } else {
        cout << "First" << endl;
    }

    return 0;
}

