const int maxn = 2e5 + 5;

int n;
int can[maxn];
int d[maxn];
vector<int> adj[maxn];

void dfs(int u, int p) {
    for (auto v : adj[u]) {
        if (v == p) continue;
        d[v] = d[u] + 1;
        dfs(v, u);
    }
}

int main() {
    cin >> n;

    can[1] = 1;
    can[2] = 0;

    rep(i, 3, maxn) {
        if (!can[i - 1] || !can[i - 2]) can[i] = 1;
        else can[i] = 0;
    }

    rep(i, 0, n - 1) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        adj[x].pb(y);
        adj[y].pb(x);
    }

    d[0] = 1;
    dfs(0, -1);

    int found = -1;
    rep(i, 0, n) {
        if (!~found || d[found] < d[i]) {
            found = i;
        }
    }
    d[found] = 1;
    dfs(found, -1);
    int res = -1;
    rep(i, 0, n) {
        res = max(res, d[i]);
    }

    cout << (can[res] ? "First" : "Second");

    return 0;
}

