    int u = q.front(); q.pop();
    int &up = prts[u], vd = ds[u] + 1;
    vi &nbru = nbrs[u];
    for (vi::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int &v = *vit;
      if (v != up) {
	cns[u]++;
	prts[v] = u;
	ds[v] = md0[v] = md1[v] = vd;
	q.push(v);
      }
    }
  }

  for (int i = 0; i < n; i++)
    if (cns[i] == 0) q.push(i);

  int maxd = 0;
  while (! q.empty()) {
