      else if (md1[up] < md0[u]) md1[up] = md0[u];
      if (--cns[up] == 0) q.push(up);
    }
  }
  //printf("maxd=%d\n", maxd);

  if (maxd % 3 == 1) puts("Second");
  else puts("First");
  return 0;
}

