void dij(int s) {

	d[s] = 0;
	priority_queue<vector<ll>, vector<vector<ll>>, greater<vector<ll>>> q;
	q.push({0,0,s});
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		int cou = p[0];
		int cur = p[2];
		int dis = p[1];
		if (cou > d[cur]) continue;
		for (auto v : es[cur])
		{
			int val = v.cap != dis;
			if (cou + val < d[v.to]) {
				d[v.to] = cou + val;
				q.push({ d[v.to],v.cap,v.to });
			}
		}
	}
}
ll p2n(ll x) {

	ll v = (x * (x - 1)) / 2;
	ll t = 1;
	ll t2 = 2;
	ll res = 1;
	while (t <= v)
	{
		if ((v & t) > 0) res *= t2;
		t <<= 1;
		t2 *= t2;
		t2 %= INF;
		res %= INF;
	}
	return res;
}

class segtree {

private:
	ll _n;

public:
	int start;
	vector<ll> dat;
	segtree(ll n) :_n(n) {
		ll p = 1;
		while (p < (n * 2))
		{
			p <<= 1;
		}
		start = p / 2;
		dat = vector<ll>(p + 1);
	}
	void setup() {
		for (int i = 1; i < start; i++)
		{
			dat[i] = INF;
		}
		for (ll i = start; i < start * 2; i++)
		{
			ll t = i;
			while (t > 0)
			{
				ll ot = t;
				t /= 2;
				dat[t] = min(dat[ot], dat[t]);
			}
		}
		for (size_t i = 1; i < start; i++)
		{
			if (dat[i] == INF) dat[i] = 0;
		}
	}

	ll rmq(int f, int t) {
		return rmq(f, t, 0, start, 1);
	}

	ll rmq(int f, int t, int x, int y, int d) {

		if (t < x || y <= f) return INF;
		if (x == y) return dat[d];
		if (f <= x && y - 1 <= t) return dat[d];
		ll p1 = rmq(f, t, x, (x + y) / 2, d * 2);
		ll p2 = rmq(f, t, (x + y) / 2, y, d * 2 + 1);
		return min(p1, p2);
	}
};
