    vector<vector<int>> G;

    Tree(int n){
        N = n;
        G.resize(N);
    }

    void make_edge(int s, int t){
        G[s].push_back(t);
        G[t].push_back(s);
    }

    int find_leaf(){
        int n = 0, par = -1;
        while(true){
            //cout << n << " " << par << endl;
            if(G[n].size() == 1) return n;
            else {
                if(G[n][0] == par){
                    par = n;
                    n = G[n][1];
                } else {
                    par = n;
                    n = G[n][0];
                }
            }
        }
    }

    int dfs(int n, int par){
        int mx = 0;
        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par){
                mx = max(mx, dfs(nx, n) + 1);
            }
        }

        return mx;
    }

    int tyokkei(){
        int n = find_leaf();
        //cout << "leaf = " << n << endl;
        return dfs(n, -1);
    }
};

