using namespace std;

struct Node {
	set<int> children;
	int height = -1;
};

vector<Node> tree;

void fix(int node, int parent) {
	tree[node].children.erase(parent);

	for(int child : tree[node].children) {
		fix(child, node);
	}
}

int fill_height(int node) {
	int height = 0;
	for(int child : tree[node].children) {
		height = max(height, fill_height(child));
	}
	height++;

	tree[node].height = height;
	return height;
}

int get_diameter(int node) {
	int diameter = 0;
	vector<int> ch;
	for(int child : tree[node].children) {
		ch.push_back(tree[child].height);
	}

	sort(ch.rbegin(), ch.rend());

	if(ch.size() >= 2) {
		diameter = ch[0] + ch[1];
	}
	else if(ch.size() >= 1) {
		diameter = ch[0];
	}

	for(int child : tree[node].children) {
		diameter = max(diameter, get_diameter(child));
	}

	return diameter;
}

