inline void add(int x, int y) {
    edge[++tp].v = y;
    edge[tp].nex = e[x];
    e[x] = tp;
    return;
}

void DFS(int x, int fa) {
    int a = 1, b = 0;
    for(int i = e[x]; i; i = edge[i].nex) {
        int y = edge[i].v;
        if(y == fa) continue;
        DFS(y, x);
        if(a < f[y] + 1) {
            b = a;
            a = f[y] + 1;
        }
        else {
            b = std::max(b, f[y] + 1);
        }
    }
    Ans = std::max(Ans, std::max(a + b - 1, a));
    f[x] = a;
    return;
}

