    int n;
    scanf("%d", &n);
    for(int i = 1, x, y; i < n; i++) {
        scanf("%d%d", &x, &y);
        add(x, y);
        add(y, x);
    }

    DFS(1, 0);

    /// cal Ans
    sg[1] = 1;
    sg[2] = 0;
    for(int i = 3; i <= Ans; i++) {
        if(std::min(sg[i - 1], sg[i - 2]) == 0) {
            sg[i] = 1;
        }
        else {
            sg[i] = 0;
        }
    }

    if(sg[Ans]) {
        printf("First\n");
    }
    else {
        printf("Second\n");
    }

    return 0;
}

