int GetMaxInd(int in, int &L){
  int Lmax = 0, Lind;
  std::vector<int> memo(N, -1);
  std::stack<int> q;
  q.push(in); memo[in] = 0;
  while(!q.empty()){
    auto cur = q.top(); q.pop();
    for(int i=0; i<N; i++) {
      if ( A[cur][i] == 1 && memo[i] == -1 ) {
        memo[i] = (memo[cur] + 1);
        if ( Lmax < memo[i] ) {
          Lmax = memo[i];
          Lind = i;
        }
        q.push(i);
      }
    }
  }

  L = Lmax;
  return Lind;
}

int GetDiameter () {
