pair<int, int> visit(int vertex)
{
  int d(0), v(vertex);
  visited[vertex] = true;
  for (auto&& vn : edge[vertex]) {
    if (!visited[vn]) {
      auto p = visit(vn);
      if (d <= p.first) {
