    q.push(en);
    while(q.size()!=0){
        int s=q.front();
        q.pop();
        for(int i=0;i < E.at(s).size();i++)
        {
            if(dis.at(E.at(s).at(i))==0){
                dis.at(E.at(s).at(i))+=max(dis.at(s)+1,1);
                q.push(E.at(s).at(i));
                ans=max(ans,dis.at(E.at(s).at(i)));

            }
        }
    }
    return ans;
}



