pair<int,int> find_farthest(int first,vector<vector<int>> &E){
	vector<int> dis(E.size(),-1);
	int maxi = 0;
	int ind = first;
	dis[first]=0;
	queue<int> que;
	que.push(first);



	while(que.size()!=0){
		int a = que.front();
		que.pop();
		for(int i=0;i<E[a].size();i++){
			if(dis[E[a][i]]==-1){
				dis[E[a][i]]=dis[a]+1;
				que.push(E[a][i]);
			}
			if(dis[E[a][i]]>maxi){
				maxi=dis[E[a][i]];
				ind=E[a][i];
			}
		}
	}
	return make_pair(ind,dis[ind]);

}

