#include <iostream>
#include <vector>
using namespace std;


using Graph = vector<vector<int> >;
struct Diameter {
    vector<int> prev;
    pair<int,int> DiameterDFS(const Graph &G, int v, int p) {
        pair<int,int> res(v, 0);
        for (int i = 0; i < (int)G[v].size(); ++i) {
            if (G[v][i] == p) continue;
            pair<int,int> tmp = DiameterDFS(G, G[v][i], v);
            tmp.second++;
            if (tmp.second > res.second) res = tmp, prev[G[v][i]] = v;
        }
        return res;
    }

    vector<int> solve(const vector<vector<int> > &G) {
        prev.assign((int)G.size(), -1);
        pair<int,int> leaf = DiameterDFS(G, 0, -1);
        prev.assign((int)G.size(), -1);
        pair<int,int> t = DiameterDFS(G, leaf.first, -1);
        vector<int> res;
        int cur = t.first;
        while (cur != -1) res.push_back(cur), cur = prev[cur];
        return res;
    }
};


using Graph = vector<vector<int> >;
int N;
Graph G;

int main() {
    cin >> N;
    G.assign(N, vector<int>());
    for (int i = 0; i < N-1; ++i) {
        int a, b; cin >> a >> b; --a, --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    Diameter di;
    auto res = di.solve(G);    
    int V = res.size();
    if (V % 3 == 2) cout << "Second" << endl;
    else cout << "First" << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Node {
    bool done;
    int dist;
    vector<int> to;
};

int dfs(int pos, vector<Node>& node) {
    node[pos].done = true;
    int res = node[pos].dist;
    for (int i = 0; i < node[pos].to.size(); i++) {
        int nex = node[pos].to[i];
        if (node[nex].done == false) {
            node[nex].dist = node[pos].dist + 1;
            res = max(res, dfs(nex, node));
        }
    }
    return res;
}

int tree_diameter(vector<Node>& node) {
    int n = node.size();
    for (int i = 0; i < n; i++) {
        node[i].done = false;
        node[i].dist = INF;
    }
    node[0].dist = 0;
    int res = dfs(0, node);
    int pos;
    for (int i = 0; i < n; i++) {
        if (node[i].dist == res) {
            pos = i;
            break;
        }
    }
