int N;
vector<vector<int>> G;

vector<int> calc_distance(vector<vector<int>> &G, int s){
    int N = G.size();
    vector<int> ret(N, 1<<30);
    ret[s] = 0;
    queue<int> que;
    que.push(s);
    vector<int> vis(N, false);
    vis[s] = true;
    while(!que.empty()){
        int fr = que.front();
        que.pop();
        for(int t : G[fr]){
            if(vis[t]) continue;
            ret[t] = ret[fr] + 1;
            vis[t] = true;
            que.push(t);
        }
    }
    return ret;
}

int main(){
    cin >> N;
    G.resize(N);
    for(int i=0; i<N-1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    vector<int> d = calc_distance(G, 0);
    int idx = max_element(d.begin(), d.end()) - d.begin();
    vector<int> d2 = calc_distance(G, idx);
    int depth = *max_element(d2.begin(), d2.end());
    if(depth % 3 == 1)
        cout << "Second" << endl;
    else
        cout << "First" << endl;
    return 0;
}

