using P = pair<int, int>;

P diameter(vector<vector<int>> &tree, int ver, int prev) {
    P ans = {1, ver};
    for (auto &v : tree[ver]) {
        if (v == prev) continue;
        P res = diameter(tree, v, ver);
        res.first++;
        chmax(ans, res);
    }
    return ans;
}

