int dp[222222];

int Grundy(int x){
  int &g=dp[x];
  if(g!=-1)return g;
  if(x==0)return g=0;
  set<int>V;
  if(x>=1)V.insert(Grundy(x-1));
  if(x>=2)V.insert(Grundy(x-2));
  g=0;
  while(V.count(g))++g;
  return g;
}

