vector<LL> f(vector<vector<LL>>& graph,vector<bool>& toutatu,LL idx){
  toutatu[idx] = false;
  vector<LL> res;
  res.push_back(0);
  REP(i, graph[idx].size())
  {
    if(toutatu[graph[idx][i]]){
      vector<LL> a = f(graph, toutatu, graph[idx][i]);
      LL max = 0;
      REP(j, a.size())
      {
        if(a[j]>max){
