        es[a].push_back(b);
        es[b].push_back(a);
    }
    queue<Node> que;
    que.push(Node {0, 1});
    int start;

    while (!que.empty()) {
        auto t = que.front();
        que.pop();
        if (used[t.v])
            continue;
        used[t.v] = true;
        start = t.v;
        for (int x: es[t.v]) {
            que.push(Node {t.d + 1, x});
        }
    }

    que.push(Node {0, start});
    int diameter = 0;
    fill(used, used + n + 1, false);
    while (!que.empty()) {
        auto t = que.front();
        que.pop();
        if (used[t.v])
