int diameter()
{
    int root = 0;
    int max_depth = 0;

    queue<tuple<int, int, int>> q;
    q.push( make_tuple( root, -1, 0 ) );

    while ( !q.empty() )
    {
        auto e = q.front();
        q.pop();

        int vert = get<0>( e );
        int prev = get<1>( e );
        int dept = get<2>( e );

        for ( auto t : tree[vert] )
        {
            if ( t == prev ) continue;

            q.push( make_tuple( t, vert, dept + 1 ) );
        }

        root = vert;
    }

    q.push( make_tuple( root, -1, 0 ) );

    while ( !q.empty() )
    {
        auto e = q.front();
        q.pop();

        int vert = get<0>( e );
        int prev = get<1>( e );
        int dept = get<2>( e );

        for ( auto t : tree[vert] )
        {
            if ( t == prev ) continue;

            q.push( make_tuple( t, vert, dept + 1 ) );
        }

        max_depth = max( max_depth, dept );
    }

    return max_depth;
}

