    graph[a].emplace_back(Edge(a, b, 1));
    graph[b].emplace_back(Edge(b, a, 1));
  }
  DoubleSweep ds(graph);
  cout << ((ds.diameter + 1) % 3 == 2 ? "Second\n" : "First\n");
  return 0;
}

