    memset(dist,0,sizeof(dist));
    dfs(maxi,-1);
    int diameter=0;
    for(int i=0;i<n;i++)diameter=max(diameter,dist[i]);
    bool dp[diameter+5];
    dp[0]=1; dp[1]=0;
    for(int i=2;i<=diameter;i++){
        if(dp[i-1]&&dp[i-2]){
            dp[i]=0;
        }else{
            dp[i]=1;
        }
    }
    if(dp[diameter])printf("First");
    else printf("Second");
}

