template<typename T, int SIZE>
struct Diameter {
    struct edge {
        int to; T cost;
        edge(int to, T cost) : to(to), cost(cost) {}
    };

    vector<edge> g[SIZE];
    int pre[SIZE], dis[SIZE], __diameter;
    vector<int> __path;

    int diameter() {
        return __diameter;
    }

    vector<int> path() {
        return __path;
    }

    void add_edge(int from,int to,T cost) {
        g[from].emplace_back(to,cost);
        g[to].emplace_back(from,cost);
    }

    void build() {
        memset(dis, -1, sizeof(dis));
        memset(pre, -1, sizeof(pre));
        dfs(0, 0, 0);
        int bp = 0, ep = 0;
        for (int i = 0; i < SIZE; i++) if (pre[i] >= 0) {
            if (dis[i] > dis[ep]) {
                ep = i;
            }
        }
        memset(dis, -1, sizeof(dis));
        memset(pre, -1, sizeof(pre));
        dfs(ep, ep, 0);
        for (int i = 0; i < SIZE; i++) if (pre[i] >= 0) {
            if (dis[i] > dis[bp]) {
                bp = i;
            }
        }
        __diameter = dis[bp];
        __path.clear();
        int p = bp;
        while (p != ep) {
            __path.push_back(p);
            p = pre[p];
        }
        __path.push_back(p);
    }

    void dfs(int v,int pv,int d) {
        pre[v] = pv; dis[v] = d;
        for (edge e : g[v]) if (e.to != pv) {
            dfs(e.to,v,d+e.cost);
        }
    }
};

