using Result = pair<Weight, int>;

Result visit(int p, int v, const Graph &g);
Weight diameter(const Graph &g);

//----------------------------------------------------------
Result visit(int id_pv, int id_tv, const Graph &g) {
	Result r(0, id_tv);
	for (const auto &e : g.vertices[id_tv]->edges)
		if (e->p_dst->id != id_pv) {
			Result t = visit(id_tv, e->p_dst->id, g);
			t.first += e->weight;
			if (r.first < t.first) r = t;
		}
	return r;
}
Weight diameter(const Graph &g) {
	Result r = visit(-1, 0, g);
	Result t = visit(-1, r.second, g);
	return t.first; // (r.second, t.second) is farthest pair
}

