using Graph = vector<vector<Edge>>; // 隣接リスト
pair<int,int> dfs(const Graph &G, int a, int par){
    pair<int,int> res = make_pair(0, a);
    for(auto e : G[a]){
        if(e.to == par) continue; // parに逆流することを防ぐ
        auto next = dfs(G, e.to, a);
        next.first += e.cost;
        if(next.first > res.first) res = next;
    }
    return res;
} // 最遠点距離と最遠点を求める

int tree_r(const Graph &G){
    pair<int,int> p = dfs(G, 0, -1);
    pair<int,int> q = dfs(G, p.second, -1);
    return q.first;
}

