// template

pair<int, int> longest(const vector<vector<int> > & G, int node, int depth, vector<bool> & memo) {
	memo[node] = true;

	pii res{ -1,-1 };
	for (auto& to : G[node]) {
		if (not memo[to]) {
			pii a = longest(G, to, depth + 1, memo);
			res = max(res, a);
		}
	}
	if (res.first == -1) {
		return { depth, node };
	}
	return res;
}

void solve() {
	int N; cin >> N;
	vector<vector<int> > G(N);
	REP(i, N - 1) {
		int a, b; cin >> a >> b;
		--a, --b;
		G[a].emplace_back(b);
		G[b].emplace_back(a);
	}

	int longest_path;
	{
		vector<bool> memo(N);
		memo[0] = true;
		pii p = longest(G, 0, 0, memo);
		memo = vector<bool>(N);
		memo[p.second] = true;
		pii pp = longest(G, p.second, 0, memo);
		longest_path = pp.first;
	}
	int node_cnt = longest_path + 1;

	vector<int> grundy(node_cnt + 3);
	grundy[0] = 0;
	grundy[1] = 1;
	grundy[2] = 0;
	FOR(i, 3, node_cnt + 1) {
		set<int> memo;
		REP(j, 2) {
			if (i - j - 1 >= 0) memo.insert(grundy[i - j - 1]);
		}
		for (int j = 0;; ++j) {
			if (memo.count(j) == 0) {
				grundy[i] = j;
				break;
			}
		}
	}
	if (grundy[node_cnt] == 0) {
		cout << "Second" << endl;
	}
	else {
		cout << "First" << endl;
	}
}

