bool centroid(int node){
    int val,tata=0;
    bool ok;

    dfs(node);
    val=dp[node]/2;
    do{
        ok=false;
        for(auto& it:V[node])
            if(it != tata)
               if(dp[it] > val){
                  tata=node;
                  node=it;
                  ok=true;
                  break;
               }
    }while(ok);
    tata=tatal[node];
    for(auto& it:V[node])
        if(it != tata){
           if(dp[1] - dp[it] > val)
              continue;
           ok=false;
           for(auto& it2:V[it])
               if(it2 != node)
                  if(dp[it2] > val)
                     ok=true;
            if(!ok)
               return 0;
        }
   return 1;
}
