    {
        queue<P> que;
        que.push(P(0, s));
        while(!que.empty())
        {
            P p = que.front();
            int v = p.second;
            int cost = p.first;
            que.pop();
            for(auto next : e[v])
            {
                if(next != s && d[next] == 0)
                {
                    que.push(P(cost+1, next));
                    d[next] = cost + 1;
                }
            }
        }
    };
