class Tree {
    public:
    struct Node {
        std::vector<int> edge;
        int rank;
        int direction;
    };
    std::vector<Node> node;
    Tree() {}
    Tree(const int node_num_max) {
        node.resize(node_num_max);
    }
    void add_directed_edge(const int from, const int to) {
        node[from].edge.push_back(to);
    }
    void add_undirected_edge(const int node1, const int node2) {
        add_directed_edge(node1, node2);
        add_directed_edge(node2, node1);
    }
    void set_rank(int n, int rank, int parent) { // 辺が有向でも無向でも使える。呼び出すとき、parentは-1にしておくとよい。
        node[n].rank = rank;
        for (int c : node[n].edge) {
            if (c != parent) {
                set_rank(c, rank + 1, n);
            }
        }
    }
    int calc_diameter(int max_idx) {
        // 点は1～max_idxという想定。
        set_rank(1, 0, -1);
        int tmp_idx = 1;
        int tmp_diameter = 0;
        for (int i = 1; i <= max_idx; i++) {
            if (tmp_diameter < node[i].rank) {
                tmp_idx = i;
                tmp_diameter = node[i].rank;
            }
        }
        set_rank(tmp_idx, 0, -1);
        for (int i = 1; i <= max_idx; i++) {
            tmp_diameter = std::max(tmp_diameter, node[i].rank);
        }
        return tmp_diameter;
    }
};

const int MAX_N = 200050;
Tree tree = Tree(MAX_N);

int N, a[MAX_N], b[MAX_N];

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i < N; i++) {
        std::cin >> a[i] >> b[i];
    }

    if (N == 1) {
        std::cout << "First" << std::endl;
        return 0;
    }

    for (int i = 1; i < N; i++) {
        tree.add_undirected_edge(a[i], b[i]);
    }

    int diameter = tree.calc_diameter(N);

    if (diameter % 3 == 1) {
        std::cout << "Second" << std::endl;
    } else {
        std::cout << "First" << std::endl;
    }

    return 0;
}

