struct Edge { int to, cost; };

int tree_diameter(const vector<vector<Edge>>& g) {
	int V = g.size();
	vector<int> d(V, -1);

	function< void(int) > bfs = [&](int s) {
		d.assign(V, -1);
		d[s] = 0;
		deque<int> que;
		que.push_back(s);
		while (!que.empty()) {
			int t = que.front();
			que.pop_front();
			for (auto e : g[t]) {
				if (d[e.to] < 0) {
					d[e.to] = d[t] + e.cost;
					que.push_back(e.to);
				}
			}
		}
	};

	bfs(0);
	bfs(max_element(d.begin(), d.end()) - d.begin());
	return *max_element(d.begin(), d.end());
}

int main() {
	int N;
	cin >> N;
	vector<vector<Edge>> g(N);
	for (int i = 0; i < N - 1; ++i) {
		int a, b;
		cin >> a >> b;
		--a, --b;
		g[a].push_back({b, 1});
		g[b].push_back({a, 1});
	}

	cout << (tree_diameter(g) % 3 == 1 ? "Second" : "First") << endl;

	return 0;
}

