void bfs(int s){
    for(int i=0;i<n;i++){
        d[i]=INFTY;
    }
    queue<int>Q;
    Q.push(s);
    d[s]=0;
    int u;
    while(Q.size()){
        u=Q.front();
        Q.pop();
        for(int i=0;i<G[u].size();i++){
            Edge e=G[u][i];
            if(d[e.t]==INFTY){
                d[e.t]=d[u]+e.w;
                Q.push(e.t);
            }
        }
    }
}

void solve(){
    bfs(0);
    int maxv=0;
    int tgt=0;
    for(int i=0;i<n;i++){
        if(d[i]==INFTY)continue;
        if(maxv<d[i]){
            maxv=d[i];
            tgt=i;
        }
    }
    bfs(tgt);
    maxv=0;
    for(int i=0;i<n;i++){
        if(d[i]==INFTY)continue;
        maxv=max(maxv,d[i]);
    }
