pair<int, int> farthest (int u, int p) {
  auto ans = make_pair(0, u);
  for (int nxt : adj[u]) {
    if (nxt != p) {
      auto pr = farthest(nxt, u);
      pr.first++;
      ans = max(ans, pr);
    }
  }
  return ans;
}

