Pii dfs(int v,int p){
  Pii ret={0,v};
  for(int u:g[v])if(u!=p){
    Pii a = dfs(u,v);
    if(ret.first<a.first+1){
      ret = {a.first+1,a.second};
    }
  }
  return ret;
}

