void readgraph(graph &g, size_t E, bool D, bool C, bool Z){ // E:num_of_edges, D:directed, C:costed, Z:already 0-indexed
	for(size_t i=0; i<E; ++i){
		edge e(1, 0, 0);
		if(!C) cin >> e.from >> e.to;
		else cin >> e.from >> e.to >> e.cost;
		if(!Z){
			--e.from;
			--e.to;
		}
		g[e.from].push_back(e);
		if(!D){
			swap(e.from, e.to);
			g[e.from].push_back(e);
		}
	}
}
void calc_distance(graph &g, vector<Int> &d, Int s){
	d.assign(g.size(), 1e8);
//	for(Int i=0; i<n; ++i)
//		cout << d[i] << " \n"[i+1==n];
	d[s] = 0;
	queue<Int> q;
	q.push(s);
	while(!q.empty()){
		Int p = q.front(); q.pop();
		for(auto e:g[p])
			if(d[e.to] == 1e8){
				d[e.to] = d[p]+1;
				q.push(e.to);
			}
	}
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n;
	graph g(n);
	readgraph(g, n-1, false, false, false);
	vector<Int> d(n);
	calc_distance(g, d, 0);
	Int l=0;
	for(Int i=0; i<n; ++i)
