void dijkstra(int x){
    priority_queue<P, vector<P>, greater<P>> pque;
    pque.push({0, x});
    d[x] = 0;
    while(!pque.empty()){
        int c = pque.top().first;
        int v = pque.top().second;
        pque.pop();
        if(c > d[v]) continue;

        for(int i = 0; i < G[v].size(); i++){
            int nv = G[v][i];
            if(d.at(nv) > c + 1){
                d.at(nv) = c+1;
                pque.push({c+1, nv});
            }
        }
    }
}


