vector<int> bfs(int n, vector<vector<int>> &g, int start) {

    vector<int> ans(n, INT_MAX);
    ans[start] = 0;
    queue<int> q;
    q.push(start);
    while (!q.empty()) {
        int from = q.front();
        q.pop();

        int next_cost = ans[from] + 1;
        for (int to : g[from]) {
            if (ans[to] > next_cost) {
                ans[to] = next_cost;
                q.push(to);
            }
        }

    }
    return ans;
}

