int tree_diameter(const vector<vector<int>>& g) {
	const int INF = 1e8;
	int V = g.size();
	vector<int> d(V, INF);
	deque<int> que;

	d[0] = 0;
	que.push_back(0);
	while (!que.empty()) {
		int s = que.front();
		que.pop_front();
		for (int i = 0; i < g[s].size(); ++i) {
			if (d[s] < d[g[s][i]]) {
				d[g[s][i]] = d[s] + 1;
				que.push_back(g[s][i]);
			}
		}
	}

	int t = 0, max_d = 0;
	for (int i = 0; i < V; ++i) {
		if (max_d < d[i]) {
			max_d = d[i];
			t = i;
		}
		d[i] = INF;
	}

	d[t] = 0;
	que.push_back(t);
	while (!que.empty()) {
		int s = que.front();
		que.pop_front();
		for (int i = 0; i < g[s].size(); ++i) {
			if (d[s] < d[g[s][i]]) {
				d[g[s][i]] = d[s] + 1;
				que.push_back(g[s][i]);
			}
		}
	}

	int ret = 0;
	for (int i = 0; i < V; ++i) { ret = max(ret, d[i]); }

	return ret + 1;
}

