int INF = 9999999;

int main() {
  int n;
  scan(n);
  vvi g(n);
  rep (i, n-1) {
    int a, b;
    scan(a, b);
    a -= 1;
    b -= 1;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  vi dist(n, INF);
  dist[0] = 0;
  deque<int> que = {0};
  while (!que.empty()) {
    int u = que.front();
    que.pop_front();
    for (int v : g[u]) {
      if (dist[v] != INF) {
        continue;
      }
      dist[v] = dist[u] + 1;
      que.push_back(v);
    }
  }
  int sv = 0;
  rep (i, n) {
    if (dist[sv] < dist[i]) {
      sv = i;
    }
  }
  dist.assign(n, INF);
  dist[sv] = 0;
  que = {sv};
  while (!que.empty()) {
    int u = que.front();
    que.pop_front();
    for (int v : g[u]) {
      if (dist[v] != INF) {
        continue;
      }
      dist[v] = dist[u] + 1;
      que.push_back(v);
    }
  }
  int dia = 0;
  rep (i, n) {
    dia = max(dia, dist[i]);
  }
  if (dia % 3 == 1) {
    print("Second");
  } else {
    print("First");
  }

  return 0;
}

