    int to,next;
}E[MAXN * 2];
int sumE,head[MAXN],N;
int dis[MAXN];
void add(int u,int v) {
    E[++sumE].to = v;
    E[sumE].next = head[u];
    head[u] = sumE;
}
void dfs(int u,int fa) {
    dis[u] = dis[fa] + 1;
    for(int i = head[u] ; i ; i = E[i].next) {
        int v = E[i].to;
        if(v != fa) {
            dfs(v,u);
        }
    }
}
void Solve() {
    read(N);
    if(N == 1) {
        puts("First");return;
    }
    int a,b;
    for(int i = 1 ; i < N ; ++i) {
        read(a);read(b);
        add(a,b);add(b,a);
    }
    dfs(1,0);
    int u = 1;
    for(int i = 1 ; i <= N ; ++i) {
        if(dis[i] > dis[u]) u = i;
    }
    dfs(u,0);
    u = 1;
    for(int i = 1 ; i <= N ; ++i) {
        if(dis[i] > dis[u]) u = i;
    }
    if(dis[u] % 3 == 2) {puts("Second");}
    else puts("First");
}
