int main(){
	int N; cin >> N; 
	vector<int> E[200010] = {}; 
	for(int i = 0; i < N-1; i++){
		int a, b; cin >> a >> b; 
		a--; b--; 
		E[a].push_back(b); 
		E[b].push_back(a); 
	}
	int D[200010] = {}; 
	queue<int> que;
	que.push(0); 
	while(que.size()){
		int p = que.front(); que.pop(); 
		for(int i = 0; i < E[p].size(); i++){
			if(D[E[p].at(i)] == 0){
				D[E[p].at(i)] = D[p] + 1; 
				que.push(E[p].at(i)); 
			}
		}
	}
	int mx = 0; int index = 0; 
	for(int i = 0; i < N; i++){
		if(D[i] > mx){
			index = i; mx = D[i]; 
		}
	}
	int D2[200010] = {}; 
	queue<int> que2;
	que2.push(index); 
	while(que2.size()){
		int p = que2.front(); que2.pop(); 
		for(int i = 0; i < E[p].size(); i++){
			if(D2[E[p].at(i)] == 0){
				D2[E[p].at(i)] = D2[p] + 1; 
				que2.push(E[p].at(i)); 
			}
		}
