    }
    if(n==1){
        cout << "First" << endl;
        return 0;
    }else if(n==2){
        return 0;
    }
    vll dep(n);
    dep[0]=0;
    stack<ll> st;
    st.push(0);
    vll par(n);
    par[0]=-1;
    ll v = 0;
    while(!st.empty()){
        ll now = st.top();
        st.pop();
        for(ll i:nei[now]){
            if(i!=par[now]){
                dep[i]=dep[now]+1;
                par[i] = now;
                st.push(i);
                if(dep[i]>dep[v]) v = i;
            }
        }
    }
    dep = vll(n,0);
    dep[v]=0;
    st.push(v);
    par = vll(n,0);
    par[0]=-1;
    ll u = v;
    while(!st.empty()){
        ll now = st.top();
        st.pop();
        for(ll i:nei[now]){
            if(i!=par[now]){
                dep[i]=dep[now]+1;
                par[i] = now;
                st.push(i);
                if(dep[i]>dep[u]) u = i;
            }
        }
    }
    ll l = dep[u];
    if(l%3==1){
        cout << "Second" << endl;
    }else{
        cout << "First" << endl;
    }
    return 0;
}

