template<typename T>
vector<pair<T, int>> RUN_LENGTH(const vector<T> &v) {
    vector<pair<T, int>> ret;
    int len = v.size();
    for (int i = 0, j = 0; i < len; i = j) {
        while (j < len && v[i] == v[j]) j++;
        ret.push_back(make_pair(v[i], j - i));
    }
    return ret;
}

