std::pair<int,int> GetMaxInd(int in){
  std::pair<int,int> L (-1,-1);
  std::vector<int> memo(N, -1);
  std::stack<int> q;
  q.push(in); memo[in] = 0;
  while(!q.empty()){
    auto cur = q.top(); q.pop();
    for(int i=0; i<A[cur].size(); i++) {
      int next = A[cur][i];
      if ( memo[next] == -1 ) {
        memo[next] = (memo[cur] + 1);
        if ( L.first < memo[next] ) L = { memo[next], next } ;
        q.push(next);
      }
    }
  }
  return L;
}

