void solve() {
  int n; cin >> n;
  Graph<int> g(n);
  rep1(_,n) {
    int a, b; cin >> a >> b; --a, --b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }

  int s, t;
  int MAX = 0;

  auto dfs = [&](auto dfs, int v, int p, int d, int &x) -> void {
    if (chmax(MAX, d)) x = v;
    for (auto &nv : g[v]) {
      if (nv != p) {
        dfs(dfs, nv, v, d+1, x);
      }
    }
  };

  dfs(dfs, 0, -1, 0, s);
  MAX = 0;
  dfs(dfs, s, -1, 0, t);

  CoutYN(MAX % 3 == 1, "Second", "First");
}


