    for (int i = 1; i < N; i++) {
        int some_lose = 0;
        for (int j = 1; j <= 2; j++) {
            if (i - j >= 0 && !dp[i - j]) {
                some_lose = 1;
            }
        }
        if (some_lose) dp[i] = 1;
    }
}

int used[N];
