void dfs(int cur, int ch, pair<int, int> &mx) {
    used[cur] = 1;
    mx = max(mx, {ch, cur});
    for (auto t : g[cur]) {
        if (!used[t]) {
            dfs(t, ch + 1, mx);
        }
    }
}

