pair<int, int> visit(int from, int node, const Graph& g)
{
    pair<int, int> r = {0, node};
    for (int next : g[node]) if (next != from) {
        pair<int, int> t = visit(node, next, g);
        t.first += 1;
        if (r.first < t.first) r = t;
    }
    return r;
}
int main()
{
    int N; cin >> N;
    Graph G(N);
    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    auto p = visit(-1, 0, G);
    auto q = visit(-1, p.second, G);
    int diameter = q.first;
    cout << ((diameter % 3 != 1) ? "First" : "Second") << '\n';
    return 0;
}

