ll Diameter(vvll &to){
	ll diameter = 0;

	std::function<ll(ll, ll)> dfsDiameter = [&](ll v, ll p)->ll{
		multiset<ll> depthSet;
		EACH(u, to[v]){
			if (u == p) continue;
			ll depth = dfsDiameter(u, v);
			depthSet.insert(dfsDiameter(u, v));
		}
		if (depthSet.empty()) return 0;
		if (depthSet.size() == 1){
			ll depth = *(depthSet.begin());
			chmax(diameter, depth+1);
			return depth+1;
		} else{
			auto it = depthSet.end();
			it--;
			ll maxDepth = *it;
			it--;
			ll secDepth = *it;
			chmax(diameter, maxDepth + secDepth + 2);
			return maxDepth+1;
		}
	};

	dfsDiameter(0, -1);
	return diameter;
}


