vector<int> d(200020, INF);
void dijkstra(int x){
    priority_queue<pair<int,int>> pque;
    pque.push({0, x});

    while(!pque.empty()){
        int c = pque.top().first;
        int v = pque.top().second;
        pque.pop();

        for(int i = 0; i < G[v].size(); i++){
            int nv = G[v][i];
            if(d.at(nv) > c + 1){
                d.at(nv) = c+1;
                pque.push({nv, c+1});
            }
        }
    }
}


