pair<int, int> findFarthest(int cur, int par, int dist){
	pair<int, int> ans = {dist, cur};
	for(int adj: g[cur]){
		if(adj == par) continue;
		ans = max(ans, findFarthest(adj, cur, dist+1));
	}
	return ans;
}

