        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }
    if(N==1){
        cout<<"first"<<endl;
        return 0;
    }
    stack<P> s;
    vector<int> visited(N);
    s.push(P(0,0));
    int max_d=0;
    int max_n;
    while(!s.empty()){
        P p=s.top();
        int v=p.second;
        int d=p.first;
        s.pop();
        if(max_d<d){
            max_d=d;
            max_n=v;
        }
        for(int i:G[v]){
            if(!visited[i]){
                visited[i]=1;
                s.push(P(d+1,i));
            }
        }
    }
    s=stack<P>();
    visited=vector<int>(N);
    s.push(P(0,max_n));
    max_d=0;
    while(!s.empty()){
        P p=s.top();
        int v=p.second;
        int d=p.first;
        s.pop();
        if(max_d<d){
            max_d=d;
        }
        for(int i:G[v]){
            if(!visited[i]){
                visited[i]=1;
                s.push(P(d+1,i));
            }
        }
    }
    cout<<(max_d%3==1?"Second":"First")<<endl;
    return 0;
}

