pair<int, int> dfs(vector<vector<int>> &g, int v, int par) {
    if (g[v].size() == 1 && g[v][0] == par) return make_pair(1, v);
    pair<int, int> ret;
    for (auto &e: g[v]) {
        if (e == par) continue;
        ret = max(ret, dfs(g, e, v));
    }
    ret.first++;
    return ret;
}

