const int MAXN = 2e5 + 5;

int n;
vector<int> adj[MAXN];

void input(){
	scanf("%d", &n);
	for(int i = 0; i < n-1; ++i){
		int u, v;
		scanf("%d %d", &u, &v);
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

int getDiameter(){
	int dist[MAXN], farthestNode = 1;

	memset(dist, -1, sizeof dist);
	queue<int> bfs;
	bfs.push(1);
	dist[1] = 0;
	while(!bfs.empty()){
		int top = bfs.front(); bfs.pop();
		if(dist[farthestNode] < dist[top])
			farthestNode = top;
		for(int i : adj[top]){
			if(dist[i] != -1)
				continue;
			dist[i] = dist[top]+1;
			bfs.push(i);
		}
	}

	fprintf(stderr, "Farthest node = %d\n", farthestNode);

	memset(dist, -1, sizeof dist);
	bfs.push(farthestNode);
	dist[farthestNode] = 0;
	while(!bfs.empty()){
		int top = bfs.front(); bfs.pop();
		if(dist[farthestNode] < dist[top])
			farthestNode = top;
		for(int i : adj[top]){
			if(dist[i] != -1)
				continue;
			dist[i] = dist[top]+1;
			bfs.push(i);
		}
	}

	fprintf(stderr, "Diameter = %d\n", dist[farthestNode]);

	return dist[farthestNode];
}

/*
Let D be the set of nodes along the diameter of the tree
If the current player choose a leaf node from D, he will shrink the diameter by 1
Otherwise, he will shrink the diameter by 2

Diameter
-1 0 1 2 3 4 5 6 7
 L W L W W L W W L
*/

void work(){
	// Find diameter of the tree
	int d = getDiameter();

	if(d == 1 || (d >= 4 && d%3 == 1)){
		printf("Second\n");
	}else{
		printf("First\n");
	}
}

int main(){
	input();
	work();
}

