int n;

vi dijkstra(int node, vvi &adj) {
	vi dist(n, inf);
	dist[node] = 0;
	priority_queue<ii> q;
	q.push({-dist[node], node});
	while(!q.empty()) {
		int node = q.top().ss; q.pop();
		for(int i : adj[node]) {
			if(dist[node] + 1 < dist[i]) {
				dist[i] = dist[node] + 1;
				q.push({-dist[i], i});
			}
		}
	}

	return dist;
}

