            ds[v] = ds[tmp] + 1;
            q.push(v);
        }
    }
    m = 0;    
    for (int i = 0; i < N; i++) {
        if(ds[i] > m){
            ind = i;
            m = ds[i];
        }
    }

    if(m % 3 == 1){
        printf("Second\n");
    }
    else{
        printf("First\n");
    }

}

