void bfs(int v = 0) {
    queue<int> q;
    q.push(v);
    fill(d, d + N, INF32);
    d[v] = 0;
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        for (int to : adj[x]) {
            if (d[to] > d[x] + 1) {
