    REP(n, N-1) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        edges[n] = mp(a, b);
    }

    if (solve(N, edges)) {
        cout << "First" << endl;
    } else {
        cout << "Second" << endl;
    }

    return 0;
}

