    Graph G(n);
    for (int i=0; i<n-1; ++i) {
        int a, b;
        cin >> a >> b;
        G.at(a-1).push_back(b-1);
        G.at(b-1).push_back(a-1);
    }

    int dia = diameter(G);
    vector<bool> dp(dia+1);
    for (int i=1; i<dia+1; ++i) {
        if (i == 1) {
            dp.at(i) = true;
        } else if (i == 2) {
            dp.at(i) = false;
        } else {
            dp.at(i) = !(dp.at(i-1) && dp.at(i-2));
        }
    }
    if (dp.at(dia)) cout << "First" << '\n';
    else cout << "Second" << '\n';
}

