pair<int, int> tddfs(int v, int par = -1) {
	pair<int, int> ret = { 0, v };
	for (auto &x : g[v]) {
		int w, cost;
		tie(w, cost) = x;
		if (w == par)
			continue;
		auto r = tddfs(w, v);
		ret = max(ret, { cost + r.first, r.second });
	}
	return ret;
}

