bool dp[200001][2];
bool already[200001][2] ={};
bool solve(int now, int player){
	if(now == 1){
		if(player == 0) return true;
		else return false;
	}
	if(now == 2) return solve(1, player^1);
	if(already[now][player]) return dp[now][player];
	already[now][player] = true;
	if(player == 0){
		return dp[now][player] = (solve(now-1, player^1) || solve(now-2, player^1));
	}
	else{
		return dp[now][player] = (solve(now-1, player^1) && solve(now-2, player^1));
	}
}

