using namespace std;

pair<uint64_t, uint64_t> farthest(uint64_t N, map<uint64_t, set<uint64_t>> &edges, uint64_t src)
{
  vector<bool> visited(N, false);

  stack<pair<uint64_t, uint64_t>> s;
  s.emplace(src, 0);

  uint64_t max_len = 0, max_len_node = -1;
  while (!s.empty()) {
    pair<uint64_t, uint64_t> p = s.top(); s.pop();

    if (visited[p.first]) { continue; }

    visited[p.first] = true;

    if (max_len < p.second) {
      max_len_node = p.first;
      max_len      = p.second;
    }

    for (uint64_t next : edges[p.first]) {
      if (!visited[next]) {
        s.emplace(next, p.second + 1);
      }
    }
  }
  return make_pair(max_len_node, max_len);
}

uint64_t center_node(uint64_t N, map<uint64_t, set<uint64_t>> &edges)
{
  pair<uint64_t, uint64_t> pu = farthest(N, edges, 0);
  pair<uint64_t, uint64_t> pv = farthest(N, edges, pu.first);

  vector<bool> visited(N, false);

  stack<pair<uint64_t, uint64_t>> s;
  s.emplace(pu.first, 0);

  uint64_t center = -1;
  while (!s.empty()) {
    pair<uint64_t, uint64_t> p = s.top(); s.pop();

    if (p.second == (pv.second >> 1)) {
      center = p.first;
      break;
    }

    if (visited[p.first]) { continue; }

    visited[p.first] = true;

    for (uint64_t next : edges[p.first]) {
      if (!visited[next]) {
        s.emplace(next, p.second + 1);
      }
    }
  }
  return center;
}

uint64_t max_depth(uint64_t N, map<uint64_t, set<uint64_t>> &edges, uint64_t node, vector<bool> &visited, uint64_t depth)
{
  if (visited[node]) { return depth; }

  visited[node] = true;

  uint64_t max_d = depth;
  for (uint64_t next : edges[node]) {
    if (!visited[next]) {
      max_d = max(max_d, max_depth(N, edges, next, visited, depth + 1));
    }
  }
  return max_d;
}

int main()
{
  uint64_t N;
  cin >> N;

  map<uint64_t, set<uint64_t>> edges;
  for (uint64_t n = 0; n < N; ++n) {
    edges.emplace(n, set<uint64_t>());
  }

  for (uint64_t n = 0; n < N - 1; ++n) {
    uint64_t a, b;
    cin >> a >> b;

    edges[a - 1].insert(b - 1);
    edges[b - 1].insert(a - 1);
  }

  uint64_t center = center_node(N, edges);

  vector<bool> visited(N, false);
  uint64_t d = max_depth(N, edges, center, visited, 0);
  cout << ((d & 1) == 1 ? "First" : "Second") << endl;

  return 0;
}

