pll visit(ll p, ll v, const Graph &g) {
  pll r(0, v);
  AUTO(e, g[v]) if (e.dst != p) {
    pll t = visit(v, e.dst, g);
    t.first += e.weight;
    if (r.first < t.first)
      r = t;
  }
  return r;
}
ll diameter(const Graph &g) {
  pll r = visit(-1, 0, g);
  pll t = visit(-1, r.second, g);
  return t.first; // (r.second, t.second) is farthest pair
}
