struct LCA {
	int ver;
	int h;	//最大ダブリング回数
	int rt;
	vector<int> par;
	vector<vector<int>> anc;
	LCA(int _ver, vector<int> _par) : ver(_ver), par(_par) {
		for(int i = 0; i < ver; i++) {
			if(i == par[i]) rt = i;
		}
		anc[0] = _par;
		vector<int> nxt(_ver);
		bool f = 1;
		int i = 0;
		while(f) {
			f = 0;
			for(int j = 0; j < _ver; j++) {
				if((nxt[j] = anc[i][anc[i][j]]) != rt) {
					f = 1;
				}
			}
		}
		h = (int)anc.size();
	}
};

template <class T>	// WarshallFloyd
void warshall(vector<vector<T>> &v) {
	ll n = v.size();
	rep(i, n) rep(j, n) rep(k, n) {
		if(v[j][i] == dekai || v[i][k] == dekai) continue;
		v[j][k] = min(v[j][k], v[j][i] + v[i][k]);
	}
	return;
}

