		// 	vec = bfs(v1);
		vec = weigh ? dijkstra(v1):bfs(v1);
		dia = -1;
		int v2 = -1;
		rep(i, ver) if(chmax(dia, vec[i])) v2 = i;

		pair<pair<int, int>, T> ans = {{v1, v2}, dia};
		return ans;
	}

