int DFS1(int x) {
	search1[x] = true;
	for (int i = 0; i < N - 1; i++) {
		if (p[i].first == x || p[i].second == x) {
			if (!search1[p[i].first + p[i].second - x]) {
				return DFS1(p[i].first + p[i].second - x);
			}
		}
	}
	return x;
}
void DFS2(int x, int count) {
	search2[x] = true;
	for (int i = 0; i < N - 1; i++) {
		if (p[i].first == x || p[i].second == x) {
			if (!search2[p[i].first + p[i].second - x]) {
				DFS2(p[i].first + p[i].second - x, count + 1);
			}
		}
	}
	dis = max(dis, count);
	return;
}

