typedef std::vector<std::vector<int>> Graph;
typedef std::pair<int,int> pii;
// visit(p,v,g)=Graph g上でvからp以外の方向に探索したときの(最遠点までの距離,最遠点の番号)の組
pii visit(int p,int v, const Graph &g){
    pii r={0,v};
    for(auto itr=g[v].begin();itr!=g[v].end();itr++){
        if(*itr==p)continue;
        pii t=visit(v,*itr,g);
        t.first++;
        if(r.first<t.first)r=t;
    }
    return r;
}
int diameter(const Graph &g){
    pii r=visit(-1,0,g);
    pii t=visit(-1,r.second,g);
    return t.first;
}
