// 移動元と行先と辺のコストを記録する構造体
template <typename T>
struct Edge {
    int from, to;
    T cost;
    Edge(int s, T d) : to(s), cost(d) {}
    Edge(int f, int s, T d) : from(f), to(s), cost(d) {}

    bool operator<(const Edge &e) const {
        return cost < e.cost;
    }
    bool operator>(const Edge &e) const {
        return cost > e.cost;
    }
};

// 木に対するDFS (対象となる頂点から最も遠い頂点の情報を返す)
// n := (頂点番号, その頂点までのコスト)
// Verified: AtCoder Regular Contest 022 C (ロミオとジュリエット)

template <typename T>
void getDeepest(pair<int, T> &n, vector< vector< Edge<T> > > &G, int p, int prev, T cost) {
    int ok = true;
    for(auto x : G[p]) {
        if(x.to != prev) {
            ok = false;
            getDeepest(n, G, x.to, p, cost+x.cost);
        }
    }
    if(ok && n.second < cost) {
        n.first = p;
        n.second = cost;
    }
}

// 補足: これを使用すると木の直径が求められる。
// 1. 適当な頂点を選びDFSを適用する
// 2. 1 で返ってきた頂点に対してDFSを適用する
// 3. 1 で返った頂点と 2 で返った頂点が直径の候補の一つになる。


template <typename T>
using Graph = vector< vector< Edge<T> > >;

signed main() {
    int N; cin >> N;
    vector< vector< Edge<int> > > G(N);
    for(int i=0; i<N-1; i++) {
        int a, b; cin >> a >> b;
        a--; b--;
        G[a].emplace_back(b, 1);
        G[b].emplace_back(a, 1);
    }

// 使用例
// この場合は p.fr と r.fr が直径の候補の一つであり、その大きさは r.sc である。
    pii p = pii(0, 0), r = pii(0, 0);
    getDeepest<int>(p, G, 0, -1, 0);
    getDeepest<int>(r, G, p.first, -1, 0);

    cout << (r.second % 3 == 1 ? "Second" : "First") << endl;
    return 0;
}

