VV<ll> edges;

PLL dfs(ll now, ll pre) {
    PLL ret(0, now);
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        auto tmp = dfs(nxt, now);
        if(tmp.first > ret.first) ret = tmp;
    }
    ret.first++;
    return ret;
}

ll dfs2(ll now, ll pre) {
    ll ret = 0;
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        chmax(ret, dfs2(nxt, now));
    }
    return ret + 1;
}

