const int Maxn = 200005;

int n;
vector <int> neigh[Maxn];
int mx;
int dp[Maxn];

int Traverse(int v, int p)
{
    int best[2] = {0, 0};
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        int g = Traverse(u, v);
        if (g > best[0]) best[1] = best[0], best[0] = g;
        else if (g > best[1]) best[1] = g;
    }
    mx = max(mx, best[0] + 1 + best[1]);
    return best[0] + 1;
}

