int diameter(const Graph &G) {
    int n = (int)G.size();
    vector<int> dis(n, -1);
    dis.at(0) = 0;
    queue<int> que;
    que.push(0);
    while (!que.empty()) {
        int cur = que.front(); que.pop();
        for (int nx : G.at(cur)) {
            if (dis.at(nx) == -1) {
                dis.at(nx) = dis.at(cur) + 1;
                que.push(nx);
            }
        }
    }
    int maxi = -1, ind = -1;
    for (int i=0; i<n; ++i) if (chmax(maxi, dis.at(i))) ind = i;

    dis.assign(n, -1);
    dis.at(ind) = 0;
    que.push(ind);
    while (!que.empty()) {
        int cur = que.front(); que.pop();
        for (int nx : G.at(cur)) {
            if (dis.at(nx) == -1) {
                dis.at(nx) = dis.at(cur) + 1;
                que.push(nx);
            }
        }
    }
    int res = -1;
    for (int i=0; i<n; ++i) chmax(res, dis.at(i));
    return res;
}

