	head[v] = cnt++;
}
int ans;
//树形dp
void dfs(int u) {
	vis[u] = 1;
	//最长路和次长路
	fir[u] = 0;
	sec[u] = 0;
	for (int i = head[u]; i != -1; i = edge[i].next) {
		int v = edge[i].v;
		if (!vis[v]) {
			//递归下去更新子节点信息
			dfs(v);
			//子节点的最长路+1更长，可以更新当前节点信息
			//当前节点的最长路变成次长路
			if (fir[v] + 1 >= fir[u]) {
				sec[u] = fir[u];
				fir[u] = fir[v] + 1;
			}
			//子节点信息只能更新次长路
			else if (fir[v] + 1 > sec[u]) {
				sec[u] = fir[v] + 1;
			}
		}
	}
	//更新整个树的信息
	ans = max(ans, fir[u] + sec[u]);
	return;
}
