pair<int, int> dfs(int start){
    pair<int, int> ans(0, start);
    vector<int> dist(MAX_SIZE+1,-1); // -1は未探訪
    stack<int> s;

    dist[start] = 0;
    s.push(start);

    // 木なのでsが空になるまで回せば全ての辺と頂点を巡る
    while(! s.empty()){
