pair<int, int> search(int from, int to, vector<vector<int>> &g)
{
    pair<int, int> result = {0, to};
    for (int next : g[to])
    {
        if (next != from)
        {
            auto tmp = search(to, next, g);
            tmp.first += 1;
            if (result.first < tmp.first)
            {
                result = tmp;
            }
        }
    }
    return result;
}

