void solve(long long N, std::vector<long long> a, std::vector<long long> b){

    ll len=0;
    ll last=-1;
    deque<ll> q;
    deque<pll> qq;
    if(N==1)goto first;
    tree.resize(N);
    used.resize(N);
    fill(used.begin(),used.end(),false);
    REP(N-1){
        tree[a[i]].push_back(b[i]);
        tree[b[i]].push_back(a[i]);
    }
    q.push_back(0);
    used[0]=true;
    while(!q.empty()){
        ll tmp=q.front();q.pop_front();
        for (auto &&i : tree[tmp])
        {
            if(used[i]==false){
                last=i;
                q.push_back(i);
                used[i]=true;
            }
        }
    }
    qq.push_back(pll(last,0));
    fill(used.begin(),used.end(),false);
    used[last]=true;
    while(!qq.empty()){
        pll tmp=qq.front();qq.pop_front();
        for (auto &&i : tree[tmp.first])
        {
            if(used[i]==false){
                len=max(len,tmp.second+1);
                qq.push_back(pll(i,tmp.second+1));
                used[i]=true;
            }
        }
    }
    if((len-1)%3)goto first;
    else goto second;
    first:
    cout<<"First"<<endl;
    return;
    second:
    cout<<"Second"<<endl;
    return ;
}

