LL dfs2(LL idx, LL d_par, LL par){
	vector<pair<LL, LL>> d_child;
	d_child.emplace_back(0, -1); // 番兵みたいなアレ
	for (LL &e : g[idx]) {
		if (e == par) d_child.emplace_back(d_par + 1, e);
		else d_child.emplace_back(1 + d[e], e);
	}
	sort(d_child.rbegin(), d_child.rend());
	LL ret = d_child[0].first; 
	d2[idx] = ret;
	for (LL &e : g[idx]) {
		if (e == par) continue;
		// 基本は d_child() の最大が d_par になるが, e.to の部分木が最大値のときはそれを取り除く必要がある
		ret = max(ret, dfs2(e, d_child[d_child[0].second == e].first, idx));
	}
	return (ret);
}

