void dfs (int x = 1, int pr = -1) {
	for (auto to : g[x]) {
		if (to == pr) continue;
		dfs(to, x);
	}        
	for (auto to : g[x]) {
		if (to == pr) continue;
		dist[x] = max(dist[x], dist[to] + 1);
	}
	int mx = -1;
	int pos = 0;
