	int sum = mx;

	mx = -1;
	for (auto to : g[x]) {
		if (to == pr || to == pos) continue;
		if (mx < dist[to]) {
			mx = dist[to];	
	   	}
	}
	int zero = 0;
	ansmx[x] = max(sum + 1, zero) + max(mx + 1, zero);
} 


