constexpr int INF = 1e9;

int dist[200005]={0};

void init(int n){
    for(int i=0;i<=n;++i)
        dist[i] = INF;
}

pair<int, int> dfs(int s, int d, const vector<vector<int>> &graph){
    if(dist[s] < INF)return make_pair(s, dist[s]);
    dist[s] = d;
    auto res = make_pair(s, d);
    for(auto to: graph[s]){
        auto p = dfs(to, d+1, graph);
        if(res.second < p.second)
            res = p;
    }
    return res;
}

int compute_diameter(int n, const vector<vector<int>> &graph){
    init(n);
    auto p = dfs(1, 0, graph);
    init(n);
    p = dfs(p.first, 0, graph);
    return p.second;
}

