using namespace std;

int FindFurthest(vector<vector<int> > &adj_nodes, int start, int* p_furthest)
{
  int N = adj_nodes.size();
  vector<bool> visited(N, false);
  int remaining = N;

  queue<int> q;
  q.push(start);
  visited[start] = true;
  --remaining;
  queue<int> nq;

  int dist = 1;
  bool done = false;
  while (remaining > 0) {
    while (not q.empty()) {
      int x = q.front();
      q.pop();
      for (auto nx : adj_nodes[x]) {
	if (not visited[nx]) {
	  nq.push(nx);
	  visited[nx] = true;
	  --remaining;
	  if (remaining == 0) {
	    *p_furthest = nx;
	    done = true;
	    break;
	  }
	}
      }
      if (done) break;
    }
    if (done) break;
    swap(q, nq);
    ++dist;
  }

  return dist;
}

int main()
{
  int N;
  cin >> N;

  if (N == 1) {
    cout << "First" << endl;
    return 0;
  }

  vector<vector<int> > adj_nodes(N);

  for (int i = 0; i < N - 1; ++i) {
    int a, b;
