int64_t dfs(const vector<vector<int64_t>>& links, vector<int64_t>& distance, int64_t node) {
    auto d = distance[node];

    int64_t mn = node;
    int64_t m = d;
    for (auto a : links[node]) {
        if (distance[a] != numeric_limits<int64_t>::max()) {
            continue;
        }

        distance[a] = d + 1;
        auto nn = dfs(links, distance, a);
        if (distance[nn] > m) {
            mn = nn;
            m = distance[nn];
        }
    }

    return mn;
}

