pair<int, int> dfs(const vector<vector<int>>& graph, int v, int p) {
    int diam = 0;

    int top1 = 0, top2 = 0;

    for (int u: graph[v])
        if (u != p) {
            auto sub = dfs(graph, u, v);

            diam = max(diam, sub.first);
            sub.second += 1;

            if (sub.second > top1)
                top2 = top1, top1 = sub.second;
            else if (sub.second > top2)
                top2 = sub.second;
        }

    diam = max(diam, top1 + top2);
    return {diam, top1};
}

