using namespace std;

using Weight = long long;
struct Edge
{
	int src, dst;
	Weight weight;
	Edge(int src, int dst, Weight weight) : src(src), dst(dst), weight(weight) {}
};

auto operator<(const Edge &e, const Edge &f)
{
	if (e.weight != f.weight)
		return e.weight > f.weight;
	else if (e.src != f.src)
		return e.src < f.src;
	else
		return e.dst < f.dst;
}

using Edges = vector<Edge>;
using Graph = vector<Edges>;

pair<Weight, int> sweep(int p, int v, const Graph &g)
{
	pair<Weight, int> r(0, v);
	for (auto e : g[v])
	{
		if (e.dst != p)
		{
			pair<Weight, int> t = sweep(v, e.dst, g);
			t.first += e.weight;
			if (r.first < t.first)
				r = t;
		}
	}
	return r;
}

Weight double_sweep(const Graph &g, int s)
{
	pair<Weight, int> r = sweep(-1, s, g);
	pair<Weight, int> t = sweep(-1, r.second, g);
	return t.first; // (r.second, t.second) is farthest pair.
}

int main()
{
	int n;
	cin >> n;
	Graph g(n);
	for (int i = 1; i < n; ++i)
	{
		int s, t;
		cin >> s >> t;
		s--, t--;
		g[s].emplace_back(s, t, 1);
		g[t].emplace_back(t, s, 1);
	}
	auto c = double_sweep(g, 0);
	if (c % 3 == 1)
	{
		cout << "Second" << endl;
	}
	else
	{
		cout << "First" << endl;
	}
	//cout << c << endl;
