using namespace std;

unordered_multimap<int, int> tree;
int num[200001] = { 0 };

int num_path(int p, unordered_multimap<int, int>& trees)
{
	FOR_LE(i, 0, 200000) {
		num[i] = -1;
	}
	queue<int> search;
	search.push(p);
	num[p] = 0;

	while (!search.empty()) {
		int p2 = search.front();
		search.pop();

		auto it = trees.find(p2);
		while (it != trees.end() && it->first == p2) {
			if (num[it->second] != -1) {
				it++;
				continue;
			}

			num[it->second] = num[it->first] + 1;
			search.push(it->second);


		}
	}

	int ans = 0;
	FOR_LE(i, 0, 200000) {
		ans = max(num[i], ans);
	}

	return ans;
}

int main()
{
	int n;
	cin >> n;

	FOR_LT(i, 0, n - 1) {
		int a, b; cin >> a >> b;
		tree.insert(make_pair(a, b));
		tree.insert(make_pair(b, a));
	}


	// 末端の数
	int p = 0;
	int count = 0;
	for (auto elem : tree) {
		if (elem.first != p) {
			if (count == 1) {
				break;
			}
			p = elem.first;
		}
		count++;
	}

	int path = num_path(p, tree);
	vector<int> wins(path + 1);
	wins[1] = false;
	wins[2] = true;
	FOR_LE(i, 3, path) {
		if (wins[i - 2] && wins[i - 1]) {
			wins[i] = false;
		}
		else {
			wins[i] = true;
		}
	}

	if (wins[path]) {
		cout << "First" << endl;
	}
	else {
		cout << "Second" << endl;
	}

	return 0;
}

