  int src, to;
  T cost;

  edge(int to, T cost) : src(-1), to(to), cost(cost) {}

  edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}

  edge &operator=(const int &x) {
    to = x;
    return *this;
  }

  operator int() const { return to; }
};

template <typename T>
using Edges = vector<edge<T> >;
template <typename T>
using WeightedGraph = vector<Edges<T> >;
using UnWeightedGraph = vector<vector<int> >;
template <typename T>
using Matrix = vector<vector<T> >;

template <typename T>
pair<T, int> dfs(const WeightedGraph<T> &g, int idx, int par) {
  pair<T, int> ret(0, idx);
  for (auto &e : g[idx]) {
    if (e.to == par) continue;
    auto cost = dfs(g, e.to, idx);
    cost.first += e.cost;
    ret = max(ret, cost);
  }
  return ret;
}

template <typename T>
T tree_diameter(const WeightedGraph<T> &g) {
  auto p = dfs(g, 0, -1);
  auto q = dfs(g, p.second, -1);
  return (q.first);
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, as[MAX_N - 1], bs[MAX_N - 1];
  scanf("%d", &N);
  for (int i = 0; i < N - 1; i++) {
    scanf("%d %d", &as[i], &bs[i]);
    as[i]--;  // NOTE : modified input
    bs[i]--;  // NOTE : modified input
  }

  // create graph
  WeightedGraph<int> g(N);
  for (int i = 0; i < N - 1; i++) {
    const int a = as[i], b = bs[i];
    g[a].emplace_back(b, 1);
    g[b].emplace_back(a, 1);
  }

  // calculate diameter of tree
  const int diameter = tree_diameter(g);
  // printf("diameter = %d\n", diameter);

  // calculate dp
  vector<int> dps(N, 0);  // first player wins?
  dps[0] = 1;
  dps[1] = 0;
  for (int i = 2; i <= N - 1; i++) {
    if (!dps[i - 1] || !dps[i - 2]) {
      dps[i] = 1;
    } else {
      dps[i] = 0;
    }
  }

  // print answer
  if (dps[diameter]) {
    printf("First\n");
  } else {
    printf("Second\n");
  }

  return 0;
}

