struct edge {
  int ix;
  int *v;
};

struct res {
  int d, v;
};

int *va, *vb;
int *cnt;
bool *visited;
struct edge *e;

struct res visit(int vertex)
{
  struct res r, t;

  r.d = 0;
  r.v = vertex;
  visited[vertex] = true;
  for (int i = 0; i < e[vertex].ix; i++) {
    if (!visited[e[vertex].v[i]]) {
      t = visit(e[vertex].v[i]);
      if (r.d <= t.d) {
        r.d = t.d + 1;
        r.v = t.v;
      }
    }
  }
  visited[vertex] = false;

  return r;
}

