void long_path_loop(int n, int i, int visited[n], int g[n][n], int parent){
  if (visited[i]){
    return;
  }
  //printf("visit %d\n", i);
  visited[i] = 1;
  int j;
  if(i != 0){
    for(j=0;j<n;j++){
      if(visited[j] && i != j){
        g[i][j] = g[parent][j] + 1;
        g[j][i] = g[j][parent] + 1;
        //printf("path %d %d: %d\n", i, j, path[i][j]);
      }
    }
  }
  for(j=0;j<n;j++){
    if(g[i][j] == 1){
      long_path_loop(n, j, visited, g, i);
    }
  }
  //return 0;
}
