    for(j=0;j<n;j++){
      path[i][j] = 0;
    }
  }
  */
  for(i=0;i<n;i++){
    visited[i] = 0;
  }
  for(i=0;i<n;i++){
    long_path_loop(n, i, visited, g, -1);
  }
  int max = 0;
  for(i=0;i<n;i++){
    for(j=i+1;j<n;j++){
      if(g[i][j] > max){
        max = g[i][j];
      }
    }
  }
  return max;
}
