typedef struct {
  int index;
  int *v;
} edge;

typedef struct {
  int d, v;
} distance;

int *va, *vb;
int *vertex_count;
bool *visited;
edge *undirected_graph;

distance visit(int vertex)
{
  distance r, t;

  r.d = 0;
  r.v = vertex;
  visited[vertex] = true;
  for (int i = 0; i < undirected_graph[vertex].index; i++) {
    if (!visited[undirected_graph[vertex].v[i]]) {
      t = visit(undirected_graph[vertex].v[i]);
      if (r.d <= t.d) {
        r.d = t.d + 1;
        r.v = t.v;
      }
    }
  }
  visited[vertex] = false;

  return r;
}

