cell* append(cell* a, cell* b,bool *err)
{
  if(a==NULL)
    {
      *err=1;
      return b;
    }
  return cons(a->car,(append(a->cdr,b,err)),err);
}
cell* reverse(cell* a,bool *err)
{
  cell* temp=NULL;
  cell* now=a;


  while(now!=NULL)
    {
      temp=cons(now->car,temp,err);
      now=now->cdr;
    }
  return temp;
}
int length(cell* a)
{
  int len=0;
  cell* temp=a;
  while(temp!=NULL)
    {
      len++;
      temp=temp->cdr;
    }
  return len;
}

item nth(cell* a,int n,bool *err)
{
  int len=length(a);
  if(n>len)
    {
      printf("nil.");
      *err=0;
      return NULL_ITEM;
    }
  if(n<0)
    {
      printf("Be positive.");
      *err=0;
      return NULL_ITEM;
    }
  int i;
  cell* temp=a;
  *err=1;
  for(i=0;i<n;i++)
    {
      temp=temp->cdr;
    }
  return temp->car;
}
void add_n(item val,cell** a,int n,bool *err)
{

  int len=length(*a);
  if(n>len)
    {
      printf("too large.");
      *err=0;
      return;
    }
  if(n<0)
    {
      printf("Be positive.");
      *err=0;
      return;
    }
  int i;
  cell* temp;
  *err=1;
  if(n==0)
    {
      temp=cons(val,*a,err);
      *a=temp;
      return;
    }
  temp=*a;
  for(i=0;i<n-1;i++)
    {
      temp=temp->cdr;
    }
  cell* next=temp->cdr;
  cell* new=cons(val,next,err);
  temp->cdr=new;
  return;
}


item del_n(cell** a,int n,bool *err)
{

  int len=length(*a);
  if(n>=len)
    {
      printf("too large.");
      *err=0;
      return NULL_ITEM;
    }
  if(n<0)
    {
      printf("Be positive.");
      *err=0;
      return NULL_ITEM;
    }
  int i;
  cell* temp=*a;
  *err=1;
  if(n==0)
    {
      item x=temp->car;
      temp=temp->cdr;
      *a=temp;
      return x;
    }
  for(i=0;i<n-1;i++)
    {
      temp=temp->cdr;
    }
  cell* next=temp->cdr;
  cell* nnxt=next->cdr;

  temp->cdr=nnxt;
  item val=next->car;
  free(next);
  return val;
}

