typedef struct List {
	struct List *next;
	int v;
} list;

int main()
{	
	int i, N, u, w;
	list *adj[200001] = {}, e[400001];
	scanf("%d", &N);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d\n", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj[w];
		adj[u] = &(e[i*2]);
		adj[w] = &(e[i*2+1]);
	}

	int dist[200001] = {}, q[200001], head, tail;
	list *p;
	q[0] = 1;
	dist[q[0]] = -1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (p = adj[u]; p != NULL; p = p->next) {
			w = p->v;
			if (dist[w] == 0) {
				dist[w] = -1;
				q[tail++] = w;
			}
		}
	}
	q[0] = q[tail-1];
	dist[q[0]] = 1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (p = adj[u]; p != NULL; p = p->next) {
			w = p->v;
			if (dist[w] == -1) {
				dist[w] = dist[u] + 1;
				q[tail++] = w;
			}
		}
	}

	if ((dist[q[tail-1]] + 1) % 3 != 0) printf("First\n");
	else printf("Second\n");
	fflush(stdout);
	return 0;
}

