		int[] q = new int[n];
		boolean[] ved = new boolean[n];
		{
			int qp = 0;
			q[qp++] = 0; ved[0] = true;
			for(int i = 0;i < qp;i++){
				int cur = q[i];
				for(int e : g[cur]){
					if(!ved[e]){
						ved[e] = true;
						q[qp++] = e;
						continue;
					}
				}
			}
			f0 = q[n-1];
		}
		{
			int[] d = new int[n];
			int qp = 0;
			Arrays.fill(ved, false);
			q[qp++] = f0; ved[f0] = true;
			for(int i = 0;i < qp;i++){
				int cur = q[i];
				for(int e : g[cur]){
					if(!ved[e]){
						ved[e] = true;
						q[qp++] = e;
						d[e] = d[cur] + 1;
						continue;
					}
				}
			}
			f1 = q[n-1];
			d01 = d[f1];
		}
		return new int[]{d01, f0, f1};
	}


	public static int[][] parents3(int[][] g, int root) {
		int n = g.length;
		int[] par = new int[n];
		Arrays.fill(par, -1);

		int[] depth = new int[n];
		depth[0] = 0;

		int[] q = new int[n];
		q[0] = root;
		for (int p = 0, r = 1; p < r; p++) {
			int cur = q[p];
			for (int nex : g[cur]) {
				if (par[cur] != nex) {
					q[r++] = nex;
					par[nex] = cur;
					depth[nex] = depth[cur] + 1;
				}
			}
		}
		return new int[][] { par, q, depth };
	}

	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}


