import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.System.arraycopy;
import static java.lang.System.exit;
import static java.util.Arrays.copyOf;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {

	static class IntList {

		int data[] = new int[3];
		int size = 0;

		boolean isEmpty() {
			return size == 0;
		}

		int size() {
			return size;
		}

		int get(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			return data[index];
		}

		void clear() {
			size = 0;
		}

		void set(int index, int value) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			data[index] = value;
		}

		void expand() {
			if (size >= data.length) {
				data = copyOf(data, (data.length << 1) + 1);
			}
		}

		void insert(int index, int value) {
			if (index < 0 || index > size) {
				throw new IndexOutOfBoundsException();
			}
			expand();
			arraycopy(data, index, data, index + 1, size++ - index);
			data[index] = value;
		}

		int delete(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			int value = data[index];
			arraycopy(data, index + 1, data, index, --size - index);
			return value;
		}

		void push(int value) {
			expand();
			data[size++] = value;
		}

		int pop() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			return data[--size];
		}

		void unshift(int value) {
			expand();
			arraycopy(data, 0, data, 1, size++);
			data[0] = value;
		}

		int shift() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			int value = data[0];
			arraycopy(data, 1, data, 0, --size);
			return value;
		}
	}

	static int n;
	static IntList edges[];

	static int maxDepth, maxV;

	static void solve() throws Exception {
		n = scanInt();
		edges = new IntList[n];
		for (int i = 0; i < n; i++) {
			edges[i] = new IntList();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = scanInt() - 1, b = scanInt() - 1;
			edges[a].push(b);
			edges[b].push(a);
		}
		maxDepth = 0;
		maxV = 0;
		dfs(0, -1, 0);
		maxDepth = 0;
		dfs(maxV, -1, 0);
		out.print(maxDepth % 3 == 1 ? "Second" : "First");
	}

	static void dfs(int cur, int prev, int depth) {
		if (depth > maxDepth) {
			maxDepth = depth;
			maxV = cur;
		}
		for (int i = 0; i < edges[cur].size; i++) {
			int next = edges[cur].data[i];
			if (next != prev) {
				dfs(next, cur, depth + 1);
			}
		}
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.util.Arrays;

public class Main {


  private static void solve() {
    int n = ni();
    int[] from = new int[n - 1];
    int[] to = new int[n-  1];
    for (int i = 0; i < n - 1; i ++) {
      from[i] = ni()-1;
      to[i] = ni()-1;
    }
    int[][] g = packU(n, from, to);
    int d = diameter(g)[0];

    System.out.println(d % 3 == 1 ? "Second" : "First");
  }

  public static int[][] packU(int n, int[] from, int[] to){ return packU(n, from, to, from.length); }
  public static int[][] packU(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < sup;i++)p[to[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }
  public static int[] diameter(int[][] g)
  {
      int n = g.length;
      int f0 = -1, f1 = -1, d01 = -1;
      int[] q = new int[n];
      boolean[] ved = new boolean[n];
      {
          int qp = 0;
          q[qp++] = 0; ved[0] = true;
          for(int i = 0;i < qp;i++){
              int cur = q[i];
              for(int e : g[cur]){
                  if(!ved[e]){
                      ved[e] = true;
                      q[qp++] = e;
                      continue;
                  }
              }
          }
          f0 = q[n-1];
      }
      {
          int[] d = new int[n];
          int qp = 0;
          Arrays.fill(ved, false);
          q[qp++] = f0; ved[f0] = true;
          for(int i = 0;i < qp;i++){
              int cur = q[i];
              for(int e : g[cur]){
                  if(!ved[e]){
                      ved[e] = true;
                      q[qp++] = e;
                      d[e] = d[cur] + 1;
                      continue;
                  }
              }
          }
