public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        IntArrayList[] adj = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new IntArrayList();
        }
        for (int i = 0; i < n - 1; i++) {
            int u = In.ni() - 1;
            int v = In.ni() - 1;
            adj[u].add(v);
            adj[v].add(u);
        }
        out.append(diameter(adj) % 3 == 1 ? "Second" : "First");
    }

    public static int diameter(IntArrayList[] adj) {
        int n = adj.length;
        IntQueue q = new IntQueue(n);
        q.add(0);
        int[] d = new int[n];
        Arrays.fill(d, -1);
        d[0] = 0;
        int max = 0;
        int maxv = 0;
        while (q.size() > 0) {
            int u = q.poll();
            if (d[u] > max) {
                max = d[u];
                maxv = u;
            }
            PrimitiveIterator.OfInt iter = adj[u].iterator();
            while (iter.hasNext()) {
                int v = iter.nextInt();
                if (d[v] < 0) {
                    d[v] = d[u] + 1;
                    q.add(v);
                }
            }
        }
        return bfs(adj, maxv);
    }

    public static int bfs(IntArrayList[] adj, int r) {
        int n = adj.length;
        IntQueue q = new IntQueue(n);
        q.add(r);
        int[] d = new int[n];
        Arrays.fill(d, -1);
        d[r] = 0;
        int max = 0;
        while (q.size() > 0) {
            int u = q.poll();
            max = Math.max(max, d[u]);
            PrimitiveIterator.OfInt iter = adj[u].iterator();
            while (iter.hasNext()) {
                int v = iter.nextInt();
                if (d[v] < 0) {
                    d[v] = d[u] + 1;
                    q.add(v);
                }
            }
        }
        return max;
    }
}


