	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte() {
		if (lenbuf == -1)
			throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	private double nd() {
		return Double.parseDouble(ns());
	}

	private char nc() {
		return (char) skip();
	}

	private String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != '
									// ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n) {
			if (!(isSpaceChar(b)))
				buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	private int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private int[][] na(int n, int m) {
		int[][] a = new int[n][];
		for (int i = 0; i < n; i++)
			a[i] = na(m);
		return a;
	}

	private int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class AtCoder {

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int N = Integer.parseInt(br.readLine());

		String[] input;
		ArrayList<Point> points = new ArrayList<Point>();

		input = br.readLine().split(" ");
		points.add(new Point(Integer.parseInt(input[0])));
		points.add(new Point(Integer.parseInt(input[1])));
		points.get(0).connect(points.get(1));
		points.get(1).connect(points.get(0));
		//sideにindex0を追加するコードがここ
		//以下forで辺情報を読み込み、Pointに格納
		for(int i=1;i<N;i++) {
			input = br.readLine().split(" ");
			int[] side = {Integer.parseInt(input[0]),Integer.parseInt(input[1])};
			for(int j=1;j<=i;j++) {
				Point target = points.get(j);
				if(side[0]==target.no) {
					Point newPoint = new Point(side[1]);
					points.add(newPoint);
					target.connect(newPoint);
					newPoint.connect(target);
					break;
				}else if(side[1]==target.no) {
					Point newPoint = new Point(side[0]);
					points.add(newPoint);
					target.connect(newPoint);
					newPoint.connect(target);
					break;
				}
			}
		}

		PointsMng tree = new PointsMng(points);

		if(tree.calcFar()%3==2) 
			System.out.println("Second");
		else
			System.out.println("First");

	}

}

class Point{
	int no;
	int lengthToFar;
	ArrayList<Point> next;

	Point(int no){
		this.no = no;
	}

	void connect(Point next) {
		this.next.add(next);
	}

	int calcMaxLength(Point back){
		int max =0;
		for(Point nextPoint:next) {
			if(nextPoint != back) {
				int length = nextPoint.calcMaxLength(this)+1;
				if(max < length) max=length;
			}
		}
		return max;
	}
}

class PointsMng{

	ArrayList<Point> tree;
	ArrayList<Point> ends;
	PointsMng(ArrayList<Point> tree){
		this.tree = tree;
		for(Point point:tree) {
			if(point.next.size()==1) ends.add(point);
		}
	}

	int calcFar(){
		int max = 0;
		for(Point end:ends) {
			if(max < (end.lengthToFar = end.calcMaxLength(null))) {
				max = end.lengthToFar;
			}
		}
