class Tree {
    public final int n;
    public final int root;

    private final IntArrayList[] adj;
    private final int[] par;
    private final int[] dep;

    protected boolean bfs = false;

    public Tree(int n, int root) {
        this.n = n;
        this.root = root;
        this.adj = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new IntArrayList();
        }
        this.par = new int[n];
        this.dep = new int[n];
    }

    public Tree(int n) {
        this(n, 0);
    }

    public void addEdge(int from, int to) {
        adj[from].add(to);
        adj[to].add(from);
    }

    public int getEdge(int from, int index) {
        return adj[from].get(index);
    }

    public IntArrayList getEdges(int i) {
        return adj[i];
    }

    public int out(int i) {
        return adj[i].size();
    }

    public int parent(int i) {
        return parent()[i];
    }

    public int[] parent() {
        if (!bfs) {
            bfs();
            bfs = true;
        }
        return par;
    }

    public int dep(int i) {
        return dep()[i];
    }

    public int[] dep() {
        if (!bfs) {
            bfs();
            bfs = true;
        }
        return dep;
    }

    private void bfs() {
        IntQueue que = new IntQueue(n);
        que.add(root);
        par[root] = root;
        while (que.size() > 0) {
            int v = que.poll();
            PrimitiveIterator.OfInt iter = getEdges(v).iterator();
            while (iter.hasNext()) {
                int u = iter.nextInt();
                if (u != par[v]) {
                    dep[u] = dep[v] + 1;
                    par[u] = v;
                    que.add(u);
                }
            }
        }
    }

    public int diameter() {
        int[] d = dep();
        int maxd = 0;
        int maxv = root;
        for (int i = 0; i < n; i++) {
            if (maxd < d[i]) {
                maxd = d[i];
                maxv = i;
            }
        }
        IntQueue q = new IntQueue(n);
        q.add(maxv);
        int[] dd = new int[n];
        Arrays.fill(dd, -1);
        dd[maxv] = 0;
        int max = 0;
        while (q.size() > 0) {
            int u = q.poll();
            PrimitiveIterator.OfInt iter = getEdges(u).iterator();
            while (iter.hasNext()) {
                int v = iter.nextInt();
                if (dd[v] < 0) {
                    dd[v] = dd[u] + 1;
                    q.add(v);
                    max = Math.max(max, dd[v]);
                }
            }
        }
        return max;
    }
}


