public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0xfffffffffffffffL;
    static final int iinf = 0xfffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int n = in.nextInt();
        List<List<Integer>> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new ArrayList<>());
        }
        for (int i = 1; i < n; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            edges.get(a).add(b);
            edges.get(b).add(a);
        }
        int v = bfs(n, 0, edges);
        int u = bfs(n, v, edges);
        out.println(d % 3 == 1 ? "Second" : "First");
    }

    int d;
    int bfs(int n, int root, List<List<Integer>> edges) {
        int[] dist = new int[n];
        Arrays.fill(dist, iinf);
        dist[root] = 0;
        Deque<Integer> deque = new ArrayDeque<>();
        deque.add(root);
        while (!deque.isEmpty()) {
            Integer v = deque.pollFirst();
            for (Integer u : edges.get(v)) {
                if (dist[u] == iinf) {
                    dist[u] = dist[v] + 1;
                    deque.addLast(u);
                }
            }
        }
        int mi = 0;
        for (int i = 0; i < n; i++) {
            if (dist[mi] < dist[i]) {
                mi = i;
            }
        }
        d = dist[mi];
        return mi;
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

