public void solve() {
	int numNode = ni();
	int numEdge = numNode - 1;
	Graph g = new Graph(numNode, numEdge, false);
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	g.init(edges);
	long dist[] = bfs(g.nodes, 0);
	int far = 0;
	int max = (int)max(dist);
	for(int i = 0; i < numNode; i ++) {
		if(dist[i] == max) far = i;
	}
	dist = bfs(g.nodes, far);
	max = (int)max(dist);
	errprtln(max);

	boolean dp[] = new boolean[max + 1];
	dp[0] = true;
	dp[1] = false;
	for(int i = 2; i <= max; i ++) {
		dp[i] = !dp[i - 1] || !dp[i - 2];
	}
	errprtln(dp);
	prtln(dp[max] ? "First" : "Second");
}

long[] bfs(Node nodes[], int start) {
	long dist[] = new long[nodes.length];
	Arrays.fill(dist, INF);

	Deque<Integer> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start] = 0;
	while(!s.isEmpty()) {
		int crt = s.removeFirst();
		for(Edge e : nodes[crt]) {
			if(isINF(dist[e.target])) {
				dist[e.target] = dist[e.source] + 1;
				s.addLast(e.target);
			}
		}
	}

	return dist;
}

