using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
static string[] input = Console.ReadLine().Split(' ');
static long n = long.Parse(input[0]);
static long m = n-1;
static List<long[]>[] nextList = new List<long[]>[n];//頂点番号ごとの隣接リスト。距離、隣接頂点番号
static long[] colors = new long[n];//最短距離未確定の頂点が0、確定で2
static long[] distances = new long[n];//各頂点への最短距離
static long[] distanceMemos = new long[2];//キューから捨てた最短距離と頂点番号
static long maxVertexNumN = 0;

	static void Main()
	{
    for(long i = 0; i < n; i++) nextList[i] = new List<long[]>();//リストの宣言が必要
    for(long i = 0; i < m; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);

      long[] nextMemo = new long[2];
      nextMemo[1] = nums[1]-1;//隣接頂点番号
      nextMemo[0] = 1;//距離
      nextList[nums[0]-1].Add(nextMemo);//隣接リストの作成

      long[] nextMemoSub = new long[2];
      nextMemoSub[1] = nums[0]-1;//隣接頂点番号
      nextMemoSub[0] = 1;//距離
      nextList[nums[1]-1].Add(nextMemoSub);
    }

    Dijkstra(0);
    //Console.WriteLine(maxVertexNumN);
    Console.WriteLine((Dijkstra(maxVertexNumN) % 3 == 1) ? "Second" : "First");
	}

  static long Dijkstra(long startVertexNum)
	//O((|頂点数|+|辺数|)log頂点数)で各頂点への最短距離を求める
  {
    List<long[]> distanceList = new List<long[]>();//優先度付きキュー
    for(long i = 0; i < n; i++)
    {
      distances[i] = long.MaxValue;//最短距離を無限とおく
      colors[i] = 0;//最短距離を無限とおく
    }

    long[] newDistance = new long[2];

    //スタート地点を決める
    newDistance[1] = startVertexNum;//スタート地点番号
    distances[startVertexNum] = 0;
    colors[startVertexNum] = 1;

    newDistance[0] = 0;//スタートからスタートまでの距離0
    distanceList.Add(newDistance);

    while(distanceList.Count() != 0)
    {
      distanceList = PopHeap(distanceList);
      long minVertex = distanceMemos[1];//最短頂点の番号
      colors[minVertex] = 2;
      if(distances[minVertex] < distanceMemos[0]) continue;//最小値が最短でないなら無視

      for(long i = 0; i < nextList[minVertex].Count(); i++)
      {
        long v = nextList[minVertex][(int)i][1];
        if(colors[v] == 2) continue;
        if(distances[v] > distances[minVertex] + nextList[minVertex][(int)i][0])
        {
          distances[v] = distances[minVertex] + nextList[minVertex][(int)i][0];
          long[] newDistanceSub = new long[2];
          newDistanceSub[0] = distances[v];
          newDistanceSub[1] = v;
          distanceList = PushHeap(distanceList, newDistanceSub);
          colors[v] = 1;
        }
      }
    }

    long maxVertexNum = 0;
    long maxDistance = 0;
    for(long i = 0; i < n; i++)
    {
      if(maxDistance < distances[i])
      {
        maxVertexNum = i;
        maxDistance = distances[i];
      }
    }

    maxVertexNumN = maxVertexNum;
    return maxDistance;

  }

  //引数は、昇順にソート済みのリスト
  static List<long[]> PushHeap(List<long[]> nums, long[] addNums)//現在のヒープnumsにaddNumを追加
  {
    int n = nums.Count;
    nums.Add(addNums);

    while (n > 0)
    {
      int i = (n-1)/2;
      if (nums[n][0] < nums[i][0])//親のほうが大きいなら入れ替え。
      {
        long tmp = nums[n][0];
        long tmpSub = nums[n][1];
        nums[n][0] = nums[i][0];
        nums[n][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      n = i;
    }
    return nums;
  }

  static List<long[]> PopHeap(List<long[]> nums)//ヒープnumsからポップ
  {
    int n = nums.Count - 1;
    distanceMemos[0] = nums[0][0];//捨てる値の保存
    distanceMemos[1] = nums[0][1];
    nums[0][0] = nums[n][0];//最小値である根を削除してリストの最後を持ってくる
    nums[0][1] = nums[n][1];
    nums.RemoveAt(n);

    for (int i = 0, j; (j = 2*i+1) < n; )
    {
      if ((j != n-1) && (nums[j][0] > nums[j+1][0]))// ２つの子のうち、値の小さい方を選ぶ
        j++;
      if (nums[i][0] > nums[j][0])//子が親より小さいなら入れ替え
      {
        long tmp = nums[j][0];
        long tmpSub = nums[j][1];
        nums[j][0] = nums[i][0];
        nums[j][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      i = j;
    }
    return nums;
  }

}

