    class Program
    {
        private int N;
        private List<int>[] E;
        private bool[] Memo;
        public void Solve()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            E = new List<int>[N];
            for (int i = 0; i < N; i++)
            {
                E[i] = new List<int>();
            }
            for (int i = 0; i < N - 1; i++)
            {
                int a = sc.NextInt() - 1;
                int b = sc.NextInt() - 1;
                E[a].Add(b);
                E[b].Add(a);
            }
            Memo = new bool[N];
            int s;
            Dist(0, out s);
            int g;
            Memo = new bool[N];
            int dist = Dist(s, out g);
            //Console.WriteLine($"{dist} {s} {g}");
            Console.WriteLine(dist%3 ==1?"Second":"First");
        }

        private int Dist(int n, out int o)
        {
            int ret = 0;
            o = n;
            Memo[n] = true;
            foreach (var i in E[n])
            {
                if (!Memo[i])
                {
                    int oo;
                    int d = Dist(i, out oo) + 1;
                    if (ret < d)
                    {
                        ret = d;
                        o = oo;
                    }
                }
            }

            Memo[n] = false;
            return ret;
        }

        static void Main() => new Program().Solve();
    }
