                foreach (var i in neighbor[v])
                {
                    if (i == prev) continue;
                    dfs(i, v, dist + 1);
                }

                return 0;
            };
            dfs(maxIndex, -1, 0);
            Console.WriteLine((dist2.Max() + 1) % 3 == 2 ? "Second" : "First");
        }
    }
}

