public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var adj = Range(0, N).Select(_ => new List<long>()).ToArray();
		for(long i = 0; i < N - 1; i++)
		{
			long a = GetLong() - 1;
			long b = GetLong() - 1;
			adj[a].Add(b);
			adj[b].Add(a);
		}
		var first = bfs(N, adj, 0);
		var firstMax = first.Max();
		var e = Array.FindIndex(first, x => x == firstMax);
		var second = bfs(N, adj, e);
		var L = second.Max();

		WriteLine((L % 3 != 1) ? "First" : "Second");
	}

	private long[] bfs(long N, List<long>[] adj, long s)
	{
		var res = Enumerable.Repeat(-1L, (int)N).ToArray();
		var queue = new Queue<long>();
		res[s] = 0;
		queue.Enqueue(s);
		while(queue.Count > 0)
		{
			long v = queue.Dequeue();
			foreach(var u in adj[v])
			{
				if(res[u] != -1)
					continue;

				res[u] = res[v] + 1;
				queue.Enqueue(u);
			}
		}
		return res;
	}
}

