static class CodeJam
{
    static int[] Distances(List<int>[] nexts, int i)
    {
        const int INF = int.MaxValue / 2;
        int N = nexts.Length;
        var d = Enumerable.Repeat(INF, N).ToArray();
        d[i] = 0;
        var q = new Queue<int>();
        q.Enqueue(i);
        while (q.Count > 0)
        {
            int a = q.Dequeue();
            foreach (int b in nexts[a])
            {
                if (d[a] + 1 < d[b])
                {
                    d[b] = d[a] + 1;
                    q.Enqueue(b);
                }
            }
        }
        return d;
    }

    static bool Solve(int N, int[][] edges)
    {
        var nexts = new List<int>[N];
        for (int i = 0; i < N; ++i) { nexts[i] = new List<int>(); }
        foreach (var edge in edges)
        {
            int a = edge[0];
            int b = edge[1];
            nexts[a].Add(b);
            nexts[b].Add(a);
        }
        int[] d1 = Distances(nexts, 0);
        int j = 0;
        for (int i = 1; i < N; ++i)
        {
            if (d1[i] > d1[j]) { j = i; }
        }
        int[] d2 = Distances(nexts, j);
        int diameter = d2.Max();
        return diameter % 3 != 1;
    }

    static void Main(string[] args)
    {
        int N = int.Parse(Console.ReadLine());
        var edges = new int[N - 1][];
        for (int i = 0; i < N - 1; ++i)
        {
            edges[i] = Array.ConvertAll(Console.ReadLine().Split(), x => int.Parse(x) - 1);
        }
        Console.WriteLine(Solve(N, edges) ? "First" : "Second");
    }
}

