	public static long[] TreeDiameter(IEnumerable<P<long,long,long>> inEdges, long V) {
		var G = new Dictionary<long,long>[V]; 
		for(int i=0;i<V;i++) G[i] = new Dictionary<long,long>();
		foreach(var e in inEdges){
			G[e.A][e.B] = e.C;
			G[e.B][e.A] = e.C;
		}
		Func<long , long, KeyValuePair<long, long>> td_dfs = null;
		td_dfs = (idx, par)=>{
			var ret = new KeyValuePair<long, long>(0,idx);
			foreach(var e in G[idx]) {
				if(e.Key == par) continue;
				var cost = td_dfs(e.Key, idx);
				cost = new KeyValuePair<long, long>(cost.Key+e.Value,cost.Value);
				ret = cost.Key<ret.Key?ret:cost;
			}
			return ret;	
		};
		var p = td_dfs(0, -1);
		var q = td_dfs(p.Value, -1);
		return new long[]{q.Key, p.Value, q.Value};
	}












