                    int idx1 = 0;
                    int idx2 = W;
                    for (int i = N - 1; i >= 0; --i)
                    {
                        switch (T[i])
                        {
                            case 'L': idx2 = Math.Min(W, idx2 + 1); break;
                            case 'R': idx1 = Math.Max(0, idx1 - 1); break;
                        }
                        switch (S[i])
                        {
                            case 'L': idx1++; break;
                            case 'R': idx2--; break;
                        }
                        if (idx1 == idx2) { Console.WriteLine("NO"); return; }
                    }
                    if (idx1 >= SC || idx2 < SC) { Console.WriteLine("NO"); return; }
                }
                Console.WriteLine("YES");
            }
            public static void C()
            {
                var N = Read.Int();
                var Adj = Read.AdjacencyList(N, N - 1);
                var dist1 = Util.CalcDistance_OnTree(Adj, N, 1);
                var max = dist1.Max();
                var dist2 = Util.CalcDistance_OnTree(Adj, N, Enumerable.Range(1, N).Where(i => dist1[i] == max).First());
                var d = dist2.Max();
                Console.WriteLine(d % 3 != 1 ? "First" : "Second");
            }
        }


        class Util
        {
            public static int[] CalcDistance_OnTree(Dictionary<int, HashSet<int>> adj, int N, int start)
            {
                var dist = Enumerable.Range(0, N + 1).Select(i => -1).ToArray();
                dist[start] = 0;
                Queue<int> queue = new Queue<int>();
                queue.Enqueue(start);
                while (queue.Count > 0)
                {
                    var v = queue.Dequeue();
                    foreach (var w in adj[v])
                    {
                        if (dist[w] < 0)
                        {
                            dist[w] = dist[v] + 1;
                            queue.Enqueue(w);
                        }
                    }
                }
                return dist;
            }
        }

