using System;
using System.Collections.Generic;
using System.Linq;

public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var edges = new Dictionary<int, List<int>>(n);
        for (int i = 1; i <= n; ++i)
            edges[i] = new List<int>();
        for (int count = n - 1; count != 0; --count)
        {
            var line = Console.ReadLine().Split(' ');
            var a = int.Parse(line[0]);
            var b = int.Parse(line[1]);
            edges[a].Add(b);
            edges[b].Add(a);
        }

        var past = new bool[n + 1];
        var current = new List<int>(){ 1 };
        var next = new List<int>();
        int end = 0;

        for (int count = 1; count > 0; count = current.Count)
        {
            end = current[0];
            next.Clear();

            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = true;

                var points = edges[c];
                for (int j = 0, pc = points.Count; j < pc; ++j)
                {
                    var point = points[j];
                    if (!past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        int dia = 0;
        current.Add(end);
        for (var count = 1; count > 0; count = current.Count, ++dia)
        {
            next.Clear();
            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = false;

                var points = edges[c];
                for (int j = 0, pc = points.Count; j < pc; ++j)
                {
                    var point = points[j];
                    if (past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        Console.WriteLine(dia % 3 == 2 ? "Second" : "First");
    }
}

