class Program
    {
        class Node
        {
            public int id;
            public List<Node> link;
            public Node (int id)
            {
                this.id = id;
                link = new List<Node>();
            }
        }
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            Node[] nodes = new Node[n];
            for (int i=0; i<n; i++)
            {
                Node nn = new Node(i);
                nodes[i] = nn;
            }
            for (int i=0; i<n-1; i++)
            {
                string[] s = Console.ReadLine().Split(' ');
                int n1 = int.Parse(s[0]) - 1, n2 = int.Parse(s[1]) - 1;
                nodes[n1].link.Add(nodes[n2]);
                nodes[n2].link.Add(nodes[n1]);
            }
            Queue<Node> queue = new Queue<Node>();
            int[] checkList = new int[n];
            queue.Enqueue(nodes[0]);
            checkList[0] = -1;
            int farNode = -1;
            while(queue.Count > 0)
            {
                Node nn = queue.Dequeue();
                farNode = nn.id;
                foreach (Node nnn in nn.link)
                {
                    if (checkList[nnn.id] == 0)
                    {
                        checkList[nnn.id] = -1;
                        queue.Enqueue(nnn);
                    }
                }
            }
            queue.Enqueue(nodes[farNode]);
            checkList[farNode] = 1;
            while(queue.Count > 0)
            {
                Node nn = queue.Dequeue();
                farNode = nn.id;
                foreach (Node nnn in nn.link)
                {
                    if (checkList[nnn.id] == -1)
                    {
                        checkList[nnn.id] = checkList[nn.id] + 1;
                        queue.Enqueue(nnn);
                    }
                }
            }
            if (checkList[farNode] % 3 == 2) Console.WriteLine("Second");
            else Console.WriteLine("First");


        }
    }
