namespace AtTest.AGC_033
{
    class C
    {
        static void Main(string[] args)
        {
            Method(args);
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            List<int>[] graph = new List<int>[n];
            for (int i = 0; i < n; i++) graph[i] = new List<int>();

            for(int i = 0; i < n-1; i++)
            {
                int[] ab = ReadInts();
                int a = ab[0] - 1;
                int b = ab[1] - 1;

                graph[a].Add(b);
                graph[b].Add(a);
            }
            int length = 0;
            bool[] used = new bool[n];
            for(int i = 0; i < n; i++)
            {
                if (graph[i].Count > 1) continue;

                var queue = new Queue<int[]>();
                queue.Enqueue(new int[2] { i, 1 });
                while (queue.Count > 0)
                {
                    int[] val = queue.Dequeue();

                    used[val[0]] = true;
                    length = Max(length, val[1]);
                    for(int j = 0; j < graph[val[0]].Count; j++)
                    {
                        if (used[graph[val[0]][j]]) continue;

                        queue.Enqueue(new int[2] { graph[val[0]][j], val[1] + 1 });
                    }
                }
                break;
            }

            if ((length - 2) % 3 == 0)
            {
                WriteLine("Second");
            }
            else
            {
                WriteLine("First");
            }
        }

