    class Modulo
    {
        private int M;
        private readonly long[] m_facs;
        public long Mul(long a, long b)
        {
            return ((a * b) % M);
        }
        public Modulo(long n, int m)
        {
            M = m;
            m_facs = new long[n + 1];
            m_facs[0] = 1;
            for (long i = 1; i <= n; ++i)
            {
                m_facs[i] = Mul(m_facs[i - 1], i);
            }
        }
        public long Fac(long n)
        {
            return m_facs[n];
        }
        public long Pow(long a, long m)
        {
            switch (m)
            {
                case 0:
                    return 1L;
                case 1:
                    return a;
                default:
                    long p1 = Pow(a, m / 2);
                    long p2 = Mul(p1, p1);
                    return ((m % 2) == 0) ? p2 : Mul(p2, a);
            }
        }
        public long Div(long a, long b)
        {
            return Mul(a, Pow(b, M - 2));
        }
        public long Ncr(long n, long r)
        {
            if (n < r) { return 0; }
            if (n == r) { return 1; }
            long res = Fac(n);
            res = Div(res, Fac(r));
            res = Div(res, Fac(n - r));
            return res;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Hello
{
    private static IEnumerable<KeyValuePair<int, int>> CreateTuple(int a, int b)
    {
        yield return new KeyValuePair<int, int>(a, b);
        yield return new KeyValuePair<int, int>(b, a);
    }

    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var edges = Enumerable.Range(0, n - 1)
            .Select(_ =>
                    {
                        var line = Console.ReadLine().Split(' ');
                        return new KeyValuePair<int, int>(
                            int.Parse(line[0]),
                            int.Parse(line[1])
                        );
                    }
                   )
            .SelectMany(p => CreateTuple(p.Key, p.Value))
            .GroupBy(kvp => kvp.Key)
            .ToDictionary(g => g.Key, g => g.Select(kvp => kvp.Value).ToArray());

        var past = new bool[n + 1];
        var current = new List<int>(){ 1 };
        var next = new List<int>();
        int end = 0;

        for (int count = 1; count > 0; count = current.Count)
        {
            end = current[0];
            next.Clear();

            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = true;

                var points = edges[c];
                for (int j = 0; j < points.Length; ++j)
                {
                    var point = points[j];
                    if (!past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        int dia = 0;
        current.Add(end);
        for (var count = 1; count > 0; count = current.Count, ++dia)
        {
            next.Clear();
            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = false;

                var points = edges[c];
                for (int j = 0; j < points.Length; ++j)
                {
                    var point = points[j];
                    if (past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        Console.WriteLine(dia % 3 == 2 ? "Second" : "First");
    }
}

