	static T[] ConstantArray<T>(int n, T val) { var a = new T[n]; for (var i = 0; i < n; i++) a[i] = val; return a; }
	static T[] MakeArray<T>(int n, Func<int, T> f) { var a = new T[n]; for (var i = 0; i < n; i++) a[i] = f(i); return a; }
	static ulong One(int k) => 1ul << k;
	static ulong All(int k) => One(k) - 1;
	static bool Has(ulong s, int k) => (s & One(k)) != 0;
	const int MOD = 1000000007;
	public K()
	{
		SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
		Solve();
		Out.Flush();
	}
	int V;
	List<int>[] es;
	void Solve()
	{
		V = F;
		es = MakeArray(V, _ => new List<int>());
		for (var i = 0; i < V - 1; i++)
		{
			var I = G;
			I[0]--; I[1]--;
			es[I[0]].Add(I[1]);
			es[I[1]].Add(I[0]);
		}
		var u = ArgMax(Distance(0));
		var d = Distance(u).Max();
		WriteLine(d % 3 == 1 ? "Second" : "First");
	}
	int ArgMax(int[] a) { int m = int.MinValue, mi = 0; for (var i = 0; i < a.Length; i++) if (m < a[i]) { m = a[i]; mi = i; } return mi; }
	int[] Distance(int r)
	{
		var dist = new int[V];
		var st = new Stack<Tuple<int, int, int>>();
		st.Push(new Tuple<int, int, int>(r, -1, 0));
		while (st.Count > 0)
		{
			var t = st.Pop();
			int u = t.Item1, p = t.Item2, d = t.Item3;
			dist[u] = d;
			foreach (var v in es[u]) if (v != p) st.Push(new Tuple<int, int, int>(v, u, d + 1));
		}
		return dist;
	}
}

