using System;
using System.Collections.Generic;
using System.Linq;

public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var edges = new KeyValuePair<int, int>[n - 1];
        for (int i = 0; i < edges.Length; ++i)
        {
            var line = Console.ReadLine().Split(' ');
            edges[i] = new KeyValuePair<int, int>(
                int.Parse(line[0]),
                int.Parse(line[1])
            );
        }

        var past = new bool[n + 1];
        var current = new List<int>(){ 1 };
        var next = new List<int>();
        int end = 0;

        for (int count = 1; count > 0; count = current.Count)
        {
            end = current[0];
            next.Clear();

            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = true;

                for (int j = 0; j < edges.Length; ++j)
                {
                    var edge = edges[j]; 
                    int point;
                    if (edge.Key == c)
                        point = edge.Value;
                    else if (edge.Value == c)
                        point = edge.Key;
                    else
                        continue;
                    if (!past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        int dia = 0;
        current.Add(end);
        for (var count = 1; count > 0; count = current.Count, ++dia)
        {
            next.Clear();
            for (int i = 0; i < count; ++i)
            {
                var c = current[i];
                past[c] = false;

                for (int j = 0; j < edges.Length; ++j)
                {
                    var edge = edges[j];
                    int point;
                    if (edge.Key == c)
                        point = edge.Value;
                    else if (edge.Value == c)
                        point = edge.Key;
                    else
                        continue;
                    if (past[point])
                        next.Add(point);
                }
            }

            var tmp = current;
            current = next;
            next = tmp;
        }

        Console.WriteLine(dia % 3 == 2 ? "Second" : "First");
    }
}

