class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;

    int N;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();

        N = cin.nextInt();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }
        int start = getPos(0);
        int dist;
        getPos(start);
        dist = d;

        if (dist % 3 == 1) Console.WriteLine("Second");
        else Console.WriteLine("First");
    }

    int d;
    int getPos(int a)
    {
        Queue<int> q = new Queue<int>();
        int[] dist = new int[N];
        int MAX = 9999999;
        for (int i = 0; i < N; i++)
        {
            dist[i] = MAX;
        }
        q.Enqueue(a);
        dist[a] = 0;
        int last = 0;
        while(q.Count != 0)
        {
            int now = q.Dequeue();
            last = now;
            foreach (var next in es[now])
            {
                if (dist[next] != MAX) continue;
                dist[next] = dist[now] + 1;
                q.Enqueue(next);
            }
        }
        d = dist[last];
        return last;
    }
}




class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
