class Program
{
    static void Main(string[] args)
    {
        Solve();
        //WriteLine(Solve());
    }
    static int num;
    static List<int>[] adj;
    static void Solve()
    {
        num = Input.num;
        adj = Enumerable.Repeat(0, num).Select(_ => new List<int>()).ToArray();
        for(var i = 0; i < num - 1; i++)
        {
            var ab = Input.ar;
            adj[ab[0] - 1].Add(ab[1] - 1);
            adj[ab[1] - 1].Add(ab[0] - 1);
        }
        var dist = Enumerable.Repeat(num, num).ToArray();
        bfs(dist, 0);
        var max = 0;
        var maxj = 0;
        for(var i=1;i<num;i++)
            if (dist[i] > max) { max = dist[i];maxj = i; }
        dist = Enumerable.Repeat(num, num).ToArray();
        bfs(dist, maxj);
        var m = dist.Max();
        WriteLine(m % 3 == 1 ? "Second" : "First");
    }
    static void bfs(int[] dist,int init)
    {
        dist[init] = 0;
        var que = new Queue<int>();
        que.Enqueue(init);
        while (que.Count != 0)
        {
            var p = que.Dequeue();
            foreach (var ad in adj[p])
            {
                if (dist[ad] != num) continue;
                dist[ad] = dist[p] + 1;
                que.Enqueue(ad);
            }
        }
    }
}

