            for (int i = 1; i <= N; i++)
            {
                if (dist1[i] > dist1[maxIndex]) maxIndex = i;
            }

            int[] dist2 = new int[N + 1];
            memo = new HashSet<int>();
            q.Enqueue(maxIndex);
