        {
            int now = Q.Dequeue();
            nodes[now].visit = true;
            foreach (var nx in nodes[now].relate)
            {
                if (!nodes[nx.to].visit)
                {
                    nodes[nx.to].cost = nodes[now].cost + 1;
                    Diameter = Math.Max(Diameter, nodes[nx.to].cost);
                    Q.Enqueue(nx.to);
                }
            }
        }

        //[直径] = T -> 先手の勝ち
        bool[] ans = new bool[N + 1];
        ans[0] = true;
        ans[1] = true;
        //端を取ると直径が1減る、中をとると直径が2減る
        //自分の勝利✋にしかつなげられない場合は後攻が勝つ
        for (int i = 2; i <= N; i++)
            ans[i] = (ans[i - 1] && ans[i - 2] ? false : true);
        Console.WriteLine((ans[Diameter] ? "First" : "Second"));
    }
}

