    class Solver
    {
        private int N;
        List<int> A;
        List<int> B;

        public void Solve()
        {
            Cin(out N);
            Cin(N - 1, out A, out B);

            Dictionary<int, HashSet<int>> neighbor = new Dictionary<int, HashSet<int>>();
            Dictionary<int, HashSet<int>> neighbor2 = new Dictionary<int, HashSet<int>>();
            for (int i = 0; i < N + 1; i++)
            {
                neighbor.Add(i, new HashSet<int>());
                neighbor2.Add(i, new HashSet<int>());
            }

            for (int i = 0; i < N - 1; i++)
            {
                neighbor[A[i]].Add(B[i]);
                neighbor[B[i]].Add(A[i]);
                neighbor2[A[i]].Add(B[i]);
                neighbor2[B[i]].Add(A[i]);
            }

            HashSet<int> memo = new HashSet<int>();
            int[] dist1 = new int[N + 1];
            Queue<int> q = new Queue<int>();
            q.Enqueue(1);
            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (var a in neighbor[c])
                {
                    if (memo.Contains(a)) continue;
                    memo.Add(a);
                    neighbor[a].Remove(c);
                    dist1[a] = dist1[c] + 1;
                    q.Enqueue(a);
                }
            }

            int maxIndex = 0;
            for (int i = 1; i <= N; i++)
            {
                if (dist1[i] > dist1[maxIndex]) maxIndex = i;
            }

            int[] dist2 = new int[N + 1];
            memo = new HashSet<int>();
            q.Enqueue(maxIndex);
            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (var a in neighbor2[c])
                {
                    if (memo.Contains(a)) continue;
                    memo.Add(a);
                    neighbor2[a].Remove(c);
                    dist2[a] = dist2[c] + 1;
                    q.Enqueue(a);
                }
            }

            Console.WriteLine((dist2.Max() + 1) % 3 == 2 ? "Second" : "First");
        }
    }
}

