class Tree
{
    public List<int>[] Input(int n, int indexed = 1)
    {
        Scanner cin = new Scanner();
        var ret = new List<int>[n];
        for (int i = 0; i < ret.Length; i++) ret[i] = new List<int>();
        for (int i = 0; i < n - 1; i++)
        {
            int a = cin.nextint - indexed;
            int b = cin.nextint - indexed;
            ret[a].Add(b);
            ret[b].Add(a);
        }
        return ret;
    }
    public int BFS(List<int>[] T, int s, out int[] dist)
    {
        int n = T.Length;
        dist = new int[n];
        for (int i = 0; i < dist.Length; i++) dist[i] = -1;
        var Q = new Queue<int>();
        dist[s] = 0;
        Q.Enqueue(s);
        int len = 0, id = s;

        while (Q.Count > 0)
        {
            var u = Q.Dequeue();
            foreach (var v in T[u])
            {
                if (dist[v] >= 0) continue;
                dist[v] = dist[u] + 1;
                if (len < dist[v])
                {
                    len = dist[v];
                    id = v;
                }
                Q.Enqueue(v);
            }
        }

        return id;
    }
    public int Diameter(List<int>[] T)
    {
        int[] dist;
        var far = BFS(T, BFS(T, 0, out dist), out dist);
        return dist[far];
    }
}

