  if (ans1 === undefined) return (ans2 + 1) % 2;
  if (ans1 !== ans2) {
    return 1;
  } else {
    return (ans1 + 1) % 2;
  }
}

function removeLeafs(old) {
  var leaves = [];
  for (var i = 0; i < old.length; i++) {
    if (old[i] && old[i].length === 1) {
      leaves.push(i)
    }
  }

  // console.log({leaves});
  var newTree = [];
  old.forEach((v, i) => {
    // console.log("forEach", v);
    if (v && v.length > 1) {
      newTree[i] = v.filter(x => leaves.indexOf(x) < 0);
    }
  })

  return newTree;
}

