	"os"
)

type pair struct {
	a int
	b int
}

func answer(reader io.Reader, writer io.Writer) {
	var n int
	_, _ = fmt.Fscan(reader, &n)
	v := make([]pair, n)
	e := map[int]map[int]bool{}
	for i := 0; i < n; i++ {
		e[i] = map[int]bool{}
	}
	for i := 0; i < n-1; i++ {
		_, _ = fmt.Fscan(reader, &v[i].a)
		_, _ = fmt.Fscan(reader, &v[i].b)
		//fmt.Printf("%v, %v\n", v[i].a, v[i].b)
		e[v[i].a-1][v[i].b-1] = true
		e[v[i].b-1][v[i].a-1] = true
	}
	max := 0
	for i := 0; i < n; i++ {
		s := map[int]bool{}
		d := map[int]bool{}
		s[i] = true
		c := 0
		for true {
			f := false
			for j := range s {
				delete(s, j)
				d[j] = true
				for k := range e[j] {
					_, ok := d[k]
					_, ok2 := s[k]
					if ok == false && ok2 == false {
						s[k] = true
						f = true
					}
				}
			}
			if f == false {
				if max < c {
					max = c
				}
				break
			}
			c++
		}
	}
	//fmt.Printf("max:%v\n", max)
	if max%3 == 1 {
		_, _ = fmt.Fprintf(writer, "Second")

	} else {
		_, _ = fmt.Fprintf(writer, "First")

	}
}

