var sc *bufio.Scanner

const BufferSize = 1024

func nextInt() int {
	if !sc.Scan() {
		panic(nil)
	}
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

var production bool

func debugf(format string, v ...interface{}) {
	if !production {
		fmt.Printf(format, v...)
	}
}

func bfs(e [][]int, s int) int {
	set := map[int]struct{}{s: {}}
	visited := map[int]struct{}{s: {}}
	last := s
	for len(set) > 0 {
		for i := range set {
			delete(set, i)
			visited[i] = struct{}{}
			last = i
			debugf("bfs: %v\n", i)

			for _, j := range e[i] {
				if _, ok := visited[j]; !ok {
					set[j] = struct{}{}
				}
			}
		}
	}
	return last
}

func radius(e [][]int) int {
	farthest := bfs(e, 0)
	debugf("farthest: %v\n", farthest)

	set := map[int]struct{}{farthest: {}}
	visited := map[int]struct{}{farthest: {}}
	count := 0
	for len(set) > 0 {
		count++
		for i := range set {
			delete(set, i)
			visited[i] = struct{}{}

			for _, j := range e[i] {
				if _, ok := visited[j]; !ok {
					set[j] = struct{}{}
				}
			}
		}
	}
	return count

}

func answer(reader io.Reader, writer io.Writer) {
	sc = bufio.NewScanner(reader)
	buf := make([]byte, BufferSize)
	sc.Buffer(buf, 1e+6)
	sc.Split(bufio.ScanWords)
	n := nextInt()
	e := make([][]int, n)

	for i := 0; i < n-1; i++ {
		u := nextInt()
		v := nextInt()
		e[u-1] = append(e[u-1], v-1)
		e[v-1] = append(e[v-1], u-1)
	}
	debugf("e: %v\n", e)

	ans := radius(e)
	debugf("radius: %v\n", ans)

	if (ans-1)%3 != 1 {
		_, _ = fmt.Fprint(writer, "First")
	} else {
		_, _ = fmt.Fprint(writer, "Second")
	}
}

func main() {
	production = true
	answer(os.Stdin, os.Stdout)
}

