package main

import (
  "bufio"
  "os"
  "strings"
  "strconv"
  "fmt"
)

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextInt() int {
  var n int
  n, _ = strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}

func dijkstra(E *[][]int, s int) (D []int) {
  N := len((*E))
  D = make([]int, N)
  for i := 0; i < N; i++ {
    if i != s {
      D[i] = -1
    }
  }
  Q := make([]int, N)
  Q[0] = s
  var v int
  pos := 1
  for i := 0; i < N; i++ {
    v = Q[i]
    for _, adj := range (*E)[v] {
      if D[adj] >= 0 {
        continue
      }
      D[adj] = D[v] + 1
      Q[pos] = adj
      pos += 1
    }
  }
  return
}

func max(A *[]int) (i, a int) {
  i = 0
  a = (*A)[0]
  for _i, _a := range (*A) {
    if _a > a {
      a = _a
      i = _i
    }
  }
  return
}

func main() {
  var N int
  N = NextInt()
  E := make([][]int, N)
  for i := range E {
    E[i] = make([]int, 0)
  }
  var a, b int
  for i := 0; i < N - 1; i++ {
    ab := NextIntVec()
    a = ab[0]
    b = ab[1]
    E[a - 1] = append(E[a - 1], b - 1)
    E[b - 1] = append(E[b - 1], a - 1)
  }
  D0 := dijkstra(&E, 0)
  s, _ := max(&D0)
  D1 := dijkstra(&E, s)
  _, L := max(&D1)
  if L % 3 != 1 {
    fmt.Println("First")
  } else {
    fmt.Println("Second")
  }
}

