type Edge struct {
	to, cost int
}

var (
	n int

	G   [100000 + 50][]Edge
	dp  [100000 + 50]int
	ans [100000 + 50]int
)

func rdfs(cid, pid int, dpar int) {
	V := []int{}
	for _, e := range G[cid] {
		if e.to == pid {
			V = append(V, dpar+e.cost)
			dpar += e.cost // 都合上ここで更新する
			continue
		}
		V = append(V, dp[e.to]+e.cost)
	}
	sort.Sort(sort.Reverse(sort.IntSlice(V)))
	if len(V) == 1 {
		ans[cid] = V[0]
	} else {
		ans[cid] = V[0] + V[1]
	}

	cdp := []int{0}
	nexts := []int{-1}
	for _, e := range G[cid] {
		if e.to == pid {
			continue
		}
		cdp = append(cdp, dp[e.to]+e.cost)
		nexts = append(nexts, e.to)
	}
	cdp = append(cdp, 0)
	nexts = append(nexts, -1)

	N := len(cdp)
	L, R := make([]int, N), make([]int, N)
	L[0], R[0], L[N-1], R[N-1] = 0, 0, 0, 0
	for i := 1; i <= N-2; i++ {
		L[i] = Max(L[i-1], cdp[i])
	}
	for i := N - 2; i >= 1; i-- {
		R[i] = Max(R[i+1], cdp[i])
	}

