// pidからcidに遷移したときの、cidからの最遠ノードを返す
// pid: 直前の遷移元ノードID, cid: 現在観ているノードID
func visit(pid, cid int) Result {
	r := Result{dist: 0, nid: cid}
	// DFS
	for _, e := range edges[cid] {
		if e.nid != pid {
			t := visit(cid, e.nid) // 次の遷移先へ
			t.dist += e.weight
			if r.dist < t.dist {
				r = t
			}
		}
	}
	return r
}

