const (
	// General purpose
	MOD = 1000000000 + 7
	// MOD          = 998244353
	ALPHABET_NUM = 26
	INF_INT64    = math.MaxInt64
	INF_BIT60    = 1 << 60
	INF_INT32    = math.MaxInt32
	INF_BIT30    = 1 << 30
	NIL          = -1

	// for dijkstra, prim, and so on
	WHITE = 0
	GRAY  = 1
	BLACK = 2
)

func init() {
	// bufio.ScanWords <---> bufio.ScanLines
	ReadString = newReadString(os.Stdin, bufio.ScanWords)
	stdout = bufio.NewWriter(os.Stdout)
}

func main() {
	n = ReadInt()
	for i := 0; i < n-1; i++ {
		a, b := ReadInt2()
		a--
		b--

		G[a] = append(G[a], Edge{to: b, cost: 1})
		G[b] = append(G[b], Edge{to: a, cost: 1})
	}

	if n == 1 {
		fmt.Println("First")
		return
	}

	dfs(0, -1)
	rdfs(0, -1, 0)
	res := 0
	for i := 0; i < n; i++ {
		res = Max(res, ans[i])
	}

	if res%3 == 1 {
		fmt.Println("Second")
	} else {
		fmt.Println("First")
	}
}

type Edge struct {
	to, cost int
}

var (
	n int

	G   [100000 + 50][]Edge
	dp  [100000 + 50]int
	ans [100000 + 50]int
)

func rdfs(cid, pid int, dpar int) {
	V := []int{}
	for _, e := range G[cid] {
		if e.to == pid {
			V = append(V, dpar+e.cost)
			dpar += e.cost // 都合上ここで更新する
			continue
		}
		V = append(V, dp[e.to]+e.cost)
	}
	sort.Sort(sort.Reverse(sort.IntSlice(V)))
	if len(V) == 1 {
		ans[cid] = V[0]
	} else {
		ans[cid] = V[0] + V[1]
	}

	cdp := []int{0}
	nexts := []int{-1}
	for _, e := range G[cid] {
		if e.to == pid {
			continue
		}
		cdp = append(cdp, dp[e.to]+e.cost)
		nexts = append(nexts, e.to)
	}
	cdp = append(cdp, 0)
	nexts = append(nexts, -1)

	N := len(cdp)
	L, R := make([]int, N), make([]int, N)
	L[0], R[0], L[N-1], R[N-1] = 0, 0, 0, 0
	for i := 1; i <= N-2; i++ {
		L[i] = Max(L[i-1], cdp[i])
	}
	for i := N - 2; i >= 1; i-- {
		R[i] = Max(R[i+1], cdp[i])
	}

	for i := 1; i <= N-2; i++ {
		ndpar := Max(dpar, L[i-1], R[i+1])
		rdfs(nexts[i], cid, ndpar)
	}
}

func dfs(cid, pid int) {
	res := 0
	for _, e := range G[cid] {
		if e.to == pid {
			continue
		}

		dfs(e.to, cid)
		res = Max(res, dp[e.to]+e.cost)
	}
	dp[cid] = res
}

