		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
	writer.Flush()
}

func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	if n == 1 {
		fmt.Fprintln(writer, "First")
		return
	}
	ee := make([][]edge, n)
	for i := 0; i < n-1; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		appendEdge(a, b, i, ee)
		appendEdge(b, a, i, ee)
	}
	dd := make([]int, n)
	dfs(0, -1, 0, dd, ee)
	win := make([]bool, n+1)
	win[1] = true
	for i := 3; i < n+1; i++ {
		win[i] = !(win[i-1] && win[i-2])
	}
	if win[dd[0]+1] {
		fmt.Fprintln(writer, "First")
		return
	}
	fmt.Fprintln(writer, "Second")
}

func dfs(c, p, d int, dd []int, ee [][]edge) int {
	dd[c] = d
	hh := make([]int, 2)
	hh[0] = d
	hh[1] = d
	for _, e := range ee[c] {
		if e.to == p {
			continue
		}
		h := dfs(e.to, c, d+1, dd, ee)
		for i := 0; i < 2; i++ {
			if hh[i] < h {
				hh[i] = h
				if hh[0] > hh[1] {
					hh[0], hh[1] = hh[1], hh[0]
				}
				break
			}
		}
	}
	dd[c] = hh[0] + hh[1] - d<<1
	return hh[1]
}

