type UnWeightedUnDirectedTree struct {
	g [][]int
}

func NewUnWeightedUnDirectedTree(s int) *UnWeightedUnDirectedTree {
	return &UnWeightedUnDirectedTree{
		g: make([][]int, s),
	}
}

func (tr *UnWeightedUnDirectedTree) AddEdge(u, v int) {
	tr.g[u] = append(tr.g[u], v)
	tr.g[v] = append(tr.g[v], u)
}

func (tr *UnWeightedUnDirectedTree) DFS(r int) []int {
	n := len(tr.g)
	ds := make([]int, n)
	var dfs func(int, int, int)
	dfs = func(c, p, d int) {
		ds[c] = d
		for _, nx := range tr.g[c] {
			if nx == p {
				continue
			}
			dfs(nx, c, d+1)
		}
	}
	dfs(r, -1, 0)
	return ds
}

func (tr *UnWeightedUnDirectedTree) Diameter() int {
	ds := tr.DFS(0)
	u := -1
	mds := -1
	for i, d := range ds {
		if d > mds {
			mds = d
			u = i
		}
	}
	du := tr.DFS(u)
	v := -1
	mdu := -1
	for i, d := range du {
		if d > mdu {
			mdu = d
			v = i
		}
	}
	return du[v]
}

