func dfs(c, p, d int, dd []int, ee [][]edge) int {
	dd[c] = d
	ch := &choku{}
	heap.Init(ch)
	heap.Push(ch, d)
	heap.Push(ch, d)
	for _, e := range ee[c] {
		if e.to == p {
			continue
		}
		h := dfs(e.to, c, d+1, dd, ee)
		heap.Push(ch, h)
		heap.Pop(ch)
	}
	h0 := heap.Pop(ch).(int)
	h1 := heap.Pop(ch).(int)
	dd[c] = h0 + h1 - d<<1
	return h1
}

type choku []int

func (h choku) Len() int           { return len(h) }
func (h choku) Less(i, j int) bool { return h[i] < h[j] }
func (h choku) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *choku) Push(x interface{}) {
	*h = append(*h, x.(int))
}
func (h *choku) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

