func dijkstra(E *[][]int, s int) (D []int) {
  N := len((*E))
  D = make([]int, N)
  for i := 0; i < N; i++ {
    if i != s {
      D[i] = -1
    }
  }
  Q := []int{s}
  var v int
  for i := 0; i < N; i++ {
    v = Q[i]
    for _, adj := range (*E)[v] {
      if D[adj] >= 0 {
        continue
      }
      D[adj] = D[v] + 1
      Q = append(Q, adj)
    }
  }
  return
}

func max(A *[]int) (i, a int) {
  i = 0
  a = (*A)[0]
  for _i, _a := range (*A) {
    if _a > a {
      a = _a
      i = _i
    }
  }
  return
}

