/*

「葉をすべて削除」
「指定した1つの葉以外のすべての葉を削除」
という行動ができる。

直径がどう変わるか？
・直径は1減る（直径に寄与している葉を指定したとき）
・直径は2減る（その他を指定したとき）

※直径が1のときは直径に寄与している葉しかないので後手勝ち

直径が0のときは先手勝ち

ニムをする。(直径-1)を0にしたらよいゲーム。
(直径-1)を3で割った余りに注目し、余りが0なら後手勝ち。それ以外は先手勝ち。

*/

class Node{
	long id;
	int dp, dq, d;
	bool isVisited;
	Node[] nodes;
	this(long id){
		this.id = id;
	}
	Node furthest(){ // O(n) // isVisitedをクリアしてから呼ぶこと
		Node res = this;
		Node[] q = [this];
		int iq = 0;
		this.isVisited = 1;
		while(iq < q.length){
			foreach(nd; q[iq].nodes) if(! nd.isVisited) nd.isVisited = 1, q ~= nd;
			iq ++;
		}
		return q[$ - 1];
	}
	void setp(int d){
		this.isVisited = 1;
		this.dp = d;
		foreach(nd; nodes) if(! nd.isVisited) nd.setp(d + 1);
	}
	void setq(int d){
		this.isVisited = 1;
		this.dq = d;
		foreach(nd; nodes) if(! nd.isVisited) nd.setq(d + 1);
	}

	override string toString(){
		return id.to!string ~ "(" ~ dp.to!string ~ " " ~ dq.to!string ~ " " ~ d.to!string ~ ")" ~ nodes.map!(x => x.id.to!string).join(" ");
	}
}

