def first_win(n, tree):
    res = [False, True,False,True,True,False]
    for i in range(6,n):
        res.append(not res[-2] or not res[-1])

    cnt_leaf = 0
    leafs = []
    for i in range(n):
        if len(tree[i]) == 1:
            cnt_leaf += 1
            leafs.append(i)
    return res[n-cnt_leaf] or res[n-cnt_leaf+1]








