N = ini()
adj = [[] for _ in range(N)]

for i in range(N - 1):
    a, b = [x - 1 for x in inm()]
    adj[a].append(b)
    adj[b].append(a)

depth = [(0, 0) for _ in range(N)]


def solve():
    def gather(node, p):
        md1, md2 = 0, 0
        for x in adj[node]:
            if x != p:
                dx = gather(x, node)
                if md1 < dx:
                    md2 = md1
                    md1 = dx
                elif md2 < dx:
                    md2 = dx
        depth[node] = (md1, md2)
        return 1 + md1

    gather(0, -1)

    def distribute(node, p):
        d1, d2 = depth[node]
        if p >= 0:
            pd1, pd2 = depth[p]
            if pd1 == 1 + d1:
                pd1 = pd2
            if d2 < pd1 + 1:
                d2 = pd1 + 1
        max_len = d1 + d2 + 1
        for x in adj[node]:
            if x != p:
                l = distribute(x, node)
                if max_len < l:
                    max_len = l
        return max_len

    max_len = distribute(0, -1)
    if max_len == 1:
        return True
    if max_len == 2:
        return False
    return (max_len + 1) % 3 != 0


print("First" if solve() else "Second")

