        }
    }

    fn dfs(&mut self, u: usize) -> (usize, usize) {
        self.done[u] = true;

        let mut D = 0;
        let mut W = u;

        for i in 0..self.G[u].len() {
            let v = self.G[u][i];
            if self.done[v] {
                continue;
            }

            let (w, d) = self.dfs(v);
            if D < d + 1 {
                D = d + 1;
                W = w;
            }
        }

        (W, D)
    }

    fn solve(mut self) {
        let (u, _) = self.dfs(0);
        self.reset();
        let (v, d) = self.dfs(u);
        debug!(u, v, d);

        println!("{}", if d % 3 != 1 { "First" } else { "Second" })
    }
}

fn main() {
    let N = read!(usize);
    let T = read![usize, usize; N - 1];

    let mut G = vec![vec![]; N];
    for (u, v) in T {
        G[u - 1].push(v - 1);
        G[v - 1].push(u - 1);
    }

    Solver {
        N: N,
        G: G,
        done: vec![false; N],
    }
    .solve()
}

