fn toi(s:usize, edges: &Vec<Vec<usize>>) -> (usize, usize){
  let mut q = vec![];
  let mut dep = vec![-1; edges.len()];
  q.push(s);
  dep[s] = 0;
  while !q.is_empty() {
    let c = q.pop().unwrap();
    for k in 0..edges[c].len() {
      let e = edges[c][k];
      if dep[e] == -1 {
        q.push(e);
        dep[e] = dep[c] + 1;
      }
    }
  }
  //debug!(dep);
  let mut dis = 0;
  let mut v = 0;
  for i in 0..edges.len() {
    if dis < dep[i] {
      dis = dep[i];
      v = i;
    }
  }
  return (v, dis as usize);
}

fn main() {
  input! {
    n: usize,
    ab: [(usize1, usize1); n-1]
  }
  let mut edges = vec![vec![]; n];
  for (x, y) in ab {
    edges[x].push(y);
    edges[y].push(x);
  }
  //debug!(edges);
  let (v, _) = toi(0, &edges);
  let (_, d) = toi(v, &edges);
  //debug!(d);
  if d % 3 == 1 {
    println!("Second");
  } else {
    println!("First");
  }
}

use std::collections::VecDeque;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    // 葉を選んだとき => 選んだ葉以外の葉をむしる
    // 葉以外を選んだとき => 葉を全てむしる

    // 直径の端点 => 直径を1減らす
    // その他の点 => 直径を2減らす

    // 0=>first
    // 1=>second
    // 2=>first
    // 3

    let n = sc.read();
    if n == 1 {
        println!("First");
        return;
    }
    if n == 2 {
        println!("Second");
        return;
    }
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut dist = vec![n; n];
    let mut q = VecDeque::new();
    q.push_back(0);
    dist[0] = 0;

    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if dist[next] > dist[v] + 1 {
                dist[next] = dist[v] + 1;
                q.push_back(next);
            }
        }
    }
    let (_, d1) = dist
        .into_iter()
        .enumerate()
        .map(|(i, d)| (d, i))
        .max()
        .unwrap();

    let mut dist = vec![n; n];
    q.push_back(d1);
    dist[d1] = 0;
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if dist[next] > dist[v] + 1 {
                dist[next] = dist[v] + 1;
                q.push_back(next);
            }
        }
    }

    let (dist, _) = dist
        .into_iter()
        .enumerate()
        .map(|(i, d)| (d, i))
        .max()
        .unwrap();

    let inf = n * 10;
    let mut grundy = vec![inf; dist + 1];
    grundy[0] = 1;
    grundy[1] = 0;
    grundy[2] = 1;
    for i in 3..(dist + 1) {
        let mut next = vec![];
        next.push(grundy[i - 1]);
        next.push(grundy[i - 2]);
        grundy[i] = (0..).find(|i| !next.contains(i)).unwrap();
    }
    if grundy[dist] == 0 {
        println!("Second");
    } else {
        println!("First");
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        parse!(it, a: usize, b: usize);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let mut a = 0;
    let mut l = 0;
    let mut stack = vec![(0, 0)];
    let mut seen = vec![false; n];
    while let Some((v, d)) = stack.pop() {
        for &u in g[v].iter() {
            if !seen[u] {
                seen[u] = true;
                if d + 1 > l {
                    a = u;
                    l = d + 1;
                }
                stack.push((u, d + 1));
            }
        }
    }
    let a = a;
    let mut l = 0;
    let mut stack = vec![(a, 0)];
    let mut seen = vec![false; n];
    while let Some((v, d)) = stack.pop() {
        for &u in g[v].iter() {
            if !seen[u] {
                seen[u] = true;
                if d + 1 > l {
                    l = d + 1;
                }
                stack.push((u, d + 1));
            }
        }
    }
    if a % 3 == 1 {
        println!("Second");
    } else {
        println!("First"); // DEBUG
    }
}

