fn dfs(v: usize, p: usize, g: &Vec<Vec<usize>>) -> (usize, usize) {
    let mut res = (0, v);
    for &dst in &g[v] {
        if dst != p {
            let mut r = dfs(dst, v, g);
            r.0 += 1;
            res.set_max(r);
        }
    }
    res
}
fn run() {
    input! {
        n: usize,
        edges: [(usize1, usize1); n-1],
    }
    let mut graph = vec![Vec::new(); n];
    for (u, v) in edges {
        graph[u].push(v);
        graph[v].push(u);
    }
    let r = dfs(0, usize::max_value(), &graph);
    let (len, _) = dfs(r.1, usize::max_value(), &graph);
    if len % 3 != 2 {
        println!("Second");
    } else {
        println!("First");
    }
}

