fn main() {
    input! {
        n: usize,
        es: [(usize1, usize1); n-1],
    }

    let mut g = vec![vec![]; n];

    for &(u, v) in es.iter() {
        g[u].push(v);
        g[v].push(u);
    }

    let (p, _) = far(&g, 0);
    let (_q, r) = far(&g, p);

    // dbg!(r);

    let ans = if r > 0 && r % 3 != 1 {
        "First"
    } else {
        "Second"
    };

    println!("{}", ans);
}

fn far(g: &Vec<Vec<usize>>, s: usize) -> (usize, usize) {
    let n = g.len();
    let mut dist = vec![None; n];
    let mut q = std::collections::VecDeque::new();

    q.push_back((s, 0));

    while let Some((u, dep)) = q.pop_back() {
        if dist[u].is_some() {
            continue;
        }

        dist[u] = Some(dep);

        for &v in g[u].iter() {
            if dist[v].is_some() {
                continue;
            }
            q.push_back((v, dep + 1));
        }
    }

    // dbg!(&dist);

    let mut ret = (0, 0);
    for i in 0..n {
        if let Some(d) = dist[i] {
            if d > ret.1 {
                ret = (i, d);
            }
        }
    }

    ret
}

