fn diameter(g: Graph) -> usize {
    let (best_leaf, _) = dfs(&g, 0, g.len());
    let (_, diameter) = dfs(&g, best_leaf, g.len());
    diameter
}

fn dfs(g: &Graph, v: V, p: V) -> (V, usize) {
    let mut best_depth = 0;
    let mut best_leaf = v;
    for &t in &g[v] {
        if t == p {
            continue;
        }
        let (l, d) = dfs(g, t, v);
        if best_depth < d+1 {
            best_depth = d+1;
            best_leaf = l;
        }
    }
    (best_leaf, best_depth)
}

