    }

    // 木の直径(diameter)を求める
    let ret = dfs(0, n, &edges, 0);
    let n1 = ret.1;
    let ret = dfs(n1, n, &edges, 0);
    let n2 = ret.1;
    let diameter = distance(n1, n2, n, &edges, 1).unwrap();

    if diameter%3 == 2 {
        println!("Second");
    } else {
        println!("First");
    }
}

