    let mut best_leaf = v;
    for &t in &g[v] {
        if t == p {
            continue;
        }
        let (l, d) = dfs(g, t, v);
        if best_depth < d+1 {
            best_depth = d+1;
            best_leaf = l;
        }
    }
    (best_leaf, best_depth)
}

