use std::collections::{BTreeSet, BTreeMap};
use std::cmp::max;

fn main() {
    input!{
        n: usize,
        v: [(usize1, usize1); n - 1]
    }
    let d = tree_diameter(&v);
    println!("{}", if d % 3 == 1 {"Second"} else {"First"});
}

fn tree_diameter(es: &Vec<(usize, usize)>) -> usize {
    let n = es.len() + 1;
    let mut t: Vec<BTreeSet<usize>> = vec![BTreeSet::new(); n];
    for (a, b) in es.iter().cloned() {
        t[a].insert(b);
        t[b].insert(a);
    }
    let mut tab: BTreeMap<(usize, usize), usize> = BTreeMap::new();
    let mut d = 0;
    for i in 0..n {
        d = max(d, dfs(i, i, &t, &mut tab));
    }
    d - 1
}

fn dfs(r: usize, p: usize, t: &Vec<BTreeSet<usize>>, tab: &mut BTreeMap<(usize, usize), usize>) -> usize {
    if let Some(&x) = tab.get(&(r, p)) {
        return x;
    }
    let mut tmp = 0;
    for &c in t[r].iter() {
        if c == p {
            continue;
        }
        tmp = max(tmp, dfs(c, r, &t, tab));
    }
    tmp += 1;
    tab.insert((r, p), tmp);
    tmp
}

use std::collections::VecDeque;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let (_, v) = bfs(0, &graph);
    let (dist, _) = bfs(v, &graph);
    if dist == 0 {
        println!("First");
        return;
    }

    let mut grundy = vec![0; dist + 1];
    grundy[0] = 1;
    grundy[1] = 0;
    for i in 2..(dist + 1) {
        let next = [grundy[i - 1], grundy[i - 2]];
        grundy[i] = (0..).find(|i| !next.contains(i)).unwrap();
    }
    println!("{}", if grundy[dist] == 0 { "Second" } else { "First" });
}

fn bfs(start: usize, graph: &Vec<Vec<usize>>) -> (usize, usize) {
    let n = graph.len();
    let mut dist = vec![n; n];
    dist[start] = 0;
    let mut q = VecDeque::new();
    q.push_back(start);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if dist[next] > dist[v] + 1 {
                dist[next] = dist[v] + 1;
                q.push_back(next);
            }
        }
    }
    dist.into_iter()
        .enumerate()
        .map(|(i, d)| (d, i))
        .max()
        .unwrap()
}

