fn dfs(i: usize, prev: usize, edges: &Vec<Vec<usize>>, d: usize) -> (usize, usize) {
    let mut ret = (d, i);
    for &next in edges[i].iter() {
        if next != prev {
            let next_ret = dfs(next, i, edges, d+1);
            if next_ret.0 > d {
                ret = next_ret
            }
        }
    }
    ret
}

fn distance(n1: usize, n2: usize, prev: usize, edges: &Vec<Vec<usize>>, d: usize) -> Option<usize> {
    if n1 == n2 {
        return Some(d)
    }
    for &next in edges[n1].iter() {
        if next != prev {
            if let Some(dia) = distance(next, n2, n1, edges, d+1) {
                return Some(dia)
            }
        }
    }
    None
}

