fn toi(s:usize, edges: &Vec<Vec<usize>>) -> (usize, usize){
  let mut q = vec![];
  let mut dep = vec![-1; edges.len()];
  q.push(s);
  dep[s] = 0;
  while !q.is_empty() {
    let c = q.pop().unwrap();
    for k in 0..edges[c].len() {
      let e = edges[c][k];
      if dep[e] == -1 {
        q.push(e);
        dep[e] = dep[c] + 1;
      }
    }
  }
  debug!(dep);
  let mut dis = 0;
  let mut v = 0;
  for i in 0..edges.len() {
    if dis < dep[i] {
      dis = dep[i];
      v = i;
    }
  }
  return (v, dis as usize);
}

