fn get_diameter(nodes: &Vec<Vec<usize>>) -> u32 {
    let (s, _dist_s) = get_fathrest(0, nodes);
    let (_t, dist_t) = get_fathrest(s, nodes);
    return dist_t;
}

fn get_fathrest(v: usize, nodes: &Vec<Vec<usize>>) -> (usize, u32) {
    let mut queue: VecDeque<usize> = VecDeque::new();
    let mut visited = vec![0u32; nodes.len()];
    let mut distance = vec![0u32; nodes.len()];
    let mut last_node = v;

    visited[v] = 1;
    queue.push_back(v);

    while let Some(s) = queue.pop_front() {
        last_node = s;
        for t in &nodes[s] {
            if visited[*t] != 0 {
                continue;
            }
            visited[*t] = 1;
            distance[*t] = distance[s] + 1;
            queue.push_back(*t);
        }
    }
    return (last_node, distance[last_node]);
}

