macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        parse!(it, a: usize, b: usize);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let mut a = 0;
    let mut l = 0;
    let mut stack = vec![(0, 0)];
    let mut seen = vec![false; n];
    while let Some((v, d)) = stack.pop() {
        for &u in g[v].iter() {
            if !seen[u] {
                seen[u] = true;
                if d + 1 > l {
                    a = u;
                    l = d + 1;
                }
                stack.push((u, d + 1));
            }
        }
    }
    let a = a;
    let mut l = 0;
    let mut stack = vec![(a, 0)];
    let mut seen = vec![false; n];
    while let Some((v, d)) = stack.pop() {
        for &u in g[v].iter() {
            if !seen[u] {
                seen[u] = true;
                if d + 1 > l {
                    l = d + 1;
                }
                stack.push((u, d + 1));
            }
        }
    }
    if l % 3 == 1 {
        println!("Second");
    } else {
        println!("First"); // DEBUG
    }
}

