use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        es: [(usize1,usize1); n-1],
    }
    let mut graph = vec![vec![]; n];
    for &(s, t) in &es {
        graph[s].push(t);
        graph[t].push(s);
    }
    let mut v1 = 0;
    let mut v2 = 0;
    let mut res = 0;
    for ite in 0..2 {
        let mut q = VecDeque::new();
        let inf = 1i64 << 60;
        let mut dist = vec![inf; n];
        dist[v1] = 0;
        let mut visited = vec![false; n];
        q.push_back(v1);
        while let Some(v) = q.pop_front() {
            visited[v] = true;
            for &nv in &graph[v] {
                if dist[v] + 1 < dist[nv] {
                    dist[nv] = dist[v] + 1;
                    q.push_back(nv);
                }
            }
        }
        for i in 0..n {
            if dist[v2] < dist[i] {
                v2 = i;
            }
        }
        if ite == 1 {
            res = dist[v2] + 1;
            break;
        }
        v1 = v2;
    }
    // eprintln!("d = {}", res);
    let res = if res % 3 != 2 { "First" } else { "Second" };
    writeln!(buf, "{}", res);
    buf
}

