fn far(g: &Vec<Vec<usize>>, s: usize) -> (usize, usize) {
    let n = g.len();
    let mut dist = vec![None; n];
    let mut q = std::collections::VecDeque::new();

    q.push_back((s, 0));

    while let Some((u, dep)) = q.pop_back() {
        if dist[u].is_some() {
            continue;
        }

        dist[u] = Some(dep);

        for &v in g[u].iter() {
            if dist[v].is_some() {
                continue;
            }
            q.push_back((v, dep + 1));
        }
    }

    // dbg!(&dist);

    let mut ret = (0, 0);
    for i in 0..n {
        if let Some(d) = dist[i] {
            if d > ret.1 {
                ret = (i, d);
            }
        }
    }

    ret
}

