#[allow(dead_code)]
fn far_vertex(
    btrace: &mut [Option<usize>],
    graph: &[Vec<usize>],
    pre: Option<usize>,
    cur: usize,
) -> (usize, usize) {
    let mut ret = (cur, 0);
    for &v in &graph[cur] {
        match pre {
            Some(p) if v == p => continue,
            _ => (),
        };
        let mut tmp = far_vertex(btrace, graph, Some(cur), v);
        tmp.1 += 1;
        if tmp.1 > ret.1 {
            ret = tmp;
            btrace[v] = Some(cur);
        }
    }
    ret
}
#[doc = " returns a diameter route"]
#[allow(dead_code)]
pub fn diameter(graph: &[Vec<usize>]) -> Vec<usize> {
    let mut btrace = vec![None; graph.len()];
    let leaf = far_vertex(&mut btrace, graph, None, 0);
    btrace = vec![None; graph.len()];
    let far = far_vertex(&mut btrace, graph, None, leaf.0);
    let mut ret = vec![];
    let mut cur = Some(far.0);
    while let Some(c) = cur {
        ret.push(c);
        cur = btrace[c];
    }
    ret
}

use std::collections::VecDeque;

