fn bfs(g: &Vec<Vec<usize>>, v: usize) -> Vec<usize> {
    let n = g.len();
    let mut d = vec![n; n];
    let mut q = VecDeque::<usize>::new();
    q.push_back(v);
    d[v] = 0;
    while q.len() > 0 {
        let v = *q.front().unwrap();
        q.pop_front();
        for &u in &g[v] {
            if d[u] > d[v] + 1 {
                d[u] = d[v] + 1;
                q.push_back(u);
            }
        }
    }
    d
}

fn diameter(g: &Vec<Vec<usize>>) -> usize {
    let n = g.len();
    let d = bfs(&g, 0usize);
    let mut v = 0;
    for i in 1..n {
        if d[i] > d[v] {
            v = i;
        }
    }
    let d = bfs(&g, v);
    return *d.iter().max().unwrap();
}

