fn dfs(v: usize, p: usize, g: &Vec<Vec<usize>>) -> (usize, usize) {
    let mut res = (1, v);
    for &dst in &g[v] {
        if dst != p {
            let mut r = dfs(dst, v, g);
            r.0 += 1;
            res.set_max(r);
        }
    }
    res
