        graph[u].push(v);
        graph[v].push(u);
    }
    let r = dfs(0, usize::max_value(), &graph);
    let (len, _) = dfs(r.1, usize::max_value(), &graph);
    if len % 3 == 2 {
        println!("Second");
    } else {
        println!("First");
    }
}

