use std::str::FromStr;


fn calc_radius(cur: i32, prev: i32, n: usize, tos: &Vec<Vec<i32>>)
        -> (i32, i32) {
    let mut maxdep = 0;
    let mut maxpos = cur;
    let nexts = &tos[cur as usize];
    for next in nexts {
        if *next == prev {
            continue;
        }
        let (getdep, getpos) = calc_radius(*next, cur, n, tos);
        if maxdep < getdep + 1 {
           maxdep = getdep + 1;
           maxpos = getpos;
        }
    }
    return (maxdep, maxpos)    
}

fn main() {
    let stdin = io::stdin();
    let mut data = stdin.lock().lines();
    let n = {
        let line = data.next().unwrap().unwrap();
        usize::from_str(&line).unwrap()
    };
    let mut tos = Vec::new();
    for _ in 0..n {
        tos.push(Vec::new());
    }
    for _ in 0..((n - 1) as usize) {
        let (x, y) = {
            let line = data.next().unwrap().unwrap();
            let mut line_split = line.split(' ');
            (i32::from_str(line_split.next().unwrap()).unwrap(),
             i32::from_str(line_split.next().unwrap()).unwrap())
        };
        tos[(x - 1) as usize].push(y - 1);
        tos[(y - 1) as usize].push(x - 1);
    }
    let (_, a) = calc_radius(0, -1, n, &tos);
    let (radius, _) = calc_radius(a, -1, n, &tos);
    if radius % 3 == 1 {
        println!("Second");
    } else {
        println!("First");
    }
}

