struct Graph {
    nodes: Vec<Vec<usize>>,
}

impl Graph {
    fn new(n: usize, ab: Vec<(usize, usize)>) -> Self {
        let mut nodes = vec![Vec::new(); n+1];
        for (a, b) in ab {
            nodes[a].push(b);
            nodes[b].push(a);
        }
        Graph{
            nodes: nodes,
        }
    }

    fn dfs(&self, node: usize, parent: usize, depth: usize) -> (usize, usize) { //(node, depth)
        let mut maxd = depth;
        let mut maxn = node;
        for &next in self.nodes[node].iter() {
            if next == parent {
                continue;
            }
            let (nn, nd) = self.dfs(next, node, depth+1);
            if nd > maxd {
                maxd = nd;
                maxn = nn;
            }
        }
        (maxn,maxd)
    }
}

fn solve() {
    let n = get!(usize);
    let ab = get!(usize, usize; n-1);

    let g = Graph::new(n, ab);
    let (node, depth) = g.dfs(1, 1, 0);
    let (_, diameter) = g.dfs(node, node, 0);

    if diameter % 3 == 1 {
        println!("Second");
    } else {
        println!("First");
    }
}

