#[derive(Debug)]
pub struct TreeRec<V, E> {
    n: usize,
    graph: Vec<Vec<usize>>,
    vs: Vec<V>,
    es: Vec<E>,
}
impl<V: Clone + Default, E: Clone + Default> TreeRec<V, E> {
    pub fn new(n: usize) -> TreeRec<V, E> {
        TreeRec {
            n: n,
            graph: vec![vec![]; n],
            vs: vec![Default::default(); n],
            es: vec![],
        }
    }
    pub fn add_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(v);
        self.graph[v].push(u);
    }
    pub fn dfs(&self, u: usize, p: usize, d: usize) -> (usize, usize) {
        let mut r = (d, u);
        for i in 0..self.graph[u].len() {
            let v = self.graph[u][i];
            if v != p {
                let x = self.dfs(v, u, d + 1);
                r = std::cmp::max(r, x);
            }
        }
        r
    }
}
pub type TreeRec0 = TreeRec<Vertex, Edge>;
